static const char *
ir_arm64_leaf_sp_trace_filter(void)
{
	static const char *filter;
	static int initialized = 0;

	if (!initialized) {
		filter = getenv("TCC_TRACE_ARM64_LEAF_SP");
		initialized = 1;
	}
	return filter;
}

static int
ir_arm64_leaf_sp_trace_enabled(const IRInst *func_inst)
{
	const char *filter = ir_arm64_leaf_sp_trace_filter();

	if (!filter || !filter[0] || !func_inst || !func_inst->name)
		return 0;
	if (STRCMP(filter, "1") == 0)
		return 1;
	return strstr(func_inst->name, filter) != NULL;
}

static int
ir_arm64_leaf_sp_trace_fail(const IRInst *func_inst, const IRInst *scan,
                            int state, const char *reason)
{
	if (ir_arm64_leaf_sp_trace_enabled(func_inst)) {
		fprintf(stderr, "[arm64-leaf-sp] reject func=%s state=%d",
		        func_inst && func_inst->name ? func_inst->name : "<anon>", state);
		if (scan)
			fprintf(stderr, " inst=%d kind=%d subop=%d", scan->id, scan->kind, scan->subop);
		fprintf(stderr, " reason=%s\n", reason ? reason : "<unknown>");
	}
	return 0;
}

static void
ir_arm64_leaf_sp_trace_ok(const IRInst *func_inst)
{
	if (ir_arm64_leaf_sp_trace_enabled(func_inst)) {
		fprintf(stderr, "[arm64-leaf-sp] accept func=%s\n",
		        func_inst && func_inst->name ? func_inst->name : "<anon>");
	}
}

static int
ir_arm64_simple_leaf_trace_fail(const IRInst *func_inst, const IRInst *scan,
                                int state, const char *reason)
{
	if (ir_arm64_leaf_sp_trace_enabled(func_inst)) {
		fprintf(stderr, "[arm64-simple-leaf] reject func=%s state=%d",
		        func_inst && func_inst->name ? func_inst->name : "<anon>", state);
		if (scan)
			fprintf(stderr, " inst=%d kind=%d subop=%d", scan->id, scan->kind, scan->subop);
		fprintf(stderr, " reason=%s\n", reason ? reason : "<unknown>");
	}
	return 0;
}

static void
ir_arm64_simple_leaf_trace_ok(const IRInst *func_inst)
{
	if (ir_arm64_leaf_sp_trace_enabled(func_inst)) {
		fprintf(stderr, "[arm64-simple-leaf] accept func=%s\n",
		        func_inst && func_inst->name ? func_inst->name : "<anon>");
	}
}

static void
ir_global_lookup_reset(void)
{
	xfree(ir_global_lookup);
	ir_global_lookup = NULL;
	ir_global_lookup_count = 0;
}

static void
ir_global_lookup_insert(Global *g)
{
	if (!g || !g->name[0])
		return;
	for (int i = 0; i < ir_global_lookup_count; i++) {
		if (STRCMP(ir_global_lookup[i].global->name, g->name) == 0)
			return;
	}
	ir_global_lookup[ir_global_lookup_count].global = g;
	ir_global_lookup_count++;
}

static void
ir_global_lookup_build(void)
{
	int count = parser_global_count();
	int i;
	if (count < 1)
		count = 1;
	ir_global_lookup = xcalloc((size_t)count, sizeof(*ir_global_lookup));
	ir_global_lookup_count = 0;

	for (i = 0; i < count; i++)
		ir_global_lookup_insert(parser_global_at(i));
}

static Global *
ir_global_lookup_find(const char *name)
{
	int i;

	if (!name || !name[0])
		return NULL;
	if (!ir_global_lookup)
		ir_global_lookup_build();
	for (i = 0; i < ir_global_lookup_count; i++)
		if (STRCMP(ir_global_lookup[i].global->name, name) == 0)
			return ir_global_lookup[i].global;

	return NULL;
}

static void
irgen_reset_for_build(void)
{
	Codegen *target_cg = irgen.target_cg;

	memset(&irgen, 0, sizeof(irgen));
	irgen.target_cg = target_cg;
	irgen.next_label = 1;
	ir_global_lookup_reset();
}

void
ir_set_target_codegen(Codegen *cg)
{
	irgen.target_cg = cg;
}

