static int 
ir_global_is_extern(const char *name)
{
	Global *g = ir_global_lookup_find(name);

	return g ? g->is_dylib : 0;  /* only dylib symbols need GOT */
}

static int 
ir_global_elem_size(const char *name)
{
	Global *g = ir_global_lookup_find(name);

	if (!g)
		return 4;

	/* pointer globals and string pointer globals are 8 bytes on 64-bit targets */
	if (g->ptr_elem_size || g->is_string)
		return 8;
	return g->elem_size ? g->elem_size : 4;
}

static int 
ir_effective_load_size(const IRInst *inst)
{
	if (!inst)
		return TCC_SIZEOF_INT;
	if (inst->kind == IR_LOAD && inst->subop == IR_OP_GLOBAL)
		return ir_global_elem_size(inst->name);
	return inst->aux ? inst->aux : TCC_SIZEOF_INT;
}

