static int
ir_is_stack_builtin_call(const Node *node)
{
	return node && node->kind == ND_CALL && node->name[0] &&
	       ((!node->left &&
	         (STRCMP(node->name, "__builtin_stack_save") == 0 ||
	          STRCMP(node->name, "__builtin_stack_restore") == 0 ||
	          STRCMP(node->name, "__builtin_stack_alloc") == 0)) ||
	         STRCMP(node->name, "__builtin_va_start") == 0);
}

static int
ir_local_const_trackable_size(int size)
{
	return size == 1 || size == 2 || size == 4 || size == 8;
}

static int
ir_arm64_direct_gpr_arg_ok(const Node *arg)
{
	Type *type;

	for (;;) {
		if (!arg)
			return 0;
		if (arg->kind == ND_CAST && arg->left) {
			arg = arg->left;
			continue;
		}
		if (arg->kind == ND_COMMA && arg->right) {
			arg = arg->right;
			continue;
		}
		break;
	}

	type = arg->type;
	if (type) {
		if (type_is_fp_scalar(type) || type_is_complex(type) ||
		    type_is_struct(type) || type_is_union(type))
			return 0;
		return 1;
	}

	if (arg->returns_struct || arg->is_fp_num)
		return 0;
	return 1;
}

static int
ir_is_x64_complex_float_abi_name(const char *name)
{
	return name && STRCMP(name, "__tcc_x64_complex_float2") == 0;
}

static int
ir_is_x64_complex_double_abi_name(const char *name)
{
	return name && STRCMP(name, "__tcc_x64_complex_double2") == 0;
}

static int
ir_type_uses_x64_complex_float_abi(const Type *type)
{
	return type && type_is_complex(type) &&
	       parser_classify_aggregate_abi((Type *)type, NULL) ==
	           AGGREGATE_ABI_X64_COMPLEX_FLOAT;
}

static int
ir_type_uses_x64_complex_double_abi(const Type *type)
{
	if (!type)
		return 0;
	if (type_is_complex(type) &&
	    parser_classify_aggregate_abi((Type *)type, NULL) ==
	        AGGREGATE_ABI_X64_COMPLEX_DOUBLE)
		return 1;
	return type_is_struct(type) &&
	       ir_is_x64_complex_double_abi_name(type->struct_name) &&
	       type_sizeof(type) == 16;
}

static int
ir_node_returns_x64_complex_float_abi(const Node *node)
{
	return node && node->returns_struct &&
	       node->aggregate_abi_class == AGGREGATE_ABI_X64_COMPLEX_FLOAT;
}

static int
ir_node_returns_x64_complex_double_abi(const Node *node)
{
	return node && node->returns_struct &&
	       node->aggregate_abi_class == AGGREGATE_ABI_X64_COMPLEX_DOUBLE;
}

static int
ir_node_returns_x64_direct_complex_abi(const Node *node)
{
	return ir_node_returns_x64_complex_float_abi(node) ||
	       ir_node_returns_x64_complex_double_abi(node);
}

static int
ir_arm64_node_uses_nonbyref_aggregate_abi(const Node *node)
{
	const Node *value = node;

	if (node && node->type &&
	    type_is_struct(node->type) &&
	    (parser_classify_aggregate_abi(node->type, NULL) == AGGREGATE_ABI_INTREGS ||
	     parser_classify_aggregate_abi(node->type, NULL) == AGGREGATE_ABI_HFA))
		return 1;

	for (;;) {
		if (!value)
			return 0;
		if (value->kind == ND_CAST && value->left) {
			value = value->left;
			continue;
		}
		if (value->kind == ND_COMMA && value->right) {
			value = value->right;
			continue;
		}
		break;
	}

	if (!value || !value->type || !type_is_struct(value->type))
		return 0;
	return parser_classify_aggregate_abi(value->type, NULL) == AGGREGATE_ABI_INTREGS ||
	       parser_classify_aggregate_abi(value->type, NULL) == AGGREGATE_ABI_HFA;
}

static int
ir_arm64_call_uses_nonbyref_aggregate_abi(const Node *call)
{
	const Node *arg;

	if (!call)
		return 0;

	for (;;) {
		if (call->kind == ND_CAST && call->left) {
			call = call->left;
			continue;
		}
		break;
	}

	if (call->returns_struct &&
	    (call->aggregate_abi_class == AGGREGATE_ABI_INTREGS ||
	     call->aggregate_abi_class == AGGREGATE_ABI_HFA))
		return 1;

	for (arg = call->args; arg; arg = arg->next) {
		if (ir_arm64_node_uses_nonbyref_aggregate_abi(arg))
			return 1;
	}

	return 0;
}

static int
ir_arm64_inst_returns_scalar_gpr(const IRInst *call)
{
	if (!call)
		return 0;

	if (call->kind != IR_CALL && call->kind != IR_CALL_ACC_ARG0 &&
	    call->kind != IR_CALL_INDIRECT && call->kind != IR_CALL_PACKED_GPR)
		return 0;

	if (call->result_size == 0 || call->result_is_fp)
		return 0;

	return call->result_size <= TCC_SIZEOF_PTR;
}

static int
ir_arm64_hfa_info_type(const Type *type, int *elem_size_out, int *elem_count_out)
{
	return parser_arm64_hfa_info_type(type, elem_size_out, elem_count_out);
}

static Type *
ir_call_param_abi_type(const Node *call, int index)
{
	FuncInfo *fi;

	if (!call || call->left || !call->name[0] || index < 0)
		return NULL;
	fi = find_func(call->name);
	if (!fi || !fi->param_types || index >= fi->param_type_count)
		return NULL;
	return fi->param_types[index];
}

static Node *
ir_x64_unwrap_direct_complex_arg(IRProgram *ir, Node *arg, int emit_side_effects)
{
	for (;;) {
		if (!arg)
			return NULL;
		if (arg->kind == ND_CAST && arg->left) {
			arg = arg->left;
			continue;
		}
		if (arg->kind == ND_COMMA && arg->left && arg->right) {
			if (emit_side_effects)
				ir_stmt(ir, arg->left);
			arg = arg->right;
			continue;
		}
		break;
	}
	return arg;
}

static Node *
ir_x64_strip_direct_complex_arg(IRProgram *ir, Node *arg)
{
	return ir_x64_unwrap_direct_complex_arg(ir, arg, 1);
}

static Node *
ir_x64_peel_direct_complex_storage(Node *arg)
{
	if (arg && arg->kind == ND_ADDR && arg->left &&
	    (arg->left->kind == ND_VAR || arg->left->kind == ND_GLOBAL))
		return arg->left;
	return arg;
}

static int
ir_alloc_hidden_local_slot(int size, int align)
{
	int total;

	if (size <= 0)
		size = 8;
	if (align <= 0)
		align = 8;
	total = irgen.current_func_stack_size + irgen.hidden_local_bytes;
	total += size;
	total = ((total + align - 1) / align) * align;
	irgen.hidden_local_bytes = total - irgen.current_func_stack_size;
	return -total;
}

static const char *
ir_call_param_abi_name(const Node *call, int index)
{
	FuncInfo *fi;

	if (!call || call->left || !call->name[0] || index < 0)
		return NULL;
	fi = find_func(call->name);
	if (!fi || !fi->param_struct_names || index >= fi->param_type_count)
		return NULL;
	return fi->param_struct_names[index];
}

static void
ir_trace_call_abi(const char *phase, Node *call)
{
	FuncInfo *fi;
	Type *arg_type;
	int arg_hfa_size = 0;
	int arg_hfa_count = 0;
	const char *trace;

	trace = getenv("TCC_TRACE_IR_CALL_ABI");
	if (!trace || !trace[0] || !call || call->kind != ND_CALL || call->left || !call->name[0])
		return;

	fi = find_func(call->name);
	arg_type = call->args ? call->args->type : NULL;
	(void)ir_arm64_hfa_info_type(arg_type, &arg_hfa_size, &arg_hfa_count);
	fprintf(stderr,
	        "tcc ir: %s call=%s node_ret=%d node_abi=%d node_regs=%d node_size=%d"
	        " node_type_kind=%d arg_kind=%d arg_type_kind=%d arg_src=%d arg_hfa=%d/%d"
	        " fi=%p fi_ret=%d fi_abi=%d fi_regs=%d fi_type=%p fi_type_kind=%d fi_type_src=%d\n",
	        phase ? phase : "?",
	        call->name,
	        call->returns_struct,
	        call->aggregate_abi_class,
	        call->aggregate_abi_reg_count,
	        call->struct_return_size,
	        call->type ? call->type->kind : -1,
	        call->args ? call->args->kind : -1,
	        arg_type ? arg_type->kind : -1,
	        arg_type ? arg_type->source_kind : -1,
	        arg_hfa_size,
	        arg_hfa_count,
	        (void *)fi,
	        fi ? fi->returns_struct : -1,
	        fi ? fi->return_abi_class : -1,
	        fi ? fi->return_abi_reg_count : -1,
	        fi ? (void *)fi->return_type : NULL,
	        (fi && fi->return_type) ? fi->return_type->kind : -1,
	        (fi && fi->return_type) ? fi->return_type->source_kind : -1);
}

static void
ir_emit_arm64_direct_aggregate_return_value(IRProgram *ir, Node *value)
{
	int size;

	if (!ir || !value || !value->type || !type_is_struct(value->type))
		return;

	size = type_sizeof(value->type);
	if (size <= 0 || size > 16)
		return;

	if (value->kind == ND_VAR) {
		IRInst *inst = ir_emit_raw(ir, IR_UNOP, "arm64_ret_agg_local", NULL,
		                           value->offset, size);
		if (inst)
			inst->fixed_params = (size + (int)TCC_SIZEOF_PTR - 1) / (int)TCC_SIZEOF_PTR;
		return;
	}

	if (value->kind == ND_GLOBAL) {
		IRInst *inst = ir_emit_raw(ir, IR_UNOP, "arm64_ret_agg_global", value->name,
		                           0, size);
		if (inst)
			inst->fixed_params = (size + (int)TCC_SIZEOF_PTR - 1) / (int)TCC_SIZEOF_PTR;
	}
}

static void
ir_emit_arm64_direct_hfa_return_value(IRProgram *ir, Node *value)
{
	int elem_size;
	int elem_count;

	if (!ir || !value || !ir_arm64_hfa_info_type(value->type, &elem_size, &elem_count))
		return;

	if (value->kind == ND_VAR) {
		IRInst *inst = ir_emit_raw(ir, IR_UNOP, "arm64_ret_hfa_local", NULL,
		                           value->offset, elem_size);
		if (inst)
			inst->fixed_params = elem_count;
		return;
	}

	if (value->kind == ND_GLOBAL) {
		IRInst *inst = ir_emit_raw(ir, IR_UNOP, "arm64_ret_hfa_global", value->name,
		                           0, elem_size);
		if (inst)
			inst->fixed_params = elem_count;
	}
}

static void
ir_emit_x64_direct_complex_double_return_value(IRProgram *ir, Node *value)
{
	IRInst *inst;

	if (!ir || !value || !value->type ||
	    !ir_type_uses_x64_complex_double_abi(value->type))
		return;

	if (value->kind == ND_VAR) {
		inst = ir_emit_raw(ir, IR_UNOP, "x64_ret_fp_agg_local", NULL,
		                   value->offset, 8);
	} else if (value->kind == ND_GLOBAL) {
		inst = ir_emit_raw(ir, IR_UNOP, "x64_ret_fp_agg_global", value->name,
		                   0, 8);
	} else {
		return;
	}
	if (inst)
		inst->fixed_params = 2;
}

static int
ir_x64_emit_single_complex_double_call(IRProgram *ir, Node *call, int discard_result)
{
	Node *arg;
	Type *abi_type;
	const char *abi_name;
	IRInst *prep = NULL;
	IRInst *ci;

	if (!ir || !call || call->kind != ND_CALL || call->left || !call->name[0])
		return 0;

	arg = call->args;
	if (!arg || arg->next)
		return 0;
	arg = ir_x64_strip_direct_complex_arg(ir, arg);
	arg = ir_x64_peel_direct_complex_storage(arg);
	abi_type = ir_call_param_abi_type(call, 0);
	abi_name = ir_call_param_abi_name(call, 0);
	if (!(ir_type_uses_x64_complex_double_abi(abi_type ? abi_type : arg ? arg->type : NULL) ||
	      ir_is_x64_complex_double_abi_name(abi_name)))
		return 0;

	if (arg && (arg->kind == ND_VAR || arg->kind == ND_GLOBAL)) {
		if (arg->kind == ND_VAR) {
			prep = ir_emit_raw(ir, IR_UNOP, "x64_arg_fp_agg_local", NULL,
			                   arg->offset, 8);
		} else {
			prep = ir_emit_raw(ir, IR_UNOP, "x64_arg_fp_agg_global", arg->name,
			                   0, 8);
		}
		if (prep)
			prep->fixed_params = 2;
	} else if (arg && arg->kind == ND_CALL &&
	           ir_node_returns_x64_complex_double_abi(arg)) {
		ir_expr(ir, arg);
	} else {
		return 0;
	}

	ci = ir_emit_raw(ir, IR_CALL_PACKED_GPR, NULL, call->name, 0, discard_result);
	if (ci) {
		ci->fixed_params = func_fixed_params(call->name);
		if (ir_type_uses_x64_complex_double_abi(call->type) ||
		    ir_node_returns_x64_complex_double_abi(call)) {
			ci->result_is_fp = 1;
			ci->result_size = 16;
		}
	}
	return ci != NULL;
}

static int
ir_call_has_x64_complex_double_abi_arg(const Node *call)
{
	int index = 0;

	if (!call || call->kind != ND_CALL)
		return 0;

	for (const Node *arg = call->args; arg; arg = arg->next, index++) {
		Type *abi_type = ir_call_param_abi_type(call, index);
		const char *abi_name = ir_call_param_abi_name(call, index);
		Node *stripped = ir_x64_unwrap_direct_complex_arg(NULL, (Node *)arg, 0);

		stripped = ir_x64_peel_direct_complex_storage(stripped);

		if (ir_type_uses_x64_complex_double_abi(abi_type ? abi_type :
		                                        stripped ? stripped->type : NULL) ||
		    ir_is_x64_complex_double_abi_name(abi_name))
			return 1;
	}
	return 0;
}

static int
ir_x64_emit_mixed_complex_double_gpr_call(IRProgram *ir, Node *call, int discard_result)
{
	enum {
		IR_X64_COMPLEX_SRC_NONE = 0,
		IR_X64_COMPLEX_SRC_LOCAL,
		IR_X64_COMPLEX_SRC_GLOBAL,
		IR_X64_COMPLEX_SRC_SCRATCH
	};
	typedef struct IRX64ComplexArgSource {
		int kind;
		int offset;
		const char *name;
		Node *expr;
	} IRX64ComplexArgSource;
	Node *args[IR_SIMPLE_CALL_MAX_ARGS];
	Node *gpr_args[IR_SIMPLE_CALL_MAX_ARGS];
	IRX64ComplexArgSource complex_args[IR_SIMPLE_CALL_MAX_ARGS];
	int count = 0;
	int gpr_count = 0;
	int complex_reg_count = 0;
	int has_complex = 0;
	int fixed_params = -1;
	IRInst *ci;

	if (!ir || !call || call->kind != ND_CALL)
		return 0;

	for (Node *arg = call->args; arg; arg = arg->next) {
		Type *abi_type;
		const char *abi_name;
		Node *stripped;
		int uses_complex_double_abi;

		if (count >= IR_SIMPLE_CALL_MAX_ARGS)
			return 0;
		args[count] = arg;
		memset(&complex_args[count], 0, sizeof(complex_args[count]));
		abi_type = ir_call_param_abi_type(call, count);
		abi_name = ir_call_param_abi_name(call, count);
		stripped = ir_x64_unwrap_direct_complex_arg(ir, arg, 0);
		stripped = ir_x64_peel_direct_complex_storage(stripped);
		uses_complex_double_abi =
		    ir_type_uses_x64_complex_double_abi(abi_type ? abi_type :
		                                        stripped ? stripped->type : NULL) ||
		    ir_is_x64_complex_double_abi_name(abi_name);

		if (uses_complex_double_abi) {
			if (complex_reg_count + 2 > 8)
				return 0;
			has_complex = 1;
			if (stripped && stripped->kind == ND_VAR) {
				complex_args[count].kind = IR_X64_COMPLEX_SRC_LOCAL;
				complex_args[count].offset = stripped->offset;
				complex_args[count].expr = arg;
			} else if (stripped && stripped->kind == ND_GLOBAL) {
				complex_args[count].kind = IR_X64_COMPLEX_SRC_GLOBAL;
				complex_args[count].name = stripped->name;
				complex_args[count].expr = arg;
			} else if (stripped && stripped->kind == ND_CALL &&
			           ir_node_returns_x64_complex_double_abi(stripped)) {
				complex_args[count].kind = IR_X64_COMPLEX_SRC_SCRATCH;
				complex_args[count].expr = arg;
				complex_args[count].offset = ir_alloc_hidden_local_slot(16, 8);
			} else {
				return 0;
			}
			complex_reg_count += 2;
		} else {
			Type *arg_type = stripped ? stripped->type : NULL;

			if (arg_type &&
			    (type_is_fp_scalar(arg_type) || type_is_complex(arg_type) ||
			     type_is_struct(arg_type) || type_is_union(arg_type)))
				return 0;
			gpr_args[gpr_count++] = arg;
		}

		count++;
	}

	if (!has_complex)
		return 0;

	if (!call->left)
		fixed_params = func_fixed_params(call->name);

	for (int i = count - 1; i >= 0; i--) {
		if (complex_args[i].kind == IR_X64_COMPLEX_SRC_SCRATCH) {
			IRInst *store_inst;
			Node *stripped = ir_x64_unwrap_direct_complex_arg(ir, complex_args[i].expr, 1);

			if (!stripped || stripped->kind != ND_CALL ||
			    !ir_node_returns_x64_complex_double_abi(stripped))
				return 0;
			ir_expr(ir, stripped);
			store_inst = ir_emit_raw(ir, IR_UNOP, "x64_store_ret_fp_agg_local", NULL,
			                         complex_args[i].offset, 8);
			if (store_inst)
				store_inst->fixed_params = 2;
			else
				return 0;
		} else if (complex_args[i].kind == IR_X64_COMPLEX_SRC_LOCAL ||
		           complex_args[i].kind == IR_X64_COMPLEX_SRC_GLOBAL) {
			(void)ir_x64_unwrap_direct_complex_arg(ir, complex_args[i].expr, 1);
		} else if (complex_args[i].kind == IR_X64_COMPLEX_SRC_NONE) {
			ir_expr(ir, args[i]);
		}
	}

	if (call->left)
		ir_expr(ir, call->left);

	for (int i = 0, xmm_base = 0; i < count; i++) {
		IRInst *prep = NULL;

		switch (complex_args[i].kind) {
		case IR_X64_COMPLEX_SRC_LOCAL:
		case IR_X64_COMPLEX_SRC_SCRATCH:
			prep = ir_emit_raw(ir, IR_UNOP, "x64_arg_fp_agg_local", NULL,
			                   complex_args[i].offset, 8);
			break;
		case IR_X64_COMPLEX_SRC_GLOBAL:
			prep = ir_emit_raw(ir, IR_UNOP, "x64_arg_fp_agg_global", complex_args[i].name,
			                   0, 8);
			break;
		default:
			break;
		}
		if (prep) {
			prep->fixed_params = 2;
			prep->extra = xmm_base;
			xmm_base += 2;
		}
	}

	if (call->left) {
		ci = ir_emit_call_indirect(ir, gpr_count, discard_result);
		if (ci)
			ci->fixed_params = -1;
	} else {
		ci = ir_emit_call_direct(ir, call->name, gpr_count, discard_result);
		if (ci)
			ci->fixed_params = fixed_params;
	}
	if (ci) {
		ci->extra = complex_reg_count;
		if (ir_type_uses_x64_complex_double_abi(call->type) ||
		    ir_node_returns_x64_complex_double_abi(call)) {
			ci->result_is_fp = 1;
			ci->result_size = 16;
		} else if (call->type && type_is_fp_scalar(call->type)) {
			ci->result_is_fp = 1;
			ci->result_size = type_sizeof(call->type);
		}
	}
	return ci != NULL;
}

static int
ir_arm64_emit_single_intregs_aggregate_call(IRProgram *ir, Node *call, int discard_result)
{
	Node *arg;
	int reg_count;
	IRInst *ci;

	if (!ir || !call || call->kind != ND_CALL || call->left || !call->name[0] ||
	    call->returns_struct)
		return 0;

	arg = call->args;
	if (!arg || arg->next)
		return 0;
	if (!arg->type || !type_is_struct(arg->type))
		return 0;
	if (parser_classify_aggregate_abi(arg->type, &reg_count) != AGGREGATE_ABI_INTREGS)
		return 0;
	if (arg->kind == ND_VAR) {
		IRInst *inst = ir_emit_raw(ir, IR_UNOP, "arm64_ret_agg_local", NULL,
		                           arg->offset, type_sizeof(arg->type));
		if (inst)
			inst->fixed_params = reg_count;
	} else if (arg->kind == ND_GLOBAL) {
		IRInst *inst = ir_emit_raw(ir, IR_UNOP, "arm64_ret_agg_global", arg->name,
		                           0, type_sizeof(arg->type));
		if (inst)
			inst->fixed_params = reg_count;
	} else {
		return 0;
	}

	ci = ir_emit_raw(ir, IR_CALL_PACKED_GPR, NULL, call->name, reg_count, discard_result);
	if (ci) {
		ci->fixed_params = func_fixed_params(call->name);
		if (call->type && type_is_fp_scalar(call->type)) {
			ci->result_is_fp = 1;
			ci->result_size = type_sizeof(call->type);
		}
	}
	return ci != NULL;
}

static int
ir_arm64_emit_single_hfa_aggregate_call(IRProgram *ir, Node *call, int discard_result)
{
	Node *arg;
	Type *abi_type;
	const char *abi_name;
	int elem_size;
	int elem_count;
	IRInst *prep;
	IRInst *ci;

	if (!ir || !call || call->kind != ND_CALL || call->left || !call->name[0])
		return 0;
	if (STRCMP(call->name, "check_complex_float_mix") == 0 ||
	    STRCMP(call->name, "check_complex_double_mix") == 0 ||
	    STRCMP(call->name, "consume_complex_float_mix") == 0 ||
	    STRCMP(call->name, "consume_complex_double_mix") == 0)
		fprintf(stderr, "mixed-hfa: enter %s\n", call->name);

	arg = call->args;
	if (!arg || arg->next)
		return 0;

	for (;;) {
		if (arg->kind == ND_CAST && arg->left) {
			arg = arg->left;
			continue;
		}
		if (arg->kind == ND_COMMA && arg->left && arg->right) {
			ir_stmt(ir, arg->left);
			arg = arg->right;
			continue;
	}
	break;
	}

	abi_type = ir_call_param_abi_type(call, 0);
	abi_name = ir_call_param_abi_name(call, 0);
	if (!arg || !(ir_arm64_hfa_info_type(abi_type ? abi_type : arg->type,
	                                     &elem_size, &elem_count) ||
	              parser_arm64_hfa_info_name(abi_name, &elem_size, &elem_count)))
		return 0;
	if (arg->kind == ND_VAR) {
		prep = ir_emit_raw(ir, IR_UNOP, "arm64_arg_hfa_local", NULL,
		                   arg->offset, elem_size);
	} else if (arg->kind == ND_GLOBAL) {
		prep = ir_emit_raw(ir, IR_UNOP, "arm64_arg_hfa_global", arg->name,
		                   0, elem_size);
	} else {
		return 0;
	}
	if (prep)
		prep->fixed_params = elem_count;

	ci = ir_emit_raw(ir, IR_CALL_PACKED_GPR, NULL, call->name, elem_count, discard_result);
	if (ci) {
		ci->fixed_params = func_fixed_params(call->name);
		if (call->type && type_is_fp_scalar(call->type)) {
			ci->result_is_fp = 1;
			ci->result_size = type_sizeof(call->type);
		}
	}
	return ci != NULL;
}

static Node *
ir_arm64_strip_direct_hfa_arg(IRProgram *ir, Node *arg, Node **prefix_stmt_out)
{
	if (prefix_stmt_out)
		*prefix_stmt_out = NULL;
	for (;;) {
		if (!arg)
			return NULL;
		if (arg->kind == ND_CAST && arg->left) {
			arg = arg->left;
			continue;
		}
		if (arg->kind == ND_COMMA && arg->left && arg->right &&
		    arg->left->kind == ND_BLOCK) {
			if (prefix_stmt_out)
				*prefix_stmt_out = arg->left;
			arg = arg->right;
			continue;
		}
		(void)ir;
		return arg;
	}
}

static int
ir_arm64_emit_mixed_hfa_gpr_call(IRProgram *ir, Node *call, int discard_result)
{
	Node **args = NULL;
	IRSimpleCallArg simple_args[IR_SIMPLE_CALL_MAX_ARGS];
	const char *hfa_names[IR_SIMPLE_CALL_MAX_ARGS];
	Node *hfa_prefix_stmts[IR_SIMPLE_CALL_MAX_ARGS];
	int hfa_offsets[IR_SIMPLE_CALL_MAX_ARGS];
	int hfa_sizes[IR_SIMPLE_CALL_MAX_ARGS];
	int hfa_counts[IR_SIMPLE_CALL_MAX_ARGS];
	int hfa_fp_bases[IR_SIMPLE_CALL_MAX_ARGS];
	int hfa_is_global[IR_SIMPLE_CALL_MAX_ARGS];
	int count;
	int simple_count = 0;
	int hfa_count = 0;
	int fp_reg = 0;
	int fixed_params;
	int i;
	IRInst *ci;

	if (!ir || !call || call->kind != ND_CALL ||
	    (!call->left && !call->name[0]))
		return 0;

	count = 0;
	for (Node *arg = call->args; arg; arg = arg->next)
		count++;
	if (count <= 0 || count > IR_SIMPLE_CALL_MAX_ARGS)
		return 0;

	args = (Node **)xcalloc((size_t)count, sizeof(Node *));
	for (i = 0; i < count; i++)
		memset(&simple_args[i], 0, sizeof(simple_args[i]));
	{
		Node *arg = call->args;
		for (i = 0; i < count; i++) {
			args[i] = arg;
			arg = arg ? arg->next : NULL;
		}
	}

	for (i = 0; i < count; i++) {
		Node *prefix_stmt = NULL;
		Node *arg = ir_arm64_strip_direct_hfa_arg(ir, args[i], &prefix_stmt);
		Type *abi_type = ir_call_param_abi_type(call, i);
		const char *abi_name = ir_call_param_abi_name(call, i);
		int elem_size;
		int elem_count;

		if (!arg) {
			simple_count = -1;
			break;
		}
		if (ir_arm64_hfa_info_type(abi_type ? abi_type : arg->type,
		                           &elem_size, &elem_count) ||
		    parser_arm64_hfa_info_name(abi_name, &elem_size, &elem_count)) {
			if (fp_reg + elem_count > 8) {
				simple_count = -1;
				break;
			}
			if (arg->kind != ND_VAR && arg->kind != ND_GLOBAL) {
				simple_count = -1;
				break;
			}
			hfa_names[hfa_count] = arg->kind == ND_GLOBAL ? arg->name : NULL;
			hfa_prefix_stmts[hfa_count] = prefix_stmt;
			hfa_offsets[hfa_count] = arg->kind == ND_VAR ? arg->offset : 0;
			hfa_sizes[hfa_count] = elem_size;
			hfa_counts[hfa_count] = elem_count;
			hfa_fp_bases[hfa_count] = fp_reg;
			hfa_is_global[hfa_count] = (arg->kind == ND_GLOBAL);
			hfa_count++;
			fp_reg += elem_count;
			continue;
		}
		if (arg->type && type_is_fp_scalar(arg->type)) {
			simple_count = -1;
			break;
		}
		if (ir_arm64_node_uses_nonbyref_aggregate_abi(arg) ||
		    !ir_try_capture_simple_call_arg(ir, &simple_args[simple_count], args[i])) {
			simple_count = -1;
			break;
		}
		simple_count++;
	}

	if (simple_count < 0 || fp_reg == 0) {
		xfree(args);
		return 0;
	}

	for (i = 0; i < hfa_count; i++) {
		IRInst *prep;

		if (hfa_prefix_stmts[i])
			ir_stmt(ir, hfa_prefix_stmts[i]);
		if (hfa_is_global[i]) {
			prep = ir_emit_raw(ir, IR_UNOP, "arm64_arg_hfa_global",
			                   hfa_names[i], 0, hfa_sizes[i]);
		} else {
			prep = ir_emit_raw(ir, IR_UNOP, "arm64_arg_hfa_local", NULL,
			                   hfa_offsets[i], hfa_sizes[i]);
		}
		if (prep) {
			prep->fixed_params = hfa_counts[i];
			prep->extra = hfa_fp_bases[i];
		}
	}

	if (call->left) {
		ir_expr(ir, call->left);
		ci = ir_emit_call_indirect(ir, simple_count, discard_result);
		if (ci) {
			ci->fixed_params = -1;
			ci->simple_call_arg_count = (uint8_t)simple_count;
			for (i = 0; i < simple_count; i++)
				ci->simple_call_args[i] = simple_args[i];
			if (call->type && type_is_fp_scalar(call->type)) {
				ci->result_is_fp = 1;
				ci->result_size = type_sizeof(call->type);
			}
		}
	} else {
		fixed_params = func_fixed_params(call->name);
		ci = ir_emit_call_direct(ir, call->name, simple_count, discard_result);
		if (ci) {
			ci->fixed_params = fixed_params;
			ci->simple_call_arg_count = (uint8_t)simple_count;
			for (i = 0; i < simple_count; i++)
				ci->simple_call_args[i] = simple_args[i];
			if (call->type && type_is_fp_scalar(call->type)) {
				ci->result_is_fp = 1;
				ci->result_size = type_sizeof(call->type);
			}
		}
	}

	xfree(args);
	return ci != NULL;
}

static int
ir_emit_arm64_direct_hfa_call_to_lvalue(IRProgram *ir, Node *dst, Node *call)
{
	Node **args = NULL;
	int count;
	int fixed_params;
	int elem_size;
	int elem_count;
	unsigned int fp_arg_mask = 0;
	unsigned int fp_arg_double_mask = 0;
	IRInst *ci;
	IRInst *store_inst;

	if (!ir || !dst || !call || call->kind != ND_CALL || call->left || !call->name[0] ||
	    !call->returns_struct || call->aggregate_abi_class != AGGREGATE_ABI_HFA ||
	    !dst->type || !ir_arm64_hfa_info_type(dst->type, &elem_size, &elem_count))
		return 0;
	if (dst->kind != ND_VAR && dst->kind != ND_GLOBAL)
		return 0;

	count = 0;
	for (Node *arg = call->args; arg; arg = arg->next)
		count++;

	args = (Node **)xcalloc((size_t)(count > 0 ? count : 1), sizeof(Node *));
	{
		int i = 0;
		for (Node *arg = call->args; arg; arg = arg->next) {
			if (ir_arm64_node_uses_nonbyref_aggregate_abi(arg)) {
				xfree(args);
				return 0;
			}
			args[i++] = arg;
		}
	}

	if (count == 1) {
		Node *arg = ir_arm64_strip_direct_hfa_arg(ir, args[0], NULL);
		Type *abi_type = ir_call_param_abi_type(call, 0);
		const char *abi_name = ir_call_param_abi_name(call, 0);
		int arg_elem_size = 0;
		int arg_elem_count = 0;

		if (arg &&
		    (ir_arm64_hfa_info_type(abi_type ? abi_type : arg->type,
		                            &arg_elem_size, &arg_elem_count) ||
		     parser_arm64_hfa_info_name(abi_name, &arg_elem_size, &arg_elem_count)) &&
		    (arg->kind == ND_VAR || arg->kind == ND_GLOBAL)) {
			IRInst *prep;

			if (arg->kind == ND_VAR) {
				prep = ir_emit_raw(ir, IR_UNOP, "arm64_arg_hfa_local", NULL,
				                   arg->offset, arg_elem_size);
			} else {
				prep = ir_emit_raw(ir, IR_UNOP, "arm64_arg_hfa_global", arg->name,
				                   0, arg_elem_size);
			}
			if (prep)
				prep->fixed_params = arg_elem_count;
			ci = ir_emit_raw(ir, IR_CALL_PACKED_GPR, NULL, call->name, arg_elem_count, 0);
			if (ci)
				ci->fixed_params = func_fixed_params(call->name);

			if (dst->kind == ND_VAR) {
				store_inst = ir_emit_raw(ir, IR_UNOP, "arm64_store_ret_hfa_local", NULL,
				                         dst->offset, elem_size);
			} else {
				store_inst = ir_emit_raw(ir, IR_UNOP, "arm64_store_ret_hfa_global", dst->name,
				                         0, elem_size);
			}
			if (store_inst)
				store_inst->fixed_params = elem_count;

			xfree(args);
			return store_inst != NULL;
		}
	}

	ir_collect_call_fp_arg_masks(args, count, &fp_arg_mask, &fp_arg_double_mask);
	for (int i = count - 1; i >= 0; i--)
		ir_expr(ir, args[i]);

	fixed_params = func_fixed_params(call->name);
	ci = ir_emit_call_direct(ir, call->name, count, 0);
	if (ci) {
		ci->fixed_params = fixed_params;
		ci->fp_arg_mask = fp_arg_mask;
		ci->fp_arg_double_mask = fp_arg_double_mask;
	}

	if (dst->kind == ND_VAR) {
		store_inst = ir_emit_raw(ir, IR_UNOP, "arm64_store_ret_hfa_local", NULL,
		                         dst->offset, elem_size);
	} else {
		store_inst = ir_emit_raw(ir, IR_UNOP, "arm64_store_ret_hfa_global", dst->name,
		                         0, elem_size);
	}
	if (store_inst)
		store_inst->fixed_params = elem_count;

	xfree(args);
	return store_inst != NULL;
}

static int
ir_emit_x64_direct_complex_double_call_to_lvalue(IRProgram *ir, Node *dst, Node *call)
{
	Node *arg;
	Node **args = NULL;
	int count;
	int fixed_params;
	unsigned int fp_arg_mask = 0;
	unsigned int fp_arg_double_mask = 0;
	IRInst *ci;
	IRInst *store_inst;

	if (!ir || !dst || !call || call->kind != ND_CALL || call->left || !call->name[0] ||
	    !call->type || !ir_type_uses_x64_complex_double_abi(call->type) ||
	    !dst->type || !ir_type_uses_x64_complex_double_abi(dst->type))
		return 0;
	if (dst->kind != ND_VAR && dst->kind != ND_GLOBAL)
		return 0;

	arg = call->args;
	if (arg && !arg->next) {
		Node *stripped = ir_x64_strip_direct_complex_arg(ir, arg);

		if (stripped && (stripped->kind == ND_VAR || stripped->kind == ND_GLOBAL)) {
			IRInst *prep;

			if (stripped->kind == ND_VAR) {
				prep = ir_emit_raw(ir, IR_UNOP, "x64_arg_fp_agg_local", NULL,
				                   stripped->offset, 8);
			} else {
				prep = ir_emit_raw(ir, IR_UNOP, "x64_arg_fp_agg_global", stripped->name,
				                   0, 8);
			}
			if (prep)
				prep->fixed_params = 2;
			goto emit_call;
		}
		if (stripped && stripped->kind == ND_CALL &&
		    ir_node_returns_x64_complex_double_abi(stripped)) {
			ir_expr(ir, stripped);
			goto emit_call;
		}
	}

	count = 0;
	for (arg = call->args; arg; arg = arg->next)
		count++;
	args = (Node **)xcalloc((size_t)(count > 0 ? count : 1), sizeof(Node *));
	{
		int i = 0;
		for (arg = call->args; arg; arg = arg->next)
			args[i++] = arg;
	}
	ir_collect_call_fp_arg_masks(args, count, &fp_arg_mask, &fp_arg_double_mask);
	for (int i = count - 1; i >= 0; i--)
		ir_expr(ir, args[i]);

emit_call:
	if (call->left) {
		ir_expr(ir, call->left);
		ci = ir_emit_call_indirect(ir, count, 0);
		if (ci) {
			ci->fixed_params = -1;
			ci->fp_arg_mask = fp_arg_mask;
			ci->fp_arg_double_mask = fp_arg_double_mask;
		}
	} else {
		fixed_params = func_fixed_params(call->name);
		ci = ir_emit_call_direct(ir, call->name, count, 0);
		if (ci) {
			ci->fixed_params = fixed_params;
			ci->fp_arg_mask = fp_arg_mask;
			ci->fp_arg_double_mask = fp_arg_double_mask;
		}
	}
	if (ci) {
		ci->result_is_fp = 1;
		ci->result_size = 16;
	}

	if (dst->kind == ND_VAR) {
		store_inst = ir_emit_raw(ir, IR_UNOP, "x64_store_ret_fp_agg_local", NULL,
		                         dst->offset, 8);
	} else {
		store_inst = ir_emit_raw(ir, IR_UNOP, "x64_store_ret_fp_agg_global", dst->name,
		                         0, 8);
	}
	if (store_inst)
		store_inst->fixed_params = 2;
	if (args)
		xfree(args);
	return store_inst != NULL;
}

static int
ir_emit_arm64_direct_aggregate_call_to_lvalue(IRProgram *ir, Node *dst, Node *call)
{
	Node **args;
	int count;
	int fixed_params;
	int size;
	unsigned int fp_arg_mask = 0;
	unsigned int fp_arg_double_mask = 0;
	IRInst *ci;
	IRInst *store_inst;

	if (!ir || !dst || !call || call->kind != ND_CALL || call->left || !call->name[0] ||
	    !call->returns_struct || call->aggregate_abi_class != AGGREGATE_ABI_INTREGS ||
	    !dst->type || !type_is_struct(dst->type))
		return 0;

	size = type_sizeof(dst->type);
	if (size <= 0 || size > 16)
		return 0;
	if (dst->kind != ND_VAR && dst->kind != ND_GLOBAL)
		return 0;

	count = 0;
	for (Node *arg = call->args; arg; arg = arg->next)
		count++;

	args = (Node **)xcalloc((size_t)(count > 0 ? count : 1), sizeof(Node *));
	{
		int i = 0;
		for (Node *arg = call->args; arg; arg = arg->next) {
			if (ir_arm64_node_uses_nonbyref_aggregate_abi(arg)) {
				xfree(args);
				return 0;
			}
			args[i++] = arg;
		}
	}

	ir_collect_call_fp_arg_masks(args, count, &fp_arg_mask, &fp_arg_double_mask);
	fixed_params = func_fixed_params(call->name);

	for (int i = count - 1; i >= 0; i--)
		ir_expr(ir, args[i]);

	ci = ir_emit_call_direct(ir, call->name, count, 1);
	if (ci) {
		ci->fixed_params = fixed_params;
		ci->fp_arg_mask = fp_arg_mask;
		ci->fp_arg_double_mask = fp_arg_double_mask;
		ci->result_size = size;
	}

	if (dst->kind == ND_VAR) {
		store_inst = ir_emit_raw(ir, IR_UNOP, "arm64_store_ret_agg_local", NULL,
		                         dst->offset, size);
	} else {
		store_inst = ir_emit_raw(ir, IR_UNOP, "arm64_store_ret_agg_global", dst->name,
		                         0, size);
	}
	if (store_inst)
		store_inst->fixed_params = (size + (int)TCC_SIZEOF_PTR - 1) / (int)TCC_SIZEOF_PTR;

	xfree(args);
	return store_inst != NULL;
}

static void
ir_inst_clear_simple_call_args(IRInst *inst)
{
	int i;

	if (!inst)
		return;
	for (i = 0; i < IR_SIMPLE_CALL_MAX_ARGS; i++) {
		xfree(inst->simple_call_args[i].name);
		inst->simple_call_args[i].name = NULL;
		inst->simple_call_args[i].kind = IR_SIMPLE_CALL_ARG_NONE;
		memset(inst->simple_call_args[i].reserved, 0,
		       sizeof(inst->simple_call_args[i].reserved));
		inst->simple_call_args[i].value = 0;
		inst->simple_call_args[i].aux = 0;
		inst->simple_call_args[i].aux2 = 0;
	}
	inst->simple_call_arg_count = 0;
}

static int
ir_simple_call_arg_is_unsigned(const IRSimpleCallArg *arg)
{
	if (!arg)
		return 0;
	return arg->reserved[0] != 0;
}

static void
ir_simple_call_arg_set_signedness(IRSimpleCallArg *arg, int is_unsigned)
{
	if (!arg)
		return;
	arg->reserved[0] = (uint8_t)(is_unsigned ? 1 : 0);
}

static int
ir_emit_arm64_simple_local_arg_acc(Codegen *cg, IRSimpleCallArg *arg)
{
	int size;

	if (!cg || !arg)
		return 0;

	size = arg->aux ? arg->aux : TCC_SIZEOF_PTR;
	if ((size == 1 || size == 2 || size == 4) && cg->emit_load_local_casted) {
		cg->emit_load_local_casted((int)arg->value, size,
		                           ir_simple_call_arg_is_unsigned(arg));
		return 1;
	}

	if (!cg->emit_load_local_sized)
		return 0;
	cg->emit_load_local_sized((int)arg->value, size);
	return 1;
}

static int
ir_emit_arm64_simple_local_arg_to_arg(Codegen *cg, IRSimpleCallArg *arg, int index)
{
	int size;

	if (!cg || !arg || index < 0 || index > 7)
		return 0;

	size = arg->aux ? arg->aux : TCC_SIZEOF_PTR;
	if ((size == 1 || size == 2 || size == 4) &&
	    cg->emit_load_local_casted && cg->emit_acc_to_arg) {
		cg->emit_load_local_casted((int)arg->value, size,
		                           ir_simple_call_arg_is_unsigned(arg));
		cg->emit_acc_to_arg(index);
		return 1;
	}

	if (!cg->emit_load_local_to_arg)
		return 0;
	cg->emit_load_local_to_arg(index, (int)arg->value, size);
	return 1;
}

static int
ir_is_positive_simple_mul_imm(long imm)
{
	return imm > 1 && imm <= 65535;
}

static int
ir_try_capture_simple_call_arg_local_mul_imm(IRSimpleCallArg *out, const Node *arg)
{
	const Node *node;
	const Node *lhs;
	const Node *rhs;
	const Node *local = NULL;
	const Node *imm_node = NULL;
	long imm;
	int offset = 0;
	int size = 0;
	int is_unsigned = 0;
	int add = 0;

	if (!out || !arg)
		return 0;

	node = ir_peel_simple_call_arg_casts(arg);
	if (!node)
		node = arg;
	if (!node || node->kind != ND_MUL || !node->type ||
	    type_is_fp_scalar(node->type))
		return 0;

	lhs = ir_peel_simple_call_arg_casts(node->left);
	rhs = ir_peel_simple_call_arg_casts(node->right);
	if (!lhs)
		lhs = node->left;
	if (!rhs)
		rhs = node->right;
	if (!lhs || !rhs)
		return 0;

	if (lhs->kind == ND_NUM && !lhs->is_fp_num) {
		imm_node = lhs;
		local = rhs;
	} else if (rhs->kind == ND_NUM && !rhs->is_fp_num) {
		imm_node = rhs;
		local = lhs;
	} else {
		return 0;
	}

	imm = imm_node->long_value;
	if (!ir_is_positive_simple_mul_imm(imm) ||
	    !ir_match_simple_local_index(local, &offset, &size, &is_unsigned, &add) ||
	    add != 0)
		return 0;

	out->kind = IR_SIMPLE_CALL_ARG_LOCAL_MUL_IMM;
	out->value = offset;
	out->aux = size;
	out->aux2 = (int)imm;
	ir_simple_call_arg_set_signedness(out, is_unsigned);
	return 1;
}

static int
ir_try_eval_simple_call_arg_const(const Node *node, long *value_out)
{
	long lhs;
	long rhs;

	if (!node || !value_out)
		return 0;
	if (node->kind == ND_NUM && !node->is_fp_num) {
		*value_out = node->long_value;
		return 1;
	}
	if (node->kind == ND_CAST && node->left &&
	    node->type && !type_is_fp_scalar(node->type)) {
		long value;
		int cast_size;
		int cast_unsigned;

		if (!ir_try_eval_simple_call_arg_const(node->left, &value))
			return 0;
		cast_size = type_sizeof(node->type);
		cast_unsigned = type_is_unsigned(node->type);
		if (cast_size == 1) {
			long v = value & 0xff;
			value = (!cast_unsigned && (v & 0x80)) ? (v - 0x100) : v;
		} else if (cast_size == 2) {
			long v = value & 0xffff;
			value = (!cast_unsigned && (v & 0x8000)) ? (v - 0x10000) : v;
		} else if (cast_size == 4) {
			long v = value & 0xffffffffL;
			value = (!cast_unsigned && (v & 0x80000000L)) ? (v - 0x100000000L) : v;
		}
		*value_out = value;
		return 1;
	}
	if (!node->left || !node->right)
		return 0;
	if (!ir_try_eval_simple_call_arg_const(node->left, &lhs) ||
	    !ir_try_eval_simple_call_arg_const(node->right, &rhs))
		return 0;
	switch (node->kind) {
	case ND_ADD:
		*value_out = lhs + rhs;
		return 1;
	case ND_SUB:
		*value_out = lhs - rhs;
		return 1;
	default:
		return 0;
	}
}

static void
ir_emit_arm64_mul_reg_imm(int reg_index, long imm)
{
	if (reg_index < 0 || reg_index > 7 || !ir_is_positive_simple_mul_imm(imm))
		ICE("bad arm64 mul-reg-imm");

	if ((imm & (imm - 1)) == 0) {
		int shift = 0;

		while ((1L << shift) != imm)
			shift++;
		printf("    lsl x%d, x%d, #%d\n", reg_index, reg_index, shift);
		return;
	}

	printf("    mov x16, #%ld\n", imm);
	printf("    mul x%d, x%d, x16\n", reg_index, reg_index);
}

#define IR_SIMPLE_CALL_ARG_PACK_I32(dst, value) \
	do { \
		(dst)[0] = (uint8_t)((value) & 0xff); \
		(dst)[1] = (uint8_t)(((value) >> 8) & 0xff); \
		(dst)[2] = (uint8_t)(((value) >> 16) & 0xff); \
		(dst)[3] = (uint8_t)(((value) >> 24) & 0xff); \
	} while (0)

#define IR_SIMPLE_CALL_ARG_UNPACK_I32(src) \
	((int)((unsigned)(src)[0] | \
	       ((unsigned)(src)[1] << 8) | \
	       ((unsigned)(src)[2] << 16) | \
	       ((unsigned)(src)[3] << 24)))

#define IR_SIMPLE_CALL_ARG_PACK_I16(dst, value) \
	do { \
		(dst)[0] = (uint8_t)((value) & 0xff); \
		(dst)[1] = (uint8_t)(((value) >> 8) & 0xff); \
	} while (0)

#define IR_SIMPLE_CALL_ARG_UNPACK_I16(src) \
	((((unsigned)(src)[1] & 0x80u) != 0) ? \
	     ((int)((unsigned)(src)[0] | ((unsigned)(src)[1] << 8)) - 0x10000) : \
	     (int)((unsigned)(src)[0] | ((unsigned)(src)[1] << 8)))

#define IR_SIMPLE_CALL_ARG_UNPACK_I8(value) \
	((((unsigned)(value) & 0x80u) != 0) ? \
	     ((int)((unsigned)(value) & 0xffu) - 0x100) : \
	     (int)((unsigned)(value) & 0xffu))

static const Node *
ir_peel_simple_call_arg_casts(const Node *node)
{
	while (node && node->kind == ND_CAST) {
		int dst_size;
		int src_size;

		if (!node->left || !node->type || !node->left->type)
			return NULL;
		if (type_is_fp_scalar(node->type) || type_is_fp_scalar(node->left->type))
			return NULL;
		dst_size = type_sizeof(node->type);
		src_size = type_sizeof(node->left->type);
		if (dst_size != src_size)
			return NULL;
		if (dst_size != 4 && dst_size != TCC_SIZEOF_PTR)
			return NULL;
		node = node->left;
	}
	return node;
}

static int
ir_simple_arg_node_size(const Node *node)
{
	if (!node)
		return 0;
	if (node->is_pointer || (node->type && type_is_pointer(node->type)))
		return TCC_SIZEOF_PTR;
	return ir_lvalue_size((Node *)node);
}

static int
ir_match_simple_local_index(const Node *node, int *offset_out, int *size_out,
                            int *is_unsigned_out, int *add_out)
{
	const Node *core;
	long add = 0;
	int size;

	if (offset_out)
		*offset_out = 0;
	if (size_out)
		*size_out = 0;
	if (is_unsigned_out)
		*is_unsigned_out = 0;
	if (add_out)
		*add_out = 0;
	if (!node)
		return 0;

	core = ir_peel_simple_call_arg_casts(node);
	if (!core)
		core = node;

	if (core->kind == ND_ADD || core->kind == ND_SUB) {
		int op_kind = core->kind;
		const Node *lhs = ir_peel_simple_call_arg_casts(core->left);
		const Node *rhs = ir_peel_simple_call_arg_casts(core->right);

		if (!lhs)
			lhs = core->left;
		if (!rhs)
			rhs = core->right;
		if (rhs && rhs->kind == ND_NUM && !rhs->is_fp_num) {
			core = lhs;
			add = rhs->long_value;
			if (op_kind == ND_SUB)
				add = -add;
		} else if (core->kind == ND_ADD &&
		           lhs && lhs->kind == ND_NUM && !lhs->is_fp_num) {
			core = rhs;
			add = lhs->long_value;
		} else {
			return 0;
		}
	}

	if (!core)
		return 0;
	if (core->kind != ND_VAR &&
	    !(core->kind == ND_MEMBER && !ir_global_lookup_find(core->name)))
		return 0;
	if (core->type && type_is_fp_scalar(core->type))
		return 0;
	size = ir_simple_arg_node_size(core);
	if (size != 1 && size != 2 && size != 4 && size != TCC_SIZEOF_PTR)
		return 0;
	if (add < -128 || add > 127)
		return 0;

	if (offset_out)
		*offset_out = core->offset;
	if (size_out)
		*size_out = size;
	if (is_unsigned_out)
		*is_unsigned_out = core->type ? type_is_unsigned(core->type) : core->is_unsigned;
	if (add_out)
		*add_out = (int)add;
	return 1;
}

static int
ir_try_capture_simple_call_arg_ptr_indexed(IRSimpleCallArg *out, const Node *arg)
{
	const Node *node;
	const Node *ptr_expr = NULL;
	const Node *base = NULL;
	const Node *index = NULL;
	int is_load = 0;
	int base_local = 0;
	int base_global_member = 0;
	int base_offset = 0;
	int index_offset = 0;
	int index_size = 0;
	int index_unsigned = 0;
	int index_add = 0;
	int load_size = 0;
	int cast_size = 0;
	int is_unsigned = 0;
	int elem_size = 0;

	if (!out || !arg)
		return 0;

	node = ir_peel_simple_call_arg_casts(arg);
	if (!node)
		node = arg;

	if (node->kind == ND_DEREF) {
		is_load = 1;
		ptr_expr = ir_peel_simple_call_arg_casts(node->left);
		if (!ptr_expr)
			ptr_expr = node->left;
	} else if (node->kind == ND_MEMBER_PTR && !node->is_array_field && node->offset == 0) {
		is_load = 1;
		ptr_expr = ir_peel_simple_call_arg_casts(node->left);
		if (!ptr_expr)
			ptr_expr = node->left;
	} else if (node->kind == ND_ADD && node->is_pointer) {
		ptr_expr = node;
	} else {
		return 0;
	}

	if (!ptr_expr || ptr_expr->kind != ND_ADD || !ptr_expr->is_pointer)
		return 0;

	{
		const Node *lhs = ir_peel_simple_call_arg_casts(ptr_expr->left);
		const Node *rhs = ir_peel_simple_call_arg_casts(ptr_expr->right);

		if (!lhs)
			lhs = ptr_expr->left;
		if (!rhs)
			rhs = ptr_expr->right;
		if ((lhs->kind == ND_VAR || lhs->kind == ND_MEMBER ||
		     lhs->kind == ND_GLOBAL) &&
		    ir_match_simple_local_index(rhs, &index_offset, &index_size,
		                                &index_unsigned, &index_add)) {
			base = lhs;
			index = rhs;
		} else if ((rhs->kind == ND_VAR || rhs->kind == ND_MEMBER ||
		            rhs->kind == ND_GLOBAL) &&
		           ir_match_simple_local_index(lhs, &index_offset, &index_size,
		                                       &index_unsigned, &index_add)) {
			base = rhs;
			index = lhs;
		}
	}

	if (!base || !index)
		return 0;

	if ((base->kind == ND_VAR ||
	     (base->kind == ND_MEMBER && !ir_global_lookup_find(base->name))) &&
	    (base->is_pointer || (base->type && type_is_pointer(base->type)))) {
		base_local = 1;
		base_offset = base->offset;
	} else if ((base->kind == ND_GLOBAL ||
	            (base->kind == ND_MEMBER && ir_global_lookup_find(base->name))) &&
	           (base->is_pointer ||
	            (base->type && (type_is_pointer(base->type) ||
	                            type_is_array(base->type))))) {
		base_global_member = 1;
		base_offset = (base->kind == ND_GLOBAL) ? 0 : base->offset;
	} else {
		return 0;
	}

	elem_size = ptr_expr->elem_size ? ptr_expr->elem_size : 1;
	if (elem_size < 1 || elem_size > 2147483647)
		return 0;

	if (is_load) {
		load_size = ir_simple_arg_node_size(node);
		if (load_size != 4 && load_size != TCC_SIZEOF_PTR)
			return 0;
		cast_size = load_size;
		is_unsigned = node->type ? type_is_unsigned(node->type) : node->is_unsigned;
	} else {
		if (index_add != 0)
			return 0;
		if (!(node->is_pointer || (node->type && type_is_pointer(node->type)) ||
		      (node->type && type_is_array(node->type))))
			return 0;
	}

	memset(out, 0, sizeof(*out));
	out->value = base_offset;
	out->aux = index_offset;
	out->aux2 = elem_size;
	out->reserved[0] = (uint8_t)index_size;
	out->reserved[1] = (uint8_t)(index_unsigned ? 1 : 0);
	out->reserved[2] = (uint8_t)(int8_t)index_add;
	out->reserved[3] = (uint8_t)load_size;
	out->reserved[4] = (uint8_t)cast_size;
	out->reserved[5] = (uint8_t)(is_unsigned ? 1 : 0);
	out->reserved[6] = (uint8_t)(base_global_member ? ir_global_is_extern(base->name) : 0);
	out->reserved[7] = (uint8_t)((base->is_pointer ||
	                             (base->type && type_is_pointer(base->type))) ? 1 : 0);

	if (base_local)
		out->kind = is_load ? IR_SIMPLE_CALL_ARG_LOCAL_PTR_INDEXED_LOAD
		                   : IR_SIMPLE_CALL_ARG_LOCAL_PTR_INDEXED_ADDR;
	else
		out->kind = is_load ? IR_SIMPLE_CALL_ARG_GLOBAL_MEMBER_INDEXED_LOAD
		                   : IR_SIMPLE_CALL_ARG_GLOBAL_MEMBER_INDEXED_ADDR;

	if (base_global_member)
		out->name = xstrdup(base->name);
	return 1;
}

static int
ir_try_capture_simple_call_arg(IRProgram *ir, IRSimpleCallArg *out, const Node *arg)
{
	const Node *ptr_base;
	const Node *node;
	long const_value;
	int size;
	int ptr_offset;

	if (!ir || !out || !arg)
		return 0;

	memset(out, 0, sizeof(*out));
	node = ir_peel_simple_call_arg_casts(arg);
	if (!node)
		node = arg;
	if (ir_try_eval_simple_call_arg_const(node, &const_value)) {
		out->kind = IR_SIMPLE_CALL_ARG_CONST;
		out->value = const_value;
		return 1;
	}
	if (node->kind == ND_CAST && node->left &&
	    node->left->kind == ND_NUM && !node->left->is_fp_num &&
	    node->type && !type_is_fp_scalar(node->type)) {
		long value = node->left->long_value;
		int cast_size = type_sizeof(node->type);
		int cast_unsigned = type_is_unsigned(node->type);

		if (cast_size == 1) {
			long v = value & 0xff;
			value = (!cast_unsigned && (v & 0x80)) ? (v - 0x100) : v;
		} else if (cast_size == 2) {
			long v = value & 0xffff;
			value = (!cast_unsigned && (v & 0x8000)) ? (v - 0x10000) : v;
		} else if (cast_size == 4) {
			long v = value & 0xffffffffL;
			value = (!cast_unsigned && (v & 0x80000000L)) ? (v - 0x100000000L) : v;
		}
		out->kind = IR_SIMPLE_CALL_ARG_CONST;
		out->value = value;
		return 1;
	}
	if (node->kind == ND_CAST && node->left && node->type &&
	    type_is_pointer(node->type)) {
		const Node *base = node->left;

		if (!base)
			base = node->left;
		if (base->kind == ND_STRING) {
			ir_add_string_len_width(ir, base->string_label, base->string_value,
			                        base->string_len,
			                        base->string_width ? base->string_width : 1);
			out->kind = IR_SIMPLE_CALL_ARG_STRING;
			out->value = base->string_label;
			return 1;
		}
		if (base->kind == ND_VAR && base->type && type_is_array(base->type)) {
			out->kind = IR_SIMPLE_CALL_ARG_ADDR_LOCAL;
			out->value = base->offset;
			return 1;
		}
		if (base->kind == ND_MEMBER && base->type && type_is_array(base->type)) {
			if (ir_global_lookup_find(base->name)) {
				out->kind = IR_SIMPLE_CALL_ARG_ADDR_GLOBAL_OFFSET;
				out->name = xstrdup(base->name);
				out->value = base->offset;
				return 1;
			}
			out->kind = IR_SIMPLE_CALL_ARG_ADDR_LOCAL;
			out->value = base->offset;
			return 1;
		}
		if (base->kind == ND_GLOBAL && base->type && type_is_array(base->type)) {
			out->kind = IR_SIMPLE_CALL_ARG_ADDR_GLOBAL;
			out->name = xstrdup(base->name);
			return 1;
		}
	}
	if (node->kind == ND_CAST && node->left && node->type &&
	    !type_is_fp_scalar(node->type)) {
		const Node *base = node->left;
		int dst_size = type_sizeof(node->type);

		if (dst_size == 4 || dst_size == TCC_SIZEOF_PTR) {
			if (base->kind == ND_VAR) {
				size = ir_simple_arg_node_size(base);
				if (size == dst_size) {
					out->kind = IR_SIMPLE_CALL_ARG_LOCAL;
					out->value = base->offset;
					out->aux = size;
					ir_simple_call_arg_set_signedness(out,
					                                  type_is_unsigned(node->type));
					return 1;
				}
			}
			if (base->kind == ND_MEMBER) {
				size = ir_lvalue_size((Node *)base);
				if (size == dst_size) {
					if (ir_global_lookup_find(base->name)) {
						out->kind = IR_SIMPLE_CALL_ARG_GLOBAL_MEMBER;
						out->name = xstrdup(base->name);
						out->value = base->offset;
						out->aux = size;
						out->aux2 = ir_global_is_extern(base->name);
						ir_simple_call_arg_set_signedness(out,
						                                  type_is_unsigned(node->type));
						return 1;
					}
					out->kind = IR_SIMPLE_CALL_ARG_LOCAL;
					out->value = base->offset;
					out->aux = size;
					ir_simple_call_arg_set_signedness(out,
					                                  type_is_unsigned(node->type));
					return 1;
				}
			}
			if (base->kind == ND_GLOBAL) {
				size = ir_simple_arg_node_size(base);
				if (size == dst_size) {
					out->kind = IR_SIMPLE_CALL_ARG_LOAD_GLOBAL;
					out->name = xstrdup(base->name);
					out->aux = size;
					out->aux2 = ir_global_is_extern(base->name);
					ir_simple_call_arg_set_signedness(out,
					                                  type_is_unsigned(node->type));
					return 1;
				}
			}
		}
	}
	if (ir_try_capture_simple_call_arg_ptr_indexed(out, node))
		return 1;
	if (ir_try_capture_simple_call_arg_local_mul_imm(out, node))
		return 1;
	if (ir_const_ptr_byte_offset(node, &ptr_base, &ptr_offset)) {
		ptr_base = ir_peel_simple_call_arg_casts(ptr_base);
		if (!ptr_base)
			ptr_base = node;
		if ((ptr_base->kind == ND_VAR ||
		     (ptr_base->kind == ND_MEMBER &&
		      !ir_global_lookup_find(ptr_base->name))) &&
		    (ptr_base->is_pointer ||
		     (ptr_base->type && type_is_pointer(ptr_base->type)))) {
			out->kind = IR_SIMPLE_CALL_ARG_LOCAL_PTR_OFFSET_ADDR;
			out->value = ptr_base->offset;
			out->aux = ptr_offset;
			return 1;
		}
		if (ptr_base->kind == ND_GLOBAL &&
		    (ptr_base->is_pointer ||
		     (ptr_base->type && (type_is_pointer(ptr_base->type) ||
		                         type_is_array(ptr_base->type))))) {
			out->kind = IR_SIMPLE_CALL_ARG_ADDR_GLOBAL_OFFSET;
			out->name = xstrdup(ptr_base->name);
			out->value = ptr_offset;
			return 1;
		}
		if (ptr_base->kind == ND_MEMBER &&
		    ir_global_lookup_find(ptr_base->name) &&
		    (ptr_base->is_pointer ||
		     (ptr_base->type && (type_is_pointer(ptr_base->type) ||
		                         type_is_array(ptr_base->type))))) {
			out->kind = IR_SIMPLE_CALL_ARG_ADDR_GLOBAL_OFFSET;
			out->name = xstrdup(ptr_base->name);
			out->value = ptr_base->offset + ptr_offset;
			return 1;
		}
	}
	switch (node->kind) {
	case ND_NUM:
		if (node->is_fp_num)
			return 0;
		out->kind = IR_SIMPLE_CALL_ARG_CONST;
		out->value = node->long_value;
		return 1;

	case ND_STRING:
		ir_add_string_len_width(ir, node->string_label, node->string_value,
		                        node->string_len,
		                        node->string_width ? node->string_width : 1);
		out->kind = IR_SIMPLE_CALL_ARG_STRING;
		out->value = node->string_label;
		return 1;

	case ND_VAR:
		if (node->type && type_is_array(node->type)) {
			out->kind = IR_SIMPLE_CALL_ARG_ADDR_LOCAL;
			out->value = node->offset;
			return 1;
		}
		size = ir_simple_arg_node_size(node);
		if (size != 4 && size != TCC_SIZEOF_PTR)
			return 0;
		out->kind = IR_SIMPLE_CALL_ARG_LOCAL;
		out->value = node->offset;
		out->aux = size;
		ir_simple_call_arg_set_signedness(
		    out, node->type ? type_is_unsigned(node->type) : node->is_unsigned);
		return 1;

	case ND_MEMBER:
		if (node->is_array_field) {
			if (ir_global_lookup_find(node->name)) {
				out->kind = IR_SIMPLE_CALL_ARG_ADDR_GLOBAL_OFFSET;
				out->name = xstrdup(node->name);
				out->value = node->offset;
				return 1;
			}
			out->kind = IR_SIMPLE_CALL_ARG_ADDR_LOCAL;
			out->value = node->offset;
			return 1;
		}
		size = ir_simple_arg_node_size(node);
		if (size != 4 && size != TCC_SIZEOF_PTR)
			return 0;
		if (ir_global_lookup_find(node->name)) {
			out->kind = IR_SIMPLE_CALL_ARG_GLOBAL_MEMBER;
			out->name = xstrdup(node->name);
			out->value = node->offset;
			out->aux = size;
			out->aux2 = ir_global_is_extern(node->name);
			ir_simple_call_arg_set_signedness(
			    out, node->type ? type_is_unsigned(node->type) : node->is_unsigned);
			return 1;
		}
		out->kind = IR_SIMPLE_CALL_ARG_LOCAL;
		out->value = node->offset;
		out->aux = size;
		ir_simple_call_arg_set_signedness(
		    out, node->type ? type_is_unsigned(node->type) : node->is_unsigned);
		return 1;

	case ND_GLOBAL:
		if (node->type && type_is_array(node->type)) {
			out->kind = IR_SIMPLE_CALL_ARG_ADDR_GLOBAL;
			out->name = xstrdup(node->name);
			return 1;
		}
		size = ir_simple_arg_node_size(node);
		if (size != 4 && size != TCC_SIZEOF_PTR)
			return 0;
		out->kind = IR_SIMPLE_CALL_ARG_LOAD_GLOBAL;
		out->name = xstrdup(node->name);
		out->aux = size;
		out->aux2 = ir_global_is_extern(node->name);
		ir_simple_call_arg_set_signedness(
		    out, node->type ? type_is_unsigned(node->type) : node->is_unsigned);
		return 1;

	case ND_FUNC_ADDR:
		out->kind = IR_SIMPLE_CALL_ARG_FUNCADDR;
		out->name = xstrdup(node->name);
		return 1;

	case ND_ADDR:
		if (!node->left)
			return 0;
		if (node->left->kind == ND_VAR) {
			out->kind = IR_SIMPLE_CALL_ARG_ADDR_LOCAL;
			out->value = node->left->offset;
			return 1;
		}
		if (node->left->kind == ND_MEMBER && !ir_global_lookup_find(node->left->name)) {
			out->kind = IR_SIMPLE_CALL_ARG_ADDR_LOCAL;
			out->value = node->left->offset;
			return 1;
		}
		if (node->left->kind == ND_MEMBER && ir_global_lookup_find(node->left->name)) {
			out->kind = IR_SIMPLE_CALL_ARG_ADDR_GLOBAL_OFFSET;
			out->name = xstrdup(node->left->name);
			out->value = node->left->offset;
			return 1;
		}
		if (node->left->kind == ND_GLOBAL) {
			out->kind = IR_SIMPLE_CALL_ARG_ADDR_GLOBAL;
			out->name = xstrdup(node->left->name);
			return 1;
		}
		if (node->left->kind == ND_FUNC_ADDR) {
			out->kind = IR_SIMPLE_CALL_ARG_FUNCADDR;
			out->name = xstrdup(node->left->name);
			return 1;
		}
		return 0;

	case ND_MEMBER_PTR:
	{
		const Node *base = ir_peel_simple_call_arg_casts(node->left);

		if (!base)
			base = node->left;
		if (!base)
			return 0;
		if (node->is_array_field) {
			if ((base->kind == ND_VAR ||
			     (base->kind == ND_MEMBER &&
			      !ir_global_lookup_find(base->name))) &&
			    (base->is_pointer ||
			     (base->type && type_is_pointer(base->type)))) {
				out->kind = IR_SIMPLE_CALL_ARG_LOCAL_PTR_OFFSET_ADDR;
				out->value = base->offset;
				out->aux = node->offset;
				return 1;
			}
			if (base->kind == ND_GLOBAL &&
			    (base->is_pointer ||
			     (base->type && type_is_pointer(base->type)))) {
				out->kind = IR_SIMPLE_CALL_ARG_LOAD_GLOBAL_OFFSET_ADDR;
				out->name = xstrdup(base->name);
				out->value = node->offset;
				out->aux = ir_global_is_extern(base->name);
				return 1;
			}
			if (base->kind == ND_MEMBER &&
			    ir_global_lookup_find(base->name) &&
			    (base->is_pointer ||
			     (base->type && type_is_pointer(base->type)))) {
				out->kind = IR_SIMPLE_CALL_ARG_GLOBAL_MEMBER_PTR_OFFSET_ADDR;
				out->name = xstrdup(base->name);
				out->value = base->offset;
				out->aux = node->offset;
				out->aux2 = ir_global_is_extern(base->name);
				return 1;
			}
			return 0;
		}
		size = node->elem_size ? node->elem_size : ir_lvalue_size((Node *)node);
		if ((size != 4 && size != TCC_SIZEOF_PTR) || node->is_array_field)
			return 0;
		if (base->kind != ND_VAR && !(base->kind == ND_MEMBER &&
		                              !ir_global_lookup_find(base->name)))
		{
			const Node *root;
			int root_offset;

			if (base->kind != ND_MEMBER_PTR)
				return 0;
			root = ir_peel_simple_call_arg_casts(base->left);
			if (!root)
				root = base->left;
			if (!root ||
			    (root->kind != ND_VAR &&
			     !(root->kind == ND_MEMBER && !ir_global_lookup_find(root->name))))
				return 0;
			if ((base->elem_size ? base->elem_size : ir_lvalue_size((Node *)base)) !=
			    TCC_SIZEOF_PTR)
				return 0;
			root_offset = root->offset;
			if ((long)(int16_t)node->offset != node->offset)
				return 0;
			out->kind = IR_SIMPLE_CALL_ARG_LOCAL_PTR_MEMBER_MEMBER;
			out->value = root_offset;
			out->aux = base->offset;
			out->aux2 = size;
			IR_SIMPLE_CALL_ARG_PACK_I16(&out->reserved[0], (int)node->offset);
			return 1;
		}
		out->kind = IR_SIMPLE_CALL_ARG_LOCAL_PTR_MEMBER;
		out->value = base->offset;
		out->aux = node->offset;
		out->aux2 = size;
		return 1;
	}

	default:
		return 0;
	}
}

static int
ir_emit_stack_builtin_call(IRProgram *ir, const Node *node, int discard_result)
{
	if (!ir_is_stack_builtin_call(node))
		return 0;

	if (STRCMP(node->name, "__builtin_stack_save") == 0) {
		ir_emit_unary_op(ir, "stack_save");
		if (discard_result)
			ir_emit_pop(ir);
		return 1;
	}

	if (STRCMP(node->name, "__builtin_stack_restore") == 0) {
		if (!node->args || node->args->next)
			ICE("__builtin_stack_restore expects one argument");
		ir_expr(ir, node->args);
		ir_emit_unary_op(ir, "stack_restore");
		return 1;
	}

	if (STRCMP(node->name, "__builtin_stack_alloc") == 0) {
		if (!node->args || node->args->next)
			ICE("__builtin_stack_alloc expects one argument");
		ir_expr(ir, node->args);
		ir_emit_unary_op(ir, "stack_alloc");
		if (discard_result)
			ir_emit_pop(ir);
		return 1;
	}

	if (STRCMP(node->name, "__builtin_va_start") == 0) {
		/* __builtin_va_start(ap, last): the macro wraps this as
		 * ((ap) = __builtin_va_start(ap, last)), so we just need to
		 * leave the va_list base pointer in acc. Arguments are ignored
		 * here — the base is derived from the enclosing function's
		 * register save area (x64) set up in the prologue. */
		ir_emit_unary_op(ir, "va_start");
		if (discard_result)
			ir_emit_pop(ir);
		return 1;
	}

	return 0;
}

static int
ir_const_global_byte_offset(const Node *node, int *offset_out)
{
	if (!node || node->kind != ND_GLOBAL_INDEX || !node->is_array_field || !node->left)
		return 0;
	if (node->left->kind != ND_NUM)
		return 0;
	if (offset_out)
		*offset_out = (int)node->left->long_value;
	return 1;
}

static int
ir_const_ptr_byte_offset(const Node *node, const Node **base_out, int *offset_out)
{
	const Node *base = NULL;
	const Node *cn = NULL;
	long offset;
	int scale;

	if (base_out)
		*base_out = NULL;
	if (offset_out)
		*offset_out = 0;
	if (!node)
		return 0;

	if (node->kind == ND_ADD) {
		if (node->left && node->left->kind == ND_NUM && !node->left->is_fp_num) {
			cn = node->left;
			base = node->right;
		} else if (node->right && node->right->kind == ND_NUM && !node->right->is_fp_num) {
			cn = node->right;
			base = node->left;
		}
	} else if (node->kind == ND_SUB) {
		if (node->right && node->right->kind == ND_NUM && !node->right->is_fp_num) {
			cn = node->right;
			base = node->left;
		}
	}
	if (!base || !cn)
		return 0;

	scale = node->elem_size ? node->elem_size : 1;
	offset = cn->long_value * scale;
	if (node->kind == ND_SUB)
		offset = -offset;
	if (offset < -2147483647L - 1L || offset > 2147483647L)
		return 0;

	if (base_out)
		*base_out = base;
	if (offset_out)
		*offset_out = (int)offset;
	return 1;
}

static void
ir_local_const_index_info(const Node *node, int *offset_out, int *size_out)
{
	int elem_size;

	if (offset_out)
		*offset_out = 0;
	if (size_out)
		*size_out = 0;
	if (!node || node->kind != ND_INDEX || !node->left)
		return;
	if (node->left->kind != ND_NUM || node->left->is_fp_num)
		return;
	if (node->is_array_field || (node->type && type_is_array(node->type)))
		return;
	if (node->type && type_is_fp_scalar(node->type))
		return;

	elem_size = node->is_pointer ? TCC_SIZEOF_PTR :
	            (node->elem_size ? node->elem_size : TCC_SIZEOF_INT);
	if (!(elem_size == 1 || elem_size == 2 || elem_size == 4 || elem_size == 8))
		return;

	if (offset_out)
		*offset_out = node->offset + (int)(node->left->long_value * elem_size);
	if (size_out)
		*size_out = elem_size;
}

static void
ir_reject_floating_expr(IRProgram *ir, const Node *node)
{
	if (node && node->line > 0) {
		const char *file = lexer_filename_name(node->filename_id);
		Debug(1, "[IR] reject floating expr func=%s at %s:%d kind=%d\n",
		      irgen.current_func_name[0] ? irgen.current_func_name : "<none>",
		      file ? file : "<unknown>", node->line, node->kind);
	} else {
		Debug(1, "[IR] reject floating expr func=%s at <unknown>\n",
		      irgen.current_func_name[0] ? irgen.current_func_name : "<none>");
	}
	ir_mark_unsupported(ir, "floating-point expressions are not implemented yet");
	ir_emit_unsupported_unop(ir);
}

static unsigned long long
ir_fp_literal_bits(const Node *node)
{
	double value;

	if (!node || !node->string_value)
		return 0;

	value = strtod(node->string_value, NULL);
	if (node->type && node->type->kind == TY_FLOAT) {
		union {
			double d;
			unsigned long long u;
		} bits;
		bits.d = value;
		return tcc_double_bits_to_float_bits(bits.u);
	} else {
		union {
			double d;
			unsigned long long u;
		} bits;
		bits.d = value;
		return bits.u;
	}
}

static int
ir_node_can_promote_integer_to_float(const Node *node)
{
	return node && node->type && type_is_integer(node->type) &&
	       (!ir_node_uses_floating(node) || ir_node_allows_raw_floating(node));
}

static int
ir_binary_fp_operand_size(const Node *node)
{
	int size = 0;

	if (!node)
		return 0;
	if (node->left && node->left->type && ir_type_is_raw_floating_scalar(node->left->type))
		size = type_sizeof(node->left->type);
	if (node->right && node->right->type && ir_type_is_raw_floating_scalar(node->right->type)) {
		int rsize = type_sizeof(node->right->type);
		if (size == 0 || rsize > size)
			size = rsize;
	}
	return size;
}

static int
ir_truth_fp_size(const Node *node)
{
	if (!node)
		return 0;
	if (node->type && ir_type_is_raw_floating_scalar(node->type))
		return type_sizeof(node->type);
	return ir_raw_floating_expr_size(node);
}

static int
ir_node_allows_floating_truth(const Node *node)
{
	return node &&
	       (!ir_node_uses_floating(node) || ir_node_allows_raw_floating(node));
}

static int
ir_raw_floating_expr_size(const Node *node)
{
	int a, b;

	if (!node)
		return 0;
	if (node->type && ir_type_is_raw_floating_scalar(node->type))
		return type_sizeof(node->type);

	switch (node->kind) {
	case ND_NEG:
		return ir_raw_floating_expr_size(node->left);
	case ND_COMMA:
		return ir_raw_floating_expr_size(node->right);
	case ND_COND:
		a = ir_raw_floating_expr_size(node->then_body);
		b = ir_raw_floating_expr_size(node->else_body);
		return a == b ? a : 0;
	default:
		return 0;
	}
}

static int
ir_type_is_raw_floating_scalar(const Type *type)
{
	int size;

	if (!type || !type_is_fp_scalar(type))
		return 0;
	size = type_sizeof(type);
	return size == 4 || size == 8;
}

static int
ir_call_has_floating_args(const Node *node)
{
	const Node *arg;

	if (!node)
		return 0;
	for (arg = node->args; arg; arg = arg->next) {
		if (arg->is_fp_num)
			return 1;
		if (arg->type && type_is_fp_scalar(arg->type))
			return 1;
	}
	return 0;
}

static int
ir_call_supports_raw_floating_args(const Node *node)
{
	const Node *arg;
	int int_reg = 0;
	int fp_reg = 0;
	int count = 0;
	int fixed_params;
	int has_fp_arg = 0;

	if (!node || node->kind != ND_CALL || node->left || !node->name[0])
		return 0;
	fixed_params = func_fixed_params(node->name);

	for (arg = node->args; arg; arg = arg->next) {
		count++;
		if (count > 32)
			return 0;
		if (arg->type && type_is_fp_scalar(arg->type)) {
			has_fp_arg = 1;
			if (!ir_node_allows_raw_floating(arg))
				return 0;
			if (fixed_params < 0 || count <= fixed_params) {
				fp_reg++;
				if (fp_reg > 8)
					return 0;
			}
		} else {
			if (fixed_params < 0 || count <= fixed_params) {
				int_reg++;
				if (int_reg > 8)
					return 0;
			}
		}
	}

	return has_fp_arg;
}

static int
ir_call_supports_raw_floating_indirect_args(const Node *node)
{
	const Node *arg;
	int int_reg = 0;
	int fp_reg = 0;
	int count = 0;
	int has_fp_arg = 0;

	if (!node || node->kind != ND_CALL || !node->left)
		return 0;

	for (arg = node->args; arg; arg = arg->next) {
		count++;
		if (count > 32)
			return 0;
		if (arg->type && type_is_fp_scalar(arg->type)) {
			has_fp_arg = 1;
			if (!ir_node_allows_raw_floating(arg))
				return 0;
			fp_reg++;
			if (fp_reg > 8)
				return 0;
		} else {
			int_reg++;
			if (int_reg > 8)
				return 0;
		}
	}

	return has_fp_arg;
}

static void
ir_collect_call_fp_arg_masks(Node **args, int count,
                             unsigned int *fp_mask_out,
                             unsigned int *fp_double_mask_out)
{
	unsigned int fp_mask = 0;
	unsigned int fp_double_mask = 0;
	int i;

	for (i = 0; i < count; i++) {
		const Type *type = args[i] ? args[i]->type : NULL;
		int elem_size;
		int elem_count;
		if (type && ir_arm64_hfa_info_type(type, &elem_size, &elem_count))
			continue;
		if (type && ir_type_uses_x64_complex_float_abi(type)) {
			fp_mask |= (1u << i);
			fp_double_mask |= (1u << i);
			continue;
		}
		if (!type || !type_is_fp_scalar(type))
			continue;
		fp_mask |= (1u << i);
		if (type_sizeof(type) == 8)
			fp_double_mask |= (1u << i);
	}

	if (fp_mask_out)
		*fp_mask_out = fp_mask;
	if (fp_double_mask_out)
		*fp_double_mask_out = fp_double_mask;
}

static int
ir_node_allows_raw_floating(const Node *node)
{
	if (!node)
		return 1;
	if (!ir_node_uses_floating(node))
		return 1;

	switch (node->kind) {
	case ND_NUM:
		return node->is_fp_num && ir_type_is_raw_floating_scalar(node->type);

	case ND_NEG:
		return node->left &&
		       ir_raw_floating_expr_size(node) != 0 &&
		       ir_node_allows_raw_floating(node->left);

	case ND_VAR:
	case ND_GLOBAL:
	case ND_MEMBER:
		return ir_type_is_raw_floating_scalar(node->type);

	case ND_DEREF:
	case ND_INDEX:
	case ND_GLOBAL_INDEX:
	case ND_MEMBER_PTR:
		return ir_type_is_raw_floating_scalar(node->type) &&
		       (!node->left || !ir_node_uses_floating(node->left) ||
		        ir_node_allows_raw_floating(node->left));

	case ND_ASSIGN:
		return node->left && node->right &&
		       ir_type_is_raw_floating_scalar(node->left->type) &&
		       ir_type_is_raw_floating_scalar(node->right->type) &&
		       type_sizeof(node->left->type) == type_sizeof(node->right->type) &&
		       ir_node_allows_raw_floating(node->left) &&
		       ir_node_allows_raw_floating(node->right);

	case ND_NOT:
		return ir_node_allows_floating_truth(node->left);

	case ND_LOGICAL_AND:
	case ND_LOGICAL_OR:
		return ir_node_allows_floating_truth(node->left) &&
		       ir_node_allows_floating_truth(node->right);

	case ND_PRE_INC:
	case ND_PRE_DEC:
	case ND_POST_INC:
	case ND_POST_DEC:
		return node->left &&
		       ir_type_is_raw_floating_scalar(node->left->type) &&
		       ir_node_allows_raw_floating(node->left);

	case ND_CALL:
		if (ir_call_has_floating_args(node))
			return !node->returns_struct &&
			       (node->left
			        ? ir_call_supports_raw_floating_indirect_args(node)
			        : ir_call_supports_raw_floating_args(node));
		return ir_type_is_raw_floating_scalar(node->type) &&
		       !node->returns_struct &&
		       !ir_call_has_floating_args(node);

	case ND_ADDR:
		return node->left && ir_node_allows_raw_floating(node->left);

	case ND_COND:
		return ir_node_allows_floating_truth(node->cond) &&
		       node->then_body && node->else_body &&
		       (!ir_node_uses_floating(node->then_body) ||
		        ir_node_allows_raw_floating(node->then_body)) &&
		       (!ir_node_uses_floating(node->else_body) ||
		        ir_node_allows_raw_floating(node->else_body));

	case ND_COMMA:
		return node->right &&
		       (!node->left || !ir_node_uses_floating(node->left) ||
		        ir_node_allows_raw_floating(node->left)) &&
		       (!ir_node_uses_floating(node->right) ||
		        ir_node_allows_raw_floating(node->right));

	case ND_ADD:
	case ND_SUB:
	case ND_MUL:
	case ND_DIV:
	case ND_EQ:
	case ND_NE:
	case ND_LT:
	case ND_LE:
	case ND_GT:
	case ND_GE:
		if (!node->left || !node->right)
			return 0;
		if (ir_raw_floating_expr_size(node->left) &&
		    ir_raw_floating_expr_size(node->right))
			return ir_node_allows_raw_floating(node->left) &&
			       ir_node_allows_raw_floating(node->right);
		if (ir_raw_floating_expr_size(node->left) &&
		    ir_node_can_promote_integer_to_float(node->right))
			return ir_node_allows_raw_floating(node->left);
		if (ir_raw_floating_expr_size(node->right) &&
		    ir_node_can_promote_integer_to_float(node->left))
			return ir_node_allows_raw_floating(node->right);
		return 0;

	case ND_CAST:
		if (ir_type_is_raw_floating_scalar(node->type) &&
		    node->left && ir_raw_floating_expr_size(node->left) != 0 &&
		    ir_node_allows_raw_floating(node->left))
			return 1;
		if (ir_type_is_raw_floating_scalar(node->type) &&
		    node->left && ir_node_can_promote_integer_to_float(node->left))
			return 1;
		return node->type && type_is_integer(node->type) &&
		       node->left && ir_type_is_raw_floating_scalar(node->left->type) &&
		       ir_node_allows_raw_floating(node->left);

	default:
		return 0;
	}
}

static int
ir_node_uses_floating(const Node *node)
{
	Node *arg;

	if (!node)
		return 0;
	if (node->kind == ND_ADDR) {
		if (!node->left)
			return 0;
		if (node->left->kind == ND_MEMBER_PTR || node->left->kind == ND_MEMBER)
			return ir_node_uses_floating(node->left->left);
		return ir_node_uses_floating(node->left);
	}
	if (node->is_fp_num)
		return 1;
	if (node->type && type_is_fp_scalar(node->type))
		return 1;
	if (node->left && node->left->type && type_is_fp_scalar(node->left->type))
		return 1;
	if (node->right && node->right->type && type_is_fp_scalar(node->right->type))
		return 1;
	if (node->cond && node->cond->type && type_is_fp_scalar(node->cond->type))
		return 1;
	if (node->inc && node->inc->type && type_is_fp_scalar(node->inc->type))
		return 1;
	for (arg = node->args; arg; arg = arg->next) {
		if (arg->is_fp_num)
			return 1;
		if (arg->type && type_is_fp_scalar(arg->type))
			return 1;
	}
	return 0;
}

static void
ir_add_unsupported_function(IRProgram *ir, const char *name, const char *reason)
{
	if (!ir || !name || !name[0])
		return;

	for (int i = 0; i < ir->unsupported_func_count; i++) {
		if (STRCMP(ir->unsupported_funcs[i].name, name) == 0)
			return;
	}

	if (ir->unsupported_func_count >= ir->unsupported_func_cap) {
		int new_cap = ir->unsupported_func_cap ? ir->unsupported_func_cap * 2 : 8;
		ir->unsupported_funcs = xrealloc(ir->unsupported_funcs,
		                                 sizeof(*ir->unsupported_funcs) * (size_t)new_cap);
		ir->unsupported_func_cap = new_cap;
	}

	ir->unsupported_funcs[ir->unsupported_func_count].name = xstrdup(name);
	ir->unsupported_funcs[ir->unsupported_func_count].reason = xstrdup(reason ? reason : "");
	ir->unsupported_func_count++;
}

static void
ir_mark_unsupported(IRProgram *ir, const char *what)
{
	ir->unsupported_count++;

	if (ir->unsupported_reason[0] == '\0')
		STRNCPY(ir->unsupported_reason, what, sizeof(ir->unsupported_reason) - 1);

	if (irgen.current_func_name[0])
		ir_add_unsupported_function(ir, irgen.current_func_name, what);
	else
		ir->unsupported_outside_functions = 1;

	/* Emit a no-op to keep the virtual stack balanced.
	 * Every call site that produces a value needs this; the few that
	 * return a label ID instead are harmless (they have no stack effect). */
	ir_emit_unsupported_unop(ir);
}

static IREmitProfile g_ir_emit_profile;

void
ir_emit_profile_reset(void)
{
	memset(&g_ir_emit_profile, 0, sizeof(g_ir_emit_profile));
}

void
ir_emit_profile_get(IREmitProfile *out)
{
	if (!out)
		return;
	*out = g_ir_emit_profile;
}

int 
ir_has_unsupported(IRProgram *program)
{
	return program && program->unsupported_count > 0;
}

const char *
ir_unsupported_reason(IRProgram *program)
{
	if (!program || program->unsupported_reason[0] == '\0')
		return "";
	return program->unsupported_reason;
}

int
ir_has_unsupported_outside_functions(IRProgram *program)
{
	return program && program->unsupported_outside_functions;
}

int
ir_unsupported_function_count(IRProgram *program)
{
	return program ? program->unsupported_func_count : 0;
}

const char *
ir_unsupported_function_name(IRProgram *program, int index)
{
	if (!program || index < 0 || index >= program->unsupported_func_count)
		return NULL;
	return program->unsupported_funcs[index].name;
}

const char *
ir_unsupported_function_reason(IRProgram *program, int index)
{
	if (!program || index < 0 || index >= program->unsupported_func_count)
		return NULL;
	return program->unsupported_funcs[index].reason;
}

int
ir_program_label_limit(IRProgram *program)
{
	int extra_user_labels = 0;

	if (!program)
		return 0;
	if (program->cached_program_label_limit > 0)
		return program->cached_program_label_limit;

	for (IRInst *inst = program->head; inst; inst = inst->next) {
		if (inst->kind == IR_LABEL &&
		    inst->op[0] == '\0' &&
		    inst->name[0] != '\0')
			extra_user_labels++;
	}

	program->cached_program_label_limit = program->next_label_limit + extra_user_labels;
	return program->cached_program_label_limit;
}

int
ir_function_is_supported(IRProgram *program, const char *name)
{
	if (!program || !name || !name[0])
		return 0;
	if (program->unsupported_outside_functions)
		return 0;
	for (int i = 0; i < program->unsupported_func_count; i++) {
		if (STRCMP(program->unsupported_funcs[i].name, name) == 0)
			return 0;
	}
	return 1;
}

static void
ir_program_function_spans_append(IRProgram *program, IRInst *start, IRInst *end)
{
	IRFunctionSpan *slot;
	int new_cap;

	if (!program || !start || start->kind != IR_LABEL || start->subop != IR_OP_FUNC)
		return;

	if (program->function_span_count >= program->function_span_cap) {
		new_cap = program->function_span_cap ? program->function_span_cap * 2 : 64;
		program->function_spans = xrealloc(program->function_spans,
		                                   sizeof(*program->function_spans) * (size_t)new_cap);
		program->function_span_cap = new_cap;
	}

	slot = &program->function_spans[program->function_span_count++];
	slot->name = start->name ? xstrdup(start->name) : xstrdup("");
	slot->start = start;
	slot->end = end;
}

static void
ir_program_build_function_spans(IRProgram *program)
{
	IRInst *func_start = NULL;

	if (!program || program->function_span_count > 0)
		return;

	for (IRInst *inst = program->head; inst; inst = inst->next) {
		if (inst->kind != IR_LABEL || inst->subop != IR_OP_FUNC)
			continue;
		if (func_start)
			ir_program_function_spans_append(program, func_start, inst);
		func_start = inst;
	}

	if (func_start)
		ir_program_function_spans_append(program, func_start, NULL);
}

static IRSubOp
ir_op_to_subop(const char *op)
{
	if (!op || !op[0]) return IR_OP_NONE;
	switch (op[0]) {
	case 'a':
		if (STRCMP(op, "add") == 0)          return IR_OP_ADD;
		if (STRCMP(op, "and") == 0)          return IR_OP_AND;
		if (STRCMP(op, "add_offset") == 0)   return IR_OP_ADD_OFFSET;
		if (STRCMP(op, "addr_local") == 0)   return IR_OP_ADDR_LOCAL;
		if (STRCMP(op, "addr_global") == 0)  return IR_OP_ADDR_GLOBAL;
		if (STRCMP(op, "addr_gidx") == 0)    return IR_OP_ADDR_GIDX;
		if (STRCMP(op, "addr_indexed") == 0) return IR_OP_ADDR_INDEXED;
		if (STRCMP(op, "arm64_ret_agg_local") == 0) return IR_OP_ARM64_RET_AGG_LOCAL;
		if (STRCMP(op, "arm64_ret_agg_global") == 0) return IR_OP_ARM64_RET_AGG_GLOBAL;
		if (STRCMP(op, "arm64_store_ret_agg_local") == 0) return IR_OP_ARM64_STORE_RET_AGG_LOCAL;
		if (STRCMP(op, "arm64_store_ret_agg_global") == 0) return IR_OP_ARM64_STORE_RET_AGG_GLOBAL;
		if (STRCMP(op, "arm64_ret_hfa_local") == 0) return IR_OP_ARM64_RET_HFA_LOCAL;
		if (STRCMP(op, "arm64_ret_hfa_global") == 0) return IR_OP_ARM64_RET_HFA_GLOBAL;
		if (STRCMP(op, "arm64_store_ret_hfa_local") == 0) return IR_OP_ARM64_STORE_RET_HFA_LOCAL;
		if (STRCMP(op, "arm64_store_ret_hfa_global") == 0) return IR_OP_ARM64_STORE_RET_HFA_GLOBAL;
		if (STRCMP(op, "arm64_arg_hfa_local") == 0) return IR_OP_ARM64_ARG_HFA_LOCAL;
		if (STRCMP(op, "arm64_arg_hfa_global") == 0) return IR_OP_ARM64_ARG_HFA_GLOBAL;
		if (STRCMP(op, "acc_to_tmp") == 0)   return IR_OP_ACC_TO_TMP;
		if (STRCMP(op, "acc_to_saved") == 0) return IR_OP_ACC_TO_SAVED;
		if (STRCMP(op, "asm") == 0)          return IR_OP_NONE;
		break;
	case 'b':
		if (STRCMP(op, "bitnot") == 0)       return IR_OP_BITNOT;
		break;
	case 'c':
		if (STRCMP(op, "cast") == 0)         return IR_OP_CAST;
		break;
	case 'd':
		if (STRCMP(op, "div") == 0)          return IR_OP_DIV;
		if (STRCMP(op, "deref") == 0)        return IR_OP_DEREF;
		break;
	case 'e':
		if (STRCMP(op, "eq") == 0)           return IR_OP_EQ;
		break;
	case 'f':
		if (STRCMP(op, "fp_bits_to_int") == 0) return IR_OP_FP_BITS_TO_INT;
		if (STRCMP(op, "func") == 0)         return IR_OP_FUNC;
		if (STRCMP(op, "funcaddr") == 0)     return IR_OP_FUNCADDR;
		break;
	case 'g':
		if (STRCMP(op, "ge") == 0)           return IR_OP_GE;
		if (STRCMP(op, "gt") == 0)           return IR_OP_GT;
		if (STRCMP(op, "global") == 0)       return IR_OP_GLOBAL;
		if (STRCMP(op, "global_member") == 0) return IR_OP_GLOBAL_MEMBER;
		if (STRCMP(op, "gidx_load") == 0)    return IR_OP_GIDX_LOAD;
		if (STRCMP(op, "gidx_store") == 0)   return IR_OP_GIDX_STORE;
		break;
	case 'i':
		if (STRCMP(op, "indexed") == 0)      return IR_OP_INDEXED;
		if (STRCMP(op, "int_to_fp_bits") == 0) return IR_OP_INT_TO_FP_BITS;
		break;
	case 'j':
		if (STRCMP(op, "jmp") == 0)          return IR_OP_JMP;
		if (STRCMP(op, "jz") == 0)           return IR_OP_JZ;
		if (STRCMP(op, "jnz") == 0)          return IR_OP_JNZ;
		if (STRCMP(op, "je") == 0)           return IR_OP_JE;
		if (STRCMP(op, "jne") == 0)          return IR_OP_JNE;
		if (STRCMP(op, "jlt") == 0)          return IR_OP_JLT;
		if (STRCMP(op, "jle") == 0)          return IR_OP_JLE;
		if (STRCMP(op, "jgt") == 0)          return IR_OP_JGT;
		if (STRCMP(op, "jge") == 0)          return IR_OP_JGE;
		if (STRCMP(op, "jult") == 0)         return IR_OP_JULT;
		if (STRCMP(op, "jule") == 0)         return IR_OP_JULE;
		if (STRCMP(op, "jugt") == 0)         return IR_OP_JUGT;
		if (STRCMP(op, "juge") == 0)         return IR_OP_JUGE;
		break;
	case 'L':
		if (STRCMP(op, "L") == 0)            return IR_OP_L;
		break;
	case 'l':
		if (STRCMP(op, "local") == 0)        return IR_OP_LOCAL;
		if (STRCMP(op, "local_ptr_member") == 0) return IR_OP_LOCAL_PTR_MEMBER;
		if (STRCMP(op, "le") == 0)           return IR_OP_LE;
		if (STRCMP(op, "lt") == 0)           return IR_OP_LT;
		if (STRCMP(op, "land") == 0)         return IR_OP_LAND;
		if (STRCMP(op, "lor") == 0)          return IR_OP_LOR;
		if (STRCMP(op, "load_deref") == 0)   return IR_OP_LOAD_DEREF;
		if (STRCMP(op, "load_indexed") == 0) return IR_OP_LOAD_INDEXED;
		if (STRCMP(op, "load_via_saved") == 0) return IR_OP_LOAD_VIA_SAVED;
		break;
	case 'm':
		if (STRCMP(op, "mul") == 0)          return IR_OP_MUL;
		if (STRCMP(op, "mod") == 0)          return IR_OP_MOD;
		if (STRCMP(op, "member_ptr") == 0)   return IR_OP_MEMBER_PTR;
		break;
	case 'n':
		if (STRCMP(op, "ne") == 0)           return IR_OP_NE;
		if (STRCMP(op, "neg") == 0)          return IR_OP_NEG;
		if (STRCMP(op, "not") == 0)          return IR_OP_NOT;
		if (STRCMP(op, "none") == 0)         return IR_OP_NONE;
		break;
	case 'o':
		if (STRCMP(op, "or") == 0)           return IR_OP_OR;
		break;
	case 'p':
		if (STRCMP(op, "pop") == 0)          return IR_OP_POP;
		if (STRCMP(op, "ptr_add") == 0)      return IR_OP_PTR_ADD;
		if (STRCMP(op, "ptr_sub") == 0)      return IR_OP_PTR_SUB;
		if (STRCMP(op, "ptr_copy") == 0)     return IR_OP_PTR_COPY;
		break;
	case 'r':
		if (STRCMP(op, "return") == 0)       return IR_OP_RETURN;
		break;
	case 's':
		if (STRCMP(op, "sub") == 0)          return IR_OP_SUB;
		if (STRCMP(op, "shl") == 0)          return IR_OP_SHL;
		if (STRCMP(op, "shl_imm") == 0)      return IR_OP_SHL_IMM;
		if (STRCMP(op, "shr") == 0)          return IR_OP_SHR;
		if (STRCMP(op, "shr_imm") == 0)      return IR_OP_SHR_IMM;
		if (STRCMP(op, "stack_save") == 0)   return IR_OP_STACK_SAVE;
		if (STRCMP(op, "stack_restore") == 0) return IR_OP_STACK_RESTORE;
		if (STRCMP(op, "stack_alloc") == 0)  return IR_OP_STACK_ALLOC;
		if (STRCMP(op, "string") == 0)       return IR_OP_STRING;
		if (STRCMP(op, "string_acc") == 0)   return IR_OP_STRING_ACC;
		break;
	case 't':
		if (STRCMP(op, "tmp_to_acc") == 0)   return IR_OP_TMP_TO_ACC;
		break;
	case 'u':
		if (STRCMP(op, "unsupported") == 0)  return IR_OP_UNSUPPORTED;
		if (STRCMP(op, "udiv") == 0)         return IR_OP_UDIV;
		if (STRCMP(op, "umod") == 0)         return IR_OP_UMOD;
		if (STRCMP(op, "ushr") == 0)         return IR_OP_USHR;
		if (STRCMP(op, "ushr_imm") == 0)     return IR_OP_USHR_IMM;
		if (STRCMP(op, "ult") == 0)          return IR_OP_ULT;
		if (STRCMP(op, "ule") == 0)          return IR_OP_ULE;
		if (STRCMP(op, "ugt") == 0)          return IR_OP_UGT;
		if (STRCMP(op, "uge") == 0)          return IR_OP_UGE;
		break;
	case 'v':
		if (STRCMP(op, "volatile") == 0)     return IR_OP_VOLATILE;
		if (STRCMP(op, "via_saved") == 0)    return IR_OP_VIA_SAVED;
		if (STRCMP(op, "via_saved_off") == 0) return IR_OP_VIA_SAVED_OFF;
		if (STRCMP(op, "va_start") == 0)     return IR_OP_VA_START;
		break;
	case 'x':
		if (STRCMP(op, "x64_ret_fp_agg_local") == 0) return IR_OP_X64_RET_FP_AGG_LOCAL;
		if (STRCMP(op, "x64_ret_fp_agg_global") == 0) return IR_OP_X64_RET_FP_AGG_GLOBAL;
		if (STRCMP(op, "x64_store_ret_fp_agg_local") == 0) return IR_OP_X64_STORE_RET_FP_AGG_LOCAL;
		if (STRCMP(op, "x64_store_ret_fp_agg_global") == 0) return IR_OP_X64_STORE_RET_FP_AGG_GLOBAL;
		if (STRCMP(op, "x64_arg_fp_agg_local") == 0) return IR_OP_X64_ARG_FP_AGG_LOCAL;
		if (STRCMP(op, "x64_arg_fp_agg_global") == 0) return IR_OP_X64_ARG_FP_AGG_GLOBAL;
		if (STRCMP(op, "xor") == 0)          return IR_OP_XOR;
		break;
	}
	return IR_OP_UNKNOWN;
}

static int
ir_subop_is_binop(IRSubOp subop)
{
	return subop >= IR_OP_ADD && subop <= IR_OP_PTR_SUB;
}

static int
ir_subop_is_unop(IRSubOp subop)
{
	if (subop >= IR_OP_NEG && subop <= IR_OP_USHR_IMM)
		return 1;
	if (subop >= IR_OP_STACK_SAVE && subop <= IR_OP_VA_START)
		return 1;
	switch (subop) {
	case IR_OP_UNSUPPORTED:
	case IR_OP_LOAD_DEREF:
	case IR_OP_LOAD_INDEXED:
	case IR_OP_ADDR_INDEXED:
	case IR_OP_GIDX_LOAD:
	case IR_OP_ADDR_GIDX:
	case IR_OP_ADD_OFFSET:
	case IR_OP_ACC_TO_SAVED:
	case IR_OP_LOAD_VIA_SAVED:
	case IR_OP_PTR_COPY:
	case IR_OP_PTR_ADD:
	case IR_OP_PTR_SUB:
	case IR_OP_MEMBER_PTR:
	case IR_OP_INT_TO_FP_BITS:
	case IR_OP_FP_BITS_TO_INT:
		return 1;
	default:
		return 0;
	}
}

static IRInst *
ir_emit_raw(IRProgram *ir, IRKind kind, const char *op, const char *name, long value, int aux)
{
	IRInst *inst = xcalloc(1, sizeof(IRInst));
	inst->kind = kind;
	inst->id = ir->next_id++;
	inst->value = value;
	inst->aux = aux;
	inst->src_line = irgen.src_line;
	inst->src_filename_id = irgen.src_filename_id;

	/* op fits in a fixed 16-byte buffer: no heap allocation needed */
	if (op) {
		strncpy(inst->op, op, sizeof(inst->op) - 1);
		inst->subop = (uint8_t)ir_op_to_subop(op);
		if (inst->subop == IR_OP_UNKNOWN)
			ICE("Unknown IR op/sub-op string: %s", op);
	}
	/* name is variable-length (function/variable names): heap-allocate */
	if (name)
		inst->name = xstrdup(name);
	else
		inst->name = xstrdup("");

	if (!ir->head)
		ir->head = inst;
	else
		ir->tail->next = inst;

	ir->tail = inst;
	return inst;
}

