static int
ir_branch_is_conditional_subop(IRSubOp subop)
{
	return subop >= IR_OP_JZ && subop <= IR_OP_JUGE;
}

static int
ir_node_is_compare(const Node *node)
{
	if (!node)
		return 0;
	return node->kind >= ND_EQ && node->kind <= ND_GE;
}

static int
ir_compare_operand_size(const Node *node)
{
	int size = 0;

	if (!node)
		return TCC_SIZEOF_INT;
	if ((node->left && node->left->is_pointer) ||
	    (node->right && node->right->is_pointer))
		return TCC_SIZEOF_PTR;
	if (node->left && node->left->type) {
		size = type_sizeof(node->left->type);
		if (size > 0)
			return size;
	}
	if (node->right && node->right->type) {
		size = type_sizeof(node->right->type);
		if (size > 0)
			return size;
	}
	if (node->elem_size > 0)
		return node->elem_size;
	return TCC_SIZEOF_INT;
}

static const char *
ir_compare_branch_op(const Node *node, int branch_on_true)
{
	int is_unsigned;

	if (!node)
		return NULL;

	is_unsigned = node->is_unsigned ? 1 : 0;
	switch (node->kind) {
	case ND_EQ:
		return branch_on_true ? "je" : "jne";
	case ND_NE:
		return branch_on_true ? "jne" : "je";
	case ND_LT:
		if (is_unsigned)
			return branch_on_true ? "jult" : "juge";
		return branch_on_true ? "jlt" : "jge";
	case ND_LE:
		if (is_unsigned)
			return branch_on_true ? "jule" : "jugt";
		return branch_on_true ? "jle" : "jgt";
	case ND_GT:
		if (is_unsigned)
			return branch_on_true ? "jugt" : "jule";
		return branch_on_true ? "jgt" : "jle";
	case ND_GE:
		if (is_unsigned)
			return branch_on_true ? "juge" : "jult";
		return branch_on_true ? "jge" : "jlt";
	default:
		return NULL;
	}
}

