static void
ir_emit_float_operand(IRProgram *ir, Node *node, int fp_size)
{
	int is_unsigned;
	int src_size;

	if (!node)
		return;
	if (node->type && type_is_fp_scalar(node->type)) {
		ir_expr(ir, node);
		src_size = type_sizeof(node->type);
		if (src_size > 0 && fp_size > 0 && src_size != fp_size) {
			IRInst *inst = ir_emit_unary_op(ir, "cast");
			inst->fp_size = fp_size;
			inst->value = src_size;
			inst->aux = fp_size;
		}
		return;
	}

	ir_expr(ir, node);
	is_unsigned = (node->type && type_is_unsigned(node->type)) ? 1 : node->is_unsigned;
	ir_emit_int_to_fp_bits(ir, fp_size > 0 ? fp_size : 8, is_unsigned);
}

