static void
ir_emit_scalar_load_cast(IRProgram *ir, Node *node)
{
	Type *type;
	int size;
	int is_unsigned;

	if (!ir || !node || node->is_pointer || node->is_bitfield)
		return;

	type = node->type;
	if (!type || !type_is_integer(type))
		return;
	if (type_is_array(type) || type_is_struct(type) || type_is_union(type) ||
	    type_is_function(type) || type_is_fp_scalar(type))
		return;

	size = type_sizeof(type);
	if (size <= 0 || size >= 8)
		return;

	is_unsigned = type_is_unsigned(type);
	ir_emit_cast(ir, size, is_unsigned);
}

