static void
ir_inst_set_param_names(IRInst *inst, char **param_names, int param_count)
{
	int i;

	if (!inst || param_count <= 0)
		return;
	inst->param_names = xcalloc((size_t)param_count, sizeof(char *));
	for (i = 0; i < param_count; i++) {
		if (param_names && param_names[i] && param_names[i][0])
			inst->param_names[i] = xstrdup(param_names[i]);
	}
}


