static void
ir_inst_set_debug_locals(IRInst *inst, const NodeDebugLocal *locals, int count)
{
	int i;

	if (!inst || !locals || count <= 0)
		return;
	inst->debug_locals = xcalloc((size_t)count, sizeof(NodeDebugLocal));
	inst->debug_local_count = count;
	for (i = 0; i < count; i++) {
		if (locals[i].name && locals[i].name[0])
			inst->debug_locals[i].name = xstrdup(locals[i].name);
		inst->debug_locals[i].offset = locals[i].offset;
		inst->debug_locals[i].type_id = locals[i].type_id;
		if (locals[i].struct_name[0])
			STRNCPY(inst->debug_locals[i].struct_name, locals[i].struct_name,
			        sizeof(inst->debug_locals[i].struct_name) - 1);
		if (locals[i].pointer_struct_name[0])
			STRNCPY(inst->debug_locals[i].pointer_struct_name, locals[i].pointer_struct_name,
			        sizeof(inst->debug_locals[i].pointer_struct_name) - 1);
		inst->debug_locals[i].pointer_depth = locals[i].pointer_depth;
		inst->debug_locals[i].array_len = locals[i].array_len;
		inst->debug_locals[i].array_elem_type_id = locals[i].array_elem_type_id;
		if (locals[i].array_elem_struct_name[0])
			STRNCPY(inst->debug_locals[i].array_elem_struct_name, locals[i].array_elem_struct_name,
			        sizeof(inst->debug_locals[i].array_elem_struct_name) - 1);
	}
}

