#define new_ir_label() (irgen.next_label++)

static int
ir_get_user_label_id(const char *name)
{
	if (!name)
		name = "";

	for (int i = 0; i < irgen.user_label_count; i++) {
		if (STRCMP(irgen.user_labels[i].name, name) == 0)
			return irgen.user_labels[i].id;
	}

	if (irgen.user_label_count >= IR_USER_LABEL_MAX)
		ICE("Too many user labels in one function");

	IRUserLabel *l = &irgen.user_labels[irgen.user_label_count++];
	STRNCPY(l->name, name, sizeof(l->name) - 1);
	l->id = new_ir_label();
	return l->id;
}

static void 
ir_add_string_len_width(IRProgram *ir, int label, const char *value, size_t len, int width)
{
	IRString *existing;
	IRString *s;

	for (existing = ir->strings; existing; existing = existing->next) {
		if (existing->label == label)
			return;
	}

	s = xcalloc(1, sizeof(IRString));
	s->label = label;
	s->value = xmalloc(len + 1);
	memcpy(s->value, value ? value : "", len);
	s->value[len] = '\0';
	s->len = (unsigned int)len;
	s->width = width ? width : 1;
	s->next = ir->strings;
	ir->strings = s;
}

static int
ir_emit_struct_lvalue_address(IRProgram *ir, Node *node)
{
	if (!node)
		return 0;

	switch (node->kind) {
	case ND_VAR:
		ir_emit_load_addr_local(ir, node->name, node->offset);
		return 1;

	case ND_GLOBAL:
		ir_emit_load_addr_global(ir, node->name);
		return 1;

	case ND_DEREF:
		ir_expr(ir, node->left);
		return 1;

	case ND_INDEX:
		ir_expr(ir, node->left);
		ir_emit_unop_indexed(ir, "addr_indexed", node->name, node->offset,
		                     node->elem_size ? node->elem_size : TCC_SIZEOF_INT);
		return 1;

	case ND_GLOBAL_INDEX:
		ir_expr(ir, node->left);
		ir_emit_unop_indexed(ir, "addr_gidx", node->name, 0,
		                     node->elem_size ? node->elem_size : TCC_SIZEOF_INT);
		return 1;

	case ND_MEMBER:
		ir_emit_load_addr_local(ir, node->name, node->offset);
		return 1;

	case ND_MEMBER_PTR:
		ir_expr(ir, node->left);
		if (node->offset)
			ir_emit_add_offset(ir, node->offset);
		return 1;

	case ND_COND:
		/* Match the mature AST fallback path: struct-producing conditionals
		 * are lowered to addressable branch temps, so either arm can supply
		 * the lvalue address for copy purposes.
		 */
		if (node->then_body)
			return ir_emit_struct_lvalue_address(ir, node->then_body);
		if (node->else_body)
			return ir_emit_struct_lvalue_address(ir, node->else_body);
		return 0;

	case ND_COMMA:
		/* Preserve setup side effects, then take the address of the final
		 * struct-valued temp/expression.
		 */
		if (node->left)
			ir_expr(ir, node->left);
		return ir_emit_struct_lvalue_address(ir, node->right);

	default:
		return 0;
	}
}

static int
ir_x86_call_has_struct_value_arg(const Node *node)
{
	const Node *arg;

	if (preprocess_get_target() != PP_TARGET_X86 || !node)
		return 0;

	for (arg = node->args; arg; arg = arg->next) {
		if (arg->type && type_is_struct(arg->type))
			return 1;
	}

	return 0;
}

static void 
push_loop(int break_label, int continue_label)
{
	int depth = irgen.loop_depth;

	if (depth >= IR_LOOP_MAX) {
		ICE("Too many nested IR loops");
	}

	irgen.loop_stack[depth].break_label = break_label;
	irgen.loop_stack[depth].continue_label = continue_label;
	irgen.loop_depth = depth + 1;
}

static void 
pop_loop(void)
{
	int *depth = &irgen.loop_depth;
	if (*depth > 0)
		(*depth)--;
}

static int 
current_break_label(IRProgram *ir)
{
	int depth = irgen.loop_depth - 1;

	if (depth < 0) {
		ir_mark_unsupported(ir, "break outside lowered loop");
		return 0;
	}

	return irgen.loop_stack[depth].break_label;
}

static int 
current_continue_label(IRProgram *ir)
{
	int depth = irgen.loop_depth - 1;

	if (depth < 0) {
		ir_mark_unsupported(ir, "continue outside lowered loop");
		return 0;
	}

	return irgen.loop_stack[depth].continue_label;
}

static const char *
binop_name(NodeKind kind)
{
	switch (kind) {
	case ND_ADD:
		return "add";
	case ND_SUB:
		return "sub";
	case ND_MUL:
		return "mul";
	case ND_DIV:
		return "div";
	case ND_MOD:
		return "mod";
	case ND_BITAND:
		return "and";
	case ND_BITOR:
		return "or";
	case ND_BITXOR:
		return "xor";
	case ND_SHL:
		return "shl";
	case ND_SHR:
		return "shr";
	case ND_EQ:
		return "eq";
	case ND_NE:
		return "ne";
	case ND_LT:
		return "lt";
	case ND_LE:
		return "le";
	case ND_GT:
		return "gt";
	case ND_GE:
		return "ge";
	case ND_LOGICAL_AND:
		return "land";
	case ND_LOGICAL_OR:
		return "lor";
	default:
		return NULL;
	}
}

static int 
ir_lvalue_size(Node *n)
{
	if (!n)
		return 4;
	if (n->type && (type_is_fp_scalar(n->type) || type_is_complex(n->type))) {
		int size = type_sizeof(n->type);
		if (size > 0)
			return size;
	}
	if (n->is_pointer)
		return 8;
	return n->elem_size ? n->elem_size : 4;
}

static int 
ir_incdec_delta(Node *target, int is_dec)
{
	int delta = 1;

	if (target && target->is_pointer)
		delta = target->elem_size ? target->elem_size : 1;

	return is_dec ? -delta : delta;
}

static void
ir_emit_incdec_delta(IRProgram *ir, Node *target, int is_dec)
{
	if (target && target->type && type_is_fp_scalar(target->type)) {
		int size = type_sizeof(target->type);

		ir_emit_const(ir, 1);
		ir_emit_int_to_fp_bits(ir, size > 0 ? size : 8, 0);
		ir_emit_binary_op_fp(ir, is_dec ? "sub" : "add", size > 0 ? size : 8);
		return;
	}

	ir_emit_const(ir, ir_incdec_delta(target, is_dec));
	ir_emit_binary_op(ir, "add");
}

static unsigned long bitfield_low_mask(int width);
static void ir_emit_bitfield_extract(IRProgram *ir, Node *node);

static void 
ir_store_lvalue_from_stack(IRProgram *ir, Node *target)
{
	if (!target) {
		ir_mark_unsupported(ir, "missing inc/dec lvalue");
		return;
	}

	switch (target->kind) {
	case ND_VAR:
	case ND_MEMBER:
		if (target->is_bitfield) {
			unsigned long field_mask = bitfield_low_mask(target->bit_width);
			unsigned long shifted_mask = target->bit_offset >= (int)(sizeof(unsigned long) * 8)
				? 0UL : (field_mask << target->bit_offset);
			unsigned long clear_mask = ~shifted_mask;

			ir_emit_const(ir, (long)field_mask);
			ir_emit_binary_op(ir, "and");
			ir_emit_load_local(ir, target->name, target->offset, target->bit_storage_size);
			ir_emit_const(ir, (long)clear_mask);
			ir_emit_binary_op(ir, "and");
			ir_emit_raw(ir, IR_UNOP, "acc_to_tmp", NULL, 0, 0);
			ir_emit_pop(ir);
			if (target->bit_offset > 0)
				ir_emit_shift_imm(ir, "shl_imm", target->bit_offset);
			ir_emit_raw(ir, IR_UNOP, "tmp_to_acc", NULL, 0, 0);
			ir_emit_binary_op(ir, "or");
			ir_emit_store_local(ir, target->name, target->offset, target->bit_storage_size);
			return;
		}
		ir_emit_store_local(ir, target->name, target->offset, ir_lvalue_size(target));
		return;

	case ND_GLOBAL: {
		IRInst *gi = ir_emit_store_global(ir, target->name);
		gi->is_extern = ir_global_is_extern(target->name);
	}
	return;

	case ND_INDEX:
		/*
		 * Generic indexed stores need both index and value.  Inc/dec
		 * lowering currently handles scalar local/global/member lvalues.
		 */
		ir_mark_unsupported(ir, "inc/dec indexed lvalue");
		return;

	case ND_DEREF:
		/* *ptr = val — value is on stack, address is the pointer expr result */
		ir_emit_store_deref(ir, ir_lvalue_size(target));
		return;

	case ND_MEMBER_PTR:
		if (target->is_bitfield) {
			unsigned long field_mask = bitfield_low_mask(target->bit_width);
			unsigned long shifted_mask = target->bit_offset >= (int)(sizeof(unsigned long) * 8)
				? 0UL : (field_mask << target->bit_offset);
			unsigned long clear_mask = ~shifted_mask;

			ir_expr(ir, target->left);
			ir_emit_add_offset(ir, target->offset);
			ir_emit_acc_to_saved(ir);
			ir_emit_pop(ir);
			ir_emit_const(ir, (long)field_mask);
			ir_emit_binary_op(ir, "and");
			ir_emit_unop_sized(ir, "load_via_saved", target->bit_storage_size);
			ir_emit_const(ir, (long)clear_mask);
			ir_emit_binary_op(ir, "and");
			ir_emit_raw(ir, IR_UNOP, "acc_to_tmp", NULL, 0, 0);
			ir_emit_pop(ir);
			if (target->bit_offset > 0)
				ir_emit_shift_imm(ir, "shl_imm", target->bit_offset);
			ir_emit_raw(ir, IR_UNOP, "tmp_to_acc", NULL, 0, 0);
			ir_emit_binary_op(ir, "or");
			ir_emit_store_via_saved(ir, target->bit_storage_size);
			return;
		}
		/* ptr->field = val — value on stack, need to compute ptr+offset then store */
		ir_emit_store_member_ptr(ir, target->offset, ir_lvalue_size(target));
		return;

	case ND_GLOBAL_INDEX:
		ir_mark_unsupported(ir, "inc/dec complex lvalue");
		return;

	default:
		ir_mark_unsupported(ir, "inc/dec unsupported lvalue");
		return;
	}
}

static void 
ir_incdec_expr(IRProgram *ir, Node *node)
{
	Node *target = node->left;
	int is_post = node->kind == ND_POST_INC || node->kind == ND_POST_DEC;
	int is_dec = node->kind == ND_PRE_DEC || node->kind == ND_POST_DEC;

	if (!target) {
		ir_mark_unsupported(ir, "inc/dec missing target");
		return;
	}

	/*
	 * Pre:
	 *   load old
	 *   const delta
	 *   add
	 *   assign target = new
	 *   reload target   -> expression value is new
	 *
	 * Post:
	 *   load old        -> expression value remains on stack
	 *   load old
	 *   const delta
	 *   add
	 *   assign target = new
	 *
	 * This keeps stack semantics simple and avoids adding a DUP IR op yet.
	 */
	if (target->is_bitfield &&
	    (target->kind == ND_MEMBER || target->kind == ND_MEMBER_PTR)) {
		if (target->kind == ND_MEMBER_PTR) {
			ir_expr(ir, target->left);
			if (target->offset)
				ir_emit_add_offset(ir, target->offset);
			ir_emit_acc_to_saved(ir);
			ir_emit_pop(ir);
			ir_emit_unop_sized(ir, "load_via_saved", target->bit_storage_size);
		} else {
			ir_emit_load_local(ir, target->name, target->offset, target->bit_storage_size);
		}
		ir_emit_bitfield_extract(ir, target);
		if (is_post) {
			ir_emit_raw(ir, IR_UNOP, "acc_to_tmp", NULL, 0, 0);
			ir_emit_raw(ir, IR_UNOP, "tmp_to_acc", NULL, 0, 0);
		}
		ir_emit_incdec_delta(ir, target, is_dec);
		ir_store_lvalue_from_stack(ir, target);
		ir_emit_pop(ir);
		if (!is_post) {
			if (target->kind == ND_MEMBER_PTR) {
				ir_expr(ir, target->left);
				if (target->offset)
					ir_emit_add_offset(ir, target->offset);
				ir_emit_acc_to_saved(ir);
				ir_emit_pop(ir);
				ir_emit_unop_sized(ir, "load_via_saved", target->bit_storage_size);
			} else {
				ir_emit_load_local(ir, target->name, target->offset, target->bit_storage_size);
			}
			ir_emit_bitfield_extract(ir, target);
		}
		return;
	}

	/* For addressable indirect lvalues: compute addr once, save it, then load/update/store. */
	if ((target->kind == ND_MEMBER_PTR && !target->is_bitfield) ||
	    target->kind == ND_DEREF ||
	    target->kind == ND_INDEX || target->kind == ND_GLOBAL_INDEX) {
		/* ir_lvalue_size respects is_pointer: pointer nodes use 8-byte store/load
		 * regardless of elem_size (which encodes the stride, not the pointer width). */
		int sz = ir_lvalue_size(target);
		if (target->kind == ND_MEMBER_PTR) {
			ir_expr(ir, target->left);
			ir_emit_add_offset(ir, target->offset);
		} else if (target->kind == ND_INDEX) {
			ir_expr(ir, target->left);
			ir_emit_unop_indexed(ir, "addr_indexed", target->name, target->offset,
			                     target->elem_size ? target->elem_size : TCC_SIZEOF_INT);
		} else if (target->kind == ND_GLOBAL_INDEX) {
			ir_expr(ir, target->left);
			ir_emit_unop_indexed(ir, "addr_gidx", target->name, 0,
			                     target->elem_size ? target->elem_size : TCC_SIZEOF_INT);
		} else {
			ir_expr(ir, target->left);
		}
		/* acc = addr (also on stack from ir_expr above — pop after saving) */
		ir_emit_acc_to_saved(ir);           /* ecx = addr; no stack change */
		ir_emit_pop(ir);                       /* discard pushed addr ptr */
		ir_emit_unop_sized(ir, "load_via_saved", sz);  /* acc = old → pushed (+1) */
		if (is_post) {
			ir_emit_raw(ir, IR_UNOP, "acc_to_tmp", NULL, 0, 0);
			ir_emit_raw(ir, IR_UNOP, "tmp_to_acc", NULL, 0, 0);
		}
		ir_emit_incdec_delta(ir, target, is_dec);         /* pops 2, pushes new (-1) */
		ir_emit_store_via_saved(ir, sz);       /* [ecx] = new; no stack */
		/* Net stack change: +1 (new on top)
		 * post-inc: old pre-pushed; pop new → net 0, old is result */
		if (is_post)
			ir_emit_pop(ir);
		/* pre-inc: net +1, new is result ✓ */
	} else {
		ir_expr(ir, target);
		if (is_post) {
			ir_emit_raw(ir, IR_UNOP, "acc_to_tmp", NULL, 0, 0);
			ir_emit_raw(ir, IR_UNOP, "tmp_to_acc", NULL, 0, 0);
		}
		ir_emit_incdec_delta(ir, target, is_dec);
		ir_store_lvalue_from_stack(ir, target);
	}

	if (!is_post)
		ir_expr(ir, target);
}

static int 
is_simple_lvalue(Node *node)
{
	return node && (node->kind == ND_VAR ||
	                node->kind == ND_GLOBAL ||
	                node->kind == ND_GLOBAL_INDEX ||
	                node->kind == ND_INDEX ||
	                node->kind == ND_DEREF ||
	                node->kind == ND_MEMBER ||
	                node->kind == ND_MEMBER_PTR);
}

static unsigned long
bitfield_low_mask(int width)
{
	if (width <= 0)
		return 0UL;
	if (width >= (int)(sizeof(unsigned long) * 8))
		return ~0UL;
	return ((1UL << width) - 1UL);
}

static int
ir_low_mask_width(unsigned long mask)
{
	int width = 0;

	if (mask == 0UL)
		return 0;
	while (mask & 1UL) {
		width++;
		mask >>= 1;
	}
	return mask == 0UL ? width : 0;
}

static void
ir_emit_bitfield_extract(IRProgram *ir, Node *node)
{
	int storage_bits;
	unsigned long storage_mask;
	unsigned long field_mask;
	int sign_shift;

	if (!node || !node->is_bitfield)
		return;

	storage_bits = (node->bit_storage_size ? node->bit_storage_size : node->elem_size) * 8;
	storage_mask = bitfield_low_mask(storage_bits);
	field_mask = bitfield_low_mask(node->bit_width);

	if (storage_bits < (int)(sizeof(unsigned long) * 8)) {
		ir_emit_const(ir, (long)storage_mask);
		ir_emit_binary_op(ir, "and");
	}
	if (node->bit_offset > 0) {
		ir_emit_shift_imm(ir, "ushr_imm", node->bit_offset);
	}
	if (node->bit_width < storage_bits) {
		ir_emit_const(ir, (long)field_mask);
		ir_emit_binary_op(ir, "and");
	}
	if (!node->is_unsigned && node->bit_width > 0 && node->bit_width < storage_bits) {
		sign_shift = (int)(sizeof(long) * 8) - node->bit_width;
		ir_emit_shift_imm(ir, "shl_imm", sign_shift);
		ir_emit_shift_imm(ir, "shr_imm", sign_shift);
	}
}

static void 
ir_list(IRProgram *ir, Node *node)
{
	for (Node *n = node; n; n = n->next) {
		if (n->kind == ND_BLOCK) {
			ir_list(ir,n->body);
			continue;
		}
		ir_stmt(ir, n);
	}
}

static void
ir_stmt(IRProgram *ir, Node *n)
{
tail:
	if (!n)
		return;
	/* Track source location for debug info.  Synthetic parser-generated
	 * statements, such as ABI struct-parameter copy-in code, should not
	 * inherit the user source line that happened to be current after parsing
	 * the function body.  Suppress .loc for those instructions until the next
	 * real source statement updates the location. */
	if (n->suppress_debug_loc) {
		irgen.src_line = 0;
		irgen.src_filename_id = 0;
	} else if (n->line > 0) {
		irgen.src_line = n->line;
		irgen.src_filename_id = n->filename_id;
	}

	switch (n->kind) {
	case ND_LABEL:
		ir_emit_user_label(ir, n->name);
		return;

	case ND_GOTO:
		ir_emit_user_branch(ir, n->name);
		return;

	case ND_FUNC:
		STRNCPY(irgen.current_func_name, n->name,
		        sizeof(irgen.current_func_name) - 1);
		if (irgen.target_cg == &arm64_codegen) {
			int use_ast_fallback = 0;

			if (use_ast_fallback) {
				ir_mark_unsupported(ir, "arm64 direct aggregate function ABI");
				irgen.current_func_name[0] = '\0';
				return;
			}
		}
		irgen.returns_struct = n->returns_struct;
		irgen.struct_return_size = n->struct_return_size;
		irgen.current_func_stack_size = n->stack_size;
		irgen.hidden_local_bytes = 0;
		irgen.function_return_type = n->return_type;
		STRNCPY(irgen.struct_return_name,
		        n->return_struct_name[0] ? n->return_struct_name : "",
		        sizeof(irgen.struct_return_name) - 1);
		{
			IRInst *func_inst = ir_emit_func_label(ir, n->name, n->stack_size, n->param_count);

			if (func_inst) {
				func_inst->is_static = n->is_static;
				ir_inst_set_param_names(func_inst, n->param_names, n->param_count);
				ir_inst_set_param_type_ids(func_inst, n->param_type_ids, n->param_count);
				ir_inst_set_param_offsets(func_inst, n->param_offsets, n->param_count);
				ir_inst_set_param_abi_sizes(func_inst, n->param_abi_sizes, n->param_count);
				ir_inst_set_param_structs(func_inst, n->param_struct_names, n->param_count);
				ir_inst_set_param_pointer_structs(func_inst, n->param_pointer_struct_names,
				                                n->param_pointer_depths, n->param_count);
				ir_inst_set_debug_locals(func_inst, n->debug_locals, n->debug_local_count);
			}
		}

		if (n->body && n->body->kind == ND_BLOCK)
			ir_list(ir, n->body->body);
		else
			ir_list(ir, n->body);

		irgen.returns_struct = 0;
		irgen.struct_return_size = 0;
		irgen.current_func_stack_size = 0;
		irgen.hidden_local_bytes = 0;
		irgen.function_return_type = NULL;
		irgen.struct_return_name[0] = '\0';
		irgen.current_func_name[0] = '\0';
		return;

	case ND_BLOCK:
		ir_list(ir, n->body);
		return;

	case ND_COMMA:
		ir_stmt(ir, n->left);
		n = n->right;
		goto tail;

	case ND_CALL: {
		int fixed_params;
		unsigned int fp_arg_mask = 0;
		unsigned int fp_arg_double_mask = 0;

		if (ir_x86_call_has_struct_value_arg(n)) {
			ir_mark_unsupported(ir, "x86 struct-by-value call statement");
			return;
		}
		if (irgen.target_cg == &arm64_codegen &&
		    ir_arm64_emit_single_hfa_aggregate_call(ir, n, 1)) {
			return;
		}
		if (irgen.target_cg == &arm64_codegen &&
		    ir_arm64_emit_single_intregs_aggregate_call(ir, n, 1)) {
			return;
		}
		if (irgen.target_cg == &arm64_codegen &&
		    ir_arm64_emit_mixed_hfa_gpr_call(ir, n, 1)) {
			return;
		}
		if (irgen.target_cg == &x64_codegen &&
		    ir_x64_emit_single_complex_double_call(ir, n, 1)) {
			return;
		}
		if (irgen.target_cg == &x64_codegen &&
		    ir_x64_emit_mixed_complex_double_gpr_call(ir, n, 1)) {
			return;
		}
		if (irgen.target_cg == &arm64_codegen &&
		    ir_arm64_call_uses_nonbyref_aggregate_abi(n)) {
			ir_mark_unsupported(ir, "arm64 non-byref aggregate call statement");
			return;
		}
		if (n->returns_struct &&
		    !ir_node_returns_x64_direct_complex_abi(n)) {
			ir_mark_unsupported(ir, "struct-returning call statement");
			return;
		}
		if (ir_emit_stack_builtin_call(ir, n, 1)) {
			return;
		}

		int count = 0;
		{
			Node *_ct;
			for (_ct = n->args; _ct; _ct = _ct->next) count++;
		}
		{
			Node **args = (Node **)xcalloc(count > 0 ? count : 1, sizeof(Node *));
			int _ci = 0;
			Node *_arg;
			for (_arg = n->args; _arg; _arg = _arg->next) args[_ci++] = _arg;

			ir_collect_call_fp_arg_masks(args, count, &fp_arg_mask, &fp_arg_double_mask);
			fixed_params = n->left ? -1 : func_fixed_params(n->name);

			if (!n->left && count == 1 && ir_arm64_direct_gpr_arg_ok(args[0])) {
				if (args[0]->kind == ND_STRING) {
					ir_add_string_len_width(ir, args[0]->string_label, args[0]->string_value,
					                        args[0]->string_len,
					                        args[0]->string_width ? args[0]->string_width : 1);
					ir_emit_load_string_acc(ir, args[0]->string_value, args[0]->string_label);
				} else {
					ir_expr(ir, args[0]);
					ir_emit_pop(ir);
				}
				ir_emit_call_acc_arg0(ir, n->name, 1);
				xfree(args);
				return;
			}

			if (irgen.target_cg == &arm64_codegen &&
			    !n->left &&
			    count > 0 &&
			    count <= IR_SIMPLE_CALL_MAX_ARGS &&
			    fp_arg_mask == 0) {
				IRSimpleCallArg simple_args[IR_SIMPLE_CALL_MAX_ARGS];
				int simple_ok = 1;
				int i;

				memset(simple_args, 0, sizeof(simple_args));
				for (i = 0; i < count; i++) {
					if (!ir_try_capture_simple_call_arg(ir, &simple_args[i], args[i])) {
						simple_ok = 0;
						break;
					}
				}
				if (simple_ok) {
					IRInst *ci = ir_emit_call_direct(ir, n->name, count, 1);

					ci->fixed_params = fixed_params;
					ci->simple_call_arg_count = (uint8_t)count;
					for (i = 0; i < count; i++)
						ci->simple_call_args[i] = simple_args[i];
					xfree(args);
					return;
				}
				for (i = 0; i < IR_SIMPLE_CALL_MAX_ARGS; i++)
					xfree(simple_args[i].name);
			}

			{
				int _i;
				for (_i = count - 1; _i >= 0; _i--)
					ir_expr(ir, args[_i]);
			}

			if (n->left) {
				ir_expr(ir, n->left);
				ir_emit_call_indirect(ir, count, 1);
			} else {
				IRInst *_ci2 = ir_emit_call_direct(ir, n->name, count, 1);
				if (_ci2) {
					_ci2->fixed_params = fixed_params;
					_ci2->fp_arg_mask = fp_arg_mask;
					_ci2->fp_arg_double_mask = fp_arg_double_mask;
				}
			}
			xfree(args);
		}
		return;
	}

	case ND_ASM:
		ir_emit_raw(ir, IR_ASM, n->asm_is_volatile ? "volatile" : "asm",
		            n->string_value, 0, n->asm_is_volatile);
		return;

	case ND_DECL:
	case ND_PTR_DECL:
	case ND_ARRAY_DECL:
	case ND_STRUCT_DECL:
		return;

	case ND_RETURN:
		if (irgen.target_cg == &arm64_codegen &&
		    n->left && n->left->type && type_is_struct(n->left->type) &&
		    parser_classify_aggregate_abi(n->left->type, NULL) == AGGREGATE_ABI_INTREGS) {
			Node *ret_val = n->left;
			IRInst *ret_inst;

			if (ret_val->kind == ND_COMMA) {
				ir_stmt(ir, ret_val->left);
				ret_val = ret_val->right;
			}
			if (ret_val->kind != ND_VAR && ret_val->kind != ND_GLOBAL) {
				ir_mark_unsupported(ir, "arm64 direct aggregate return requires named storage");
				return;
			}
			ir_emit_arm64_direct_aggregate_return_value(ir, ret_val);
			ret_inst = ir_emit_return(ir);
			if (ret_inst)
				ret_inst->aux = 1;
			return;
		}
		if (irgen.target_cg == &arm64_codegen &&
		    n->left && n->left->type && type_is_struct(n->left->type) &&
		    parser_classify_aggregate_abi(n->left->type, NULL) == AGGREGATE_ABI_HFA) {
			IRInst *ret_inst;
			Node *ret_val = n->left;

			if (ret_val->kind == ND_COMMA) {
				ir_stmt(ir, ret_val->left);
				ret_val = ret_val->right;
			}
			if (ret_val->kind != ND_VAR && ret_val->kind != ND_GLOBAL) {
				ir_mark_unsupported(ir, "arm64 direct aggregate return requires named storage");
				return;
			}
			ir_emit_arm64_direct_hfa_return_value(ir, ret_val);
			ret_inst = ir_emit_return(ir);
			if (ret_inst)
				ret_inst->aux = 1;
			return;
		}
		if (irgen.target_cg == &x64_codegen &&
		    n->left && n->left->type &&
		    ir_type_uses_x64_complex_double_abi(n->left->type)) {
			Node *ret_val = n->left;
			IRInst *ret_inst;

			if (ret_val->kind == ND_COMMA) {
				ir_stmt(ir, ret_val->left);
				ret_val = ret_val->right;
			}
			if (ret_val->kind != ND_VAR && ret_val->kind != ND_GLOBAL) {
				ir_mark_unsupported(ir, "x64 direct complex return requires named storage");
				return;
			}
			ir_emit_x64_direct_complex_double_return_value(ir, ret_val);
			ret_inst = ir_emit_return(ir);
			if (ret_inst)
				ret_inst->aux = 1;
			return;
		}
		if (irgen.returns_struct) {
			Node *ret_val = n->left;

			if (n->left && n->left->type &&
			    parser_classify_aggregate_abi(n->left->type, NULL) == AGGREGATE_ABI_HFA) {
				IRInst *ret_inst;

				if (ret_val && ret_val->kind == ND_COMMA) {
					ir_stmt(ir, ret_val->left);
					ret_val = ret_val->right;
				}
				if (!ret_val || (ret_val->kind != ND_VAR && ret_val->kind != ND_GLOBAL)) {
					ir_mark_unsupported(ir, "arm64 HFA struct return requires named storage");
					return;
				}
				ir_emit_arm64_direct_hfa_return_value(ir, ret_val);
				ret_inst = ir_emit_return(ir);
				if (ret_inst)
					ret_inst->aux = 1;
				return;
			}
			if (ret_val && ret_val->type &&
			    ir_type_uses_x64_complex_double_abi(ret_val->type)) {
				IRInst *ret_inst;

				if (ret_val && ret_val->kind == ND_COMMA) {
					ir_stmt(ir, ret_val->left);
					ret_val = ret_val->right;
				}
				if (!ret_val || (ret_val->kind != ND_VAR && ret_val->kind != ND_GLOBAL)) {
					ir_mark_unsupported(ir, "x64 direct complex return requires named storage");
					return;
				}
				ir_emit_x64_direct_complex_double_return_value(ir, ret_val);
				ret_inst = ir_emit_return(ir);
				if (ret_inst)
					ret_inst->aux = 1;
				return;
			}

			/* If return value is a ND_COMMA (spilled struct call), use the right side */
			if (ret_val && ret_val->kind == ND_COMMA)
				ret_val = ret_val->right;

			if (!ret_val ||
			        (ret_val->kind != ND_VAR && ret_val->kind != ND_GLOBAL) ||
			        !ret_val->type || !type_is_struct(ret_val->type)) {
				ir_mark_unsupported(ir, "struct return requires local struct");
				return;
			}

			/* emit the side-effect part of ND_COMMA if present */
			if (n->left && n->left->kind == ND_COMMA)
				ir_stmt(ir, n->left->left);

			/* Copy the full struct by address so array fields and odd-sized
			 * aggregates are returned byte-accurately. */
			ir_emit_load_local(ir, "__ret", -8, 8);
			ir_emit_acc_to_saved(ir);
			if (ret_val->kind == ND_VAR)
				ir_emit_load_addr_local(ir, ret_val->name, ret_val->offset);
			else
				ir_emit_load_addr_global(ir, ret_val->name);
			ir_emit_unop_sized(ir, "ptr_copy", irgen.struct_return_size);

			ir_emit_const(ir, 0);
			ir_emit_return(ir);
			return;
		}

		ir_emit_return_expr(ir, n->left);
		return;

	case ND_PRE_INC:
	case ND_PRE_DEC:
	case ND_POST_INC:
	case ND_POST_DEC:
		ir_incdec_expr(ir, n);
		ir_emit_pop(ir);
		return;

	case ND_ASSIGN:
		if (n->left && n->left->is_bitfield &&
		    (n->left->kind == ND_MEMBER || n->left->kind == ND_MEMBER_PTR)) {
			ir_expr(ir, n->right);
			ir_store_lvalue_from_stack(ir, n->left);
			return;
		}

		if (n->right && n->right->kind == ND_GLOBAL &&
		        n->right->type && type_is_struct(n->right->type) &&
		        n->left && n->left->kind == ND_VAR &&
		        n->left->type && type_is_struct(n->left->type)) {
			/* local_struct = global_struct -- word-by-word copy */
			int sz = type_sizeof(n->right->type);
			for (int off = 0; off < sz; off += 4) {
				ir_emit_load_addr_global(ir, n->right->name);
				if (off)
					ir_emit_add_offset(ir, off);
				ir_emit_unop_sized(ir, "load_deref", 4);
				ir_emit_store_local(ir, n->left->name, n->left->offset + off, TCC_SIZEOF_INT);
			}
			return;
		}

		if (irgen.target_cg == &arm64_codegen &&
		    n->right && n->right->kind == ND_CALL &&
		    n->right->returns_struct &&
		    n->right->aggregate_abi_class == AGGREGATE_ABI_HFA &&
		    n->left && n->left->type &&
		    parser_classify_aggregate_abi(n->left->type, NULL) == AGGREGATE_ABI_HFA &&
		    ir_emit_arm64_direct_hfa_call_to_lvalue(ir, n->left, n->right)) {
			return;
		}
		if (irgen.target_cg == &arm64_codegen &&
		    n->right && n->right->kind == ND_CALL &&
		    n->right->returns_struct &&
		    n->right->aggregate_abi_class == AGGREGATE_ABI_INTREGS &&
		    n->left && n->left->type && type_is_struct(n->left->type) &&
		    ir_emit_arm64_direct_aggregate_call_to_lvalue(ir, n->left, n->right)) {
			return;
		}
		if (irgen.target_cg == &arm64_codegen &&
		    n->right && n->right->kind == ND_CALL &&
		    ir_arm64_call_uses_nonbyref_aggregate_abi(n->right)) {
			ir_mark_unsupported(ir, "arm64 non-byref aggregate call assignment");
			return;
		}
		if (irgen.target_cg == &arm64_codegen &&
		    n->right && n->right->kind == ND_CALL &&
		    n->right->returns_struct &&
		    n->right->aggregate_abi_class != AGGREGATE_ABI_INTREGS &&
		    n->right->aggregate_abi_class != AGGREGATE_ABI_HFA) {
			ir_mark_unsupported(ir, "arm64 byref struct return assignment");
			return;
		}
		if (irgen.target_cg == &x64_codegen &&
		    n->right && n->right->kind == ND_CALL &&
		    n->right->type &&
		    ir_type_uses_x64_complex_double_abi(n->right->type) &&
		    n->left && n->left->type &&
		    ir_type_uses_x64_complex_double_abi(n->left->type) &&
		    ir_emit_x64_direct_complex_double_call_to_lvalue(ir, n->left, n->right)) {
			return;
		}
		if (n->right && n->right->kind == ND_CALL && n->right->returns_struct &&
		        n->left && n->left->kind == ND_VAR &&
		        n->left->type && type_is_struct(n->left->type)) {
			int count = 0;
			unsigned int fp_arg_mask = 0;
			unsigned int fp_arg_double_mask = 0;
			{
				Node *_ct;
				for (_ct = n->right->args; _ct; _ct = _ct->next) count++;
			}
			{
				Node **args = (Node **)xcalloc(count > 0 ? count : 1, sizeof(Node *));
				{
					int _ci = 0;
					Node *arg;
					for (arg = n->right->args; arg; arg = arg->next) args[_ci++] = arg;
				}

				ir_collect_call_fp_arg_masks(args, count,
				                             &fp_arg_mask,
				                             &fp_arg_double_mask);
				fp_arg_mask <<= 1;        /* hidden struct-return pointer is arg0 */
				fp_arg_double_mask <<= 1; /* hidden struct-return pointer is arg0 */

				{
					int _i;
					for (_i = count - 1; _i >= 0; _i--)
						ir_expr(ir, args[_i]);
				}

				ir_emit_load_addr_local(ir, n->left->name, n->left->offset);
				{
					IRInst *_ci2 = ir_emit_call_direct(ir, n->right->name, count + 1, 0);
					if (_ci2) {
						_ci2->fixed_params = -1; /* struct return: not variadic */
						_ci2->fp_arg_mask = fp_arg_mask;
						_ci2->fp_arg_double_mask = fp_arg_double_mask;
					}
				}
				ir_emit_pop(ir);
				xfree(args);
				return;
			} /* end args block */
		}

		if (n->left && n->left->kind == ND_GLOBAL_INDEX) {
			ir_expr(ir, n->left->left);
			ir_emit_expr_as_type(ir, n->right,
			                     n->left->type ? n->left->type : n->right->type);
			ir_emit_store_global_index(ir, n->left->name, n->left->elem_size ? n->left->elem_size : TCC_SIZEOF_INT, 0);
			return;
		}

		if (n->left && n->left->kind == ND_INDEX) {
			int local_offset = 0;
			int local_size = 0;

			ir_local_const_index_info(n->left, &local_offset, &local_size);
			if (local_size > 0) {
				ir_emit_expr_as_type(ir, n->right,
				                     n->left->type ? n->left->type : n->right->type);
				ir_emit_store_local(ir, n->left->name, local_offset, local_size);
				return;
			}
			/*
			 * Stack order: index, value.  The IR store_indexed emitter pops
			 * value to acc and index to tmp, matching the mature AST path.
			 */
			ir_expr(ir, n->left->left);
			ir_emit_expr_as_type(ir, n->right,
			                     n->left->type ? n->left->type : n->right->type);
			ir_emit_store_indexed(ir, n->left->name, n->left->offset, n->left->elem_size ? n->left->elem_size : TCC_SIZEOF_INT);
			return;
		}

		if (n->left && n->left->kind == ND_DEREF) {
			/*
			 * Stack order: address, value.  The IR store_deref emitter pops
			 * value to acc and address to tmp.
			 * For large struct copies (> 8 bytes), use ptr_copy which keeps
			 * both src and dst pointers available for word-by-word copy.
			 */
			int deref_sz = ir_lvalue_size(n->left);
			const Node *base = NULL;
			int offset = 0;
			if (ir_const_ptr_byte_offset(n->left->left, &base, &offset) &&
			    deref_sz <= 8) {
				if (base && base->kind == ND_VAR) {
					ir_emit_expr_as_type(ir, n->right,
					                     n->left->type ? n->left->type : n->right->type);
					ir_emit_store_local_ptr_member(ir, base->offset, offset, deref_sz);
				} else {
					ir_expr(ir, (Node *)base);
					ir_emit_expr_as_type(ir, n->right,
					                     n->left->type ? n->left->type : n->right->type);
					ir_emit_store_member_ptr(ir, offset, deref_sz);
				}
			} else if (deref_sz <= 8) {
				ir_expr(ir, n->left->left);
				ir_emit_expr_as_type(ir, n->right,
				                     n->left->type ? n->left->type : n->right->type);
				ir_emit_store_member_ptr(ir, 0, deref_sz);
			} else if (deref_sz > 8 && n->right && n->right->kind == ND_DEREF) {
				/* Emit: dst=acc_to_saved, src=acc, then ptr_copy(size) */
				ir_expr(ir, n->left->left);   /* dst ptr in acc */
				ir_emit_acc_to_saved(ir);
				ir_expr(ir, n->right->left);  /* src ptr in acc */
				ir_emit_unop_sized(ir, "ptr_copy", deref_sz);
			} else {
				ir_expr(ir, n->left->left);
				ir_expr(ir, n->right);
				ir_emit_store_deref(ir, deref_sz);
			}
			return;
		}

		if (n->left && n->left->kind == ND_MEMBER_PTR) {
			if (n->left->left && n->left->left->kind == ND_VAR) {
				ir_emit_expr_as_type(ir, n->right,
				                     n->left->type ? n->left->type : n->right->type);
				ir_emit_store_local_ptr_member(ir, n->left->left->offset,
				                               n->left->offset,
				                               ir_lvalue_size(n->left));
			} else {
				ir_expr(ir, n->left->left);
				ir_emit_expr_as_type(ir, n->right,
				                     n->left->type ? n->left->type : n->right->type);
				ir_emit_store_member_ptr(ir, n->left->offset, ir_lvalue_size(n->left));
			}
			return;
		}

		ir_emit_expr_as_type(ir, n->right,
		                     n->left && n->left->type ? n->left->type : n->right->type);
		if (is_simple_lvalue(n->left)) {
			if (n->left->kind == ND_GLOBAL) {
				IRInst *gi = ir_emit_store_global(ir, n->left->name);
				gi->is_extern = ir_global_is_extern(n->left->name);
			} else if (n->left->kind == ND_GLOBAL_INDEX) {
				{
					IRInst *gi = ir_emit_store_global(ir, n->left->name);
					gi->is_extern = ir_global_is_extern(n->left->name);
				}
			} else if (n->left->kind == ND_DEREF) {
				ir_emit_store_deref(ir, ir_lvalue_size(n->left));
			} else if (n->left->kind == ND_MEMBER_PTR) {
				if (n->left->left && n->left->left->kind == ND_VAR)
					ir_emit_store_local_ptr_member(ir, n->left->left->offset,
					                               n->left->offset,
					                               ir_lvalue_size(n->left));
				else
					ir_emit_store_member_ptr(ir, n->left->offset, ir_lvalue_size(n->left));
			} else if (n->left->kind == ND_MEMBER)
				ir_emit_store_local(ir, n->left->name, n->left->offset, ir_lvalue_size(n->left));
			else
				ir_emit_store_local(ir, n->left->name, n->left->offset, ir_lvalue_size(n->left));
		} else {
			ir_mark_unsupported(ir, "complex assignment lvalue");
			ir_emit_unsupported_store(ir, "<lvalue>");
		}
		return;

	case ND_IF: {
		int else_label = new_ir_label();
		int end_label = new_ir_label();

		ir_emit_cond_branch(ir, n->cond, else_label, 0);
		ir_list(ir, n->then_body);
		ir_emit_jump(ir, end_label);
		ir_emit_label_num(ir, else_label);
		ir_list(ir, n->else_body);
		ir_emit_label_num(ir, end_label);
		return;
	}

	case ND_WHILE: {
		int begin_label = new_ir_label();
		int end_label = new_ir_label();

		ir_emit_label_num(ir, begin_label);
		ir_emit_cond_branch(ir, n->cond, end_label, 0);
		push_loop(end_label, begin_label);
		ir_list(ir, n->body);
		pop_loop();
		ir_emit_jump(ir, begin_label);
		ir_emit_label_num(ir, end_label);
		return;
	}

	case ND_DO_WHILE: {
		int begin_label = new_ir_label();
		int continue_label = new_ir_label();
		int end_label = new_ir_label();

		ir_emit_label_num(ir, begin_label);
		push_loop(end_label, continue_label);
		ir_list(ir, n->body);
		pop_loop();
		ir_emit_label_num(ir, continue_label);
		ir_emit_cond_branch(ir, n->cond, begin_label, 1);
		ir_emit_label_num(ir, end_label);
		return;
	}

	case ND_FOR: {
		int begin_label = new_ir_label();
		int continue_label = new_ir_label();
		int end_label = new_ir_label();

		ir_stmt(ir, n->init);
		ir_emit_label_num(ir, begin_label);

		if (n->cond) {
			ir_emit_cond_branch(ir, n->cond, end_label, 0);
		}

		push_loop(end_label, continue_label);
		ir_list(ir, n->body);
		pop_loop();

		ir_emit_label_num(ir, continue_label);
		if (n->inc) {
			ir_expr(ir, n->inc);
			ir_emit_pop(ir);
		}
		ir_emit_jump(ir, begin_label);
		ir_emit_label_num(ir, end_label);
		return;
	}

	case ND_SWITCH: {
		int end_label = new_ir_label();
		int default_label = end_label;
		int first_case_label = 0;
		int duff_cond_label = 0;
		int continue_label = end_label;

		for (Node *c = n->body; c; c = c->next) {
			c->offset = new_ir_label();
			if (!first_case_label && c->kind == ND_CASE)
				first_case_label = c->offset;
			if (c->kind == ND_DEFAULT)
				default_label = c->offset;
		}

		ir_expr(ir, n->cond);
		ir_emit_acc_to_tmp(ir);
		ir_emit_pop(ir);

		for (Node *c = n->body; c; c = c->next) {
			if (c->kind != ND_CASE)
				continue;
			ir_emit_tmp_to_acc(ir);
			ir_emit_const(ir, c->value);
			ir_emit_branch_compare(ir, "je", c->offset, TCC_SIZEOF_INT);
		}

		ir_emit_jump(ir, default_label);

		if (n->inc) {
			duff_cond_label = new_ir_label();
			push_loop(end_label, duff_cond_label);
		} else {
			if (irgen.loop_depth > 0)
				continue_label = current_continue_label(ir);
			push_loop(end_label, continue_label);
		}

		for (Node *c = n->body; c; c = c->next) {
			ir_emit_label_num(ir, c->offset);
			ir_list(ir, c->body);
		}

		if (n->inc) {
			ir_emit_label_num(ir, duff_cond_label);
			ir_expr(ir, n->inc);
			ir_emit_branch_nonzero(ir, first_case_label);
		}

		pop_loop();
		ir_emit_label_num(ir, end_label);
		return;
	}

	case ND_CASE:
	case ND_DEFAULT:
		ir_list(ir, n->body);
		return;

	case ND_BREAK:
		ir_emit_jump(ir, current_break_label(ir));
		return;

	case ND_CONTINUE:
		ir_emit_jump(ir, current_continue_label(ir));
		return;

	default:
		/*
		 * Expression statement: evaluate for side effects, then discard the
		 * expression value if one is produced.  Aggregate copies such as
		 *
		 *     y = x;
		 *
		 * are lowered as ND_STRUCT_ASSIGN and emit only stores; they do not
		 * leave a scalar result on the expression stack.  Emitting IR_POP
		 * after them unbalances the stack and can corrupt the next
		 * expression/return value.
		 */
		if (ir_expr_stmt_is_trivial_discard(n))
			return;
		ir_expr(ir, n);
		if (n->kind != ND_STRUCT_ASSIGN)
			ir_emit_pop(ir);
		return;
	}
}

static void
ir_emit_expr_as_type(IRProgram *ir, Node *expr, Type *target_type)
{
	int dst_size;
	int src_size;
	int src_unsigned;
	int dst_unsigned;

	if (!expr || !target_type) {
		ir_expr(ir, expr);
		return;
	}

	if (type_is_fp_scalar(target_type) &&
	    expr->kind == ND_CAST && expr->left && expr->left->kind == ND_COND) {
		ir_emit_expr_as_type(ir, expr->left, target_type);
		return;
	}

	if (expr->kind == ND_COMMA) {
		ir_stmt(ir, expr->left);
		ir_emit_expr_as_type(ir, expr->right, target_type);
		return;
	}

	if (expr->kind == ND_COND) {
		int else_label = new_ir_label();
		int end_label = new_ir_label();

		ir_emit_cond_branch(ir, expr->cond, else_label, 0);
		ir_emit_expr_as_type(ir, expr->then_body, target_type);
		ir_emit_jump(ir, end_label);
		ir_emit_label_num(ir, else_label);
		ir_emit_expr_as_type(ir, expr->else_body, target_type);
		ir_emit_label_num(ir, end_label);
		return;
	}

	dst_size = type_sizeof(target_type);
	dst_unsigned = type_is_unsigned(target_type);
	src_size = expr->type ? type_sizeof(expr->type) : dst_size;
	src_unsigned = expr->type ? type_is_unsigned(expr->type) : expr->is_unsigned;

	if (type_is_fp_scalar(target_type)) {
		if (expr->type && type_is_fp_scalar(expr->type)) {
			ir_expr(ir, expr);
			if (src_size > 0 && dst_size > 0 && src_size != dst_size) {
				IRInst *inst = ir_emit_unary_op(ir, "cast");
				inst->fp_size = dst_size;
				inst->value = src_size;
				inst->aux = dst_size;
			}
			return;
		}
		if (expr->type && type_is_integer(expr->type)) {
			ir_expr(ir, expr);
			ir_emit_int_to_fp_bits(ir, dst_size > 0 ? dst_size : 8, src_unsigned);
			return;
		}
	}

	if (type_is_integer(target_type) && expr->type && type_is_fp_scalar(expr->type)) {
		ir_expr(ir, expr);
		ir_emit_fp_bits_to_int(ir, src_size > 0 ? src_size : 8, dst_unsigned);
		if (dst_size > 0 && dst_size < 8)
			ir_emit_cast(ir, dst_size, dst_unsigned);
		return;
	}

	ir_expr(ir, expr);
}

static void
ir_emit_return_expr(IRProgram *ir, Node *expr)
{
	int label;

	if (!expr) {
		ir_emit_const(ir, 0);
		ir_emit_return(ir);
		return;
	}

	switch (expr->kind) {
	case ND_COMMA:
		ir_stmt(ir, expr->left);
		ir_emit_return_expr(ir, expr->right);
		return;

	case ND_COND:
		label = new_ir_label();
		ir_emit_cond_branch(ir, expr->cond, label, 0);
		ir_emit_expr_as_type(ir, expr->then_body,
		                     irgen.function_return_type ? irgen.function_return_type : expr->type);
		ir_emit_return(ir);
		ir_emit_label_num(ir, label);
		ir_emit_expr_as_type(ir, expr->else_body,
		                     irgen.function_return_type ? irgen.function_return_type : expr->type);
		ir_emit_return(ir);
		return;

	case ND_LOGICAL_AND:
		label = new_ir_label();
		ir_emit_cond_branch(ir, expr->left, label, 0);
		ir_emit_cond_branch(ir, expr->right, label, 0);
		ir_emit_const(ir, 1);
		ir_emit_return(ir);
		ir_emit_label_num(ir, label);
		ir_emit_const(ir, 0);
		ir_emit_return(ir);
		return;

	case ND_LOGICAL_OR:
		label = new_ir_label();
		ir_emit_cond_branch(ir, expr->left, label, 1);
		ir_emit_cond_branch(ir, expr->right, label, 1);
		ir_emit_const(ir, 0);
		ir_emit_return(ir);
		ir_emit_label_num(ir, label);
		ir_emit_const(ir, 1);
		ir_emit_return(ir);
		return;

	default:
		ir_emit_expr_as_type(ir, expr,
		                     irgen.function_return_type ? irgen.function_return_type : expr->type);
		ir_emit_return(ir);
		return;
	}
}

static int
ir_expr_stmt_is_trivial_discard(const Node *node)
{
	Type *type;

	if (!node)
		return 0;

	if (node->kind == ND_CAST && node->type && type_is_void(node->type))
		return ir_expr_stmt_is_trivial_discard(node->left);

	type = node->type;
	if (type && type_has_qualifier(type, TYPE_QUAL_VOLATILE))
		return 0;
	if (type && (type_is_struct(type) || type_is_union(type) || type_is_array(type)))
		return 0;

	switch (node->kind) {
	case ND_NUM:
	case ND_VAR:
	case ND_GLOBAL:
	case ND_STRING:
	case ND_FUNC_ADDR:
		return 1;
	default:
		return 0;
	}
}

static void
ir_emit_cond_branch(IRProgram *ir, Node *node, int label, int branch_on_true)
{
	const char *cmp_op;
	int skip_label;
	int fp_size;

	if (!node)
		return;
	if (node->kind != ND_DECL && ir_node_uses_floating(node) &&
	    !ir_node_allows_raw_floating(node)) {
		ir_reject_floating_expr(ir, node);
		return;
	}

	switch (node->kind) {
	case ND_NOT:
		ir_emit_cond_branch(ir, node->left, label, !branch_on_true);
		return;

	case ND_LOGICAL_AND:
		if (branch_on_true) {
			skip_label = new_ir_label();
			ir_emit_cond_branch(ir, node->left, skip_label, 0);
			ir_emit_cond_branch(ir, node->right, label, 1);
			ir_emit_label_num(ir, skip_label);
		} else {
			ir_emit_cond_branch(ir, node->left, label, 0);
			ir_emit_cond_branch(ir, node->right, label, 0);
		}
		return;

	case ND_LOGICAL_OR:
		if (branch_on_true) {
			ir_emit_cond_branch(ir, node->left, label, 1);
			ir_emit_cond_branch(ir, node->right, label, 1);
		} else {
			skip_label = new_ir_label();
			ir_emit_cond_branch(ir, node->left, skip_label, 1);
			ir_emit_cond_branch(ir, node->right, label, 0);
			ir_emit_label_num(ir, skip_label);
		}
		return;

	default:
		break;
	}

	cmp_op = ir_node_is_compare(node) ? ir_compare_branch_op(node, branch_on_true) : NULL;
	if (cmp_op) {
		ir_expr(ir, node->left);
		ir_expr(ir, node->right);
		if (ir_node_uses_floating(node))
			ir_emit_branch_compare_fp(ir, cmp_op, label, ir_compare_operand_size(node));
		else
			ir_emit_branch_compare(ir, cmp_op, label, ir_compare_operand_size(node));
		return;
	}

	ir_expr(ir, node);
	fp_size = ir_truth_fp_size(node);
	if (fp_size) {
		ir_emit_const(ir, 0);
		ir_emit_int_to_fp_bits(ir, fp_size, 0);
		ir_emit_branch_compare_fp(ir, branch_on_true ? "jne" : "je",
		                          label, fp_size);
		return;
	}
	if (branch_on_true)
		ir_emit_branch_nonzero(ir, label);
	else
		ir_emit_branch_zero(ir, label);
}


static int
ir_node_can_yield_expression_value(Node *node)
{
	if (!node)
		return 0;
	if (node->kind <= ND_STRUCT_ASSIGN)
		return 1;
	if (node->kind >= ND_DECL && node->kind <= ND_STRUCT_DECL)
		return 0;
	if (node->kind >= ND_RETURN && node->kind <= ND_CONTINUE)
		return 0;
	if (node->kind == ND_ASM)
		return 0;
	return 1;
}

static void
ir_block_expr(IRProgram *ir, Node *block)
{
	Node *last = NULL;

	if (!block || !block->body) {
		ir_emit_const(ir, 0);
		return;
	}

	for (Node *stmt = block->body; stmt; stmt = stmt->next)
		last = stmt;

	for (Node *stmt = block->body; stmt && stmt != last; stmt = stmt->next)
		ir_stmt(ir, stmt);

	if (ir_node_can_yield_expression_value(last)) {
		ir_expr(ir, last);
	} else {
		ir_stmt(ir, last);
		ir_emit_const(ir, 0);
	}
}

static void 
ir_expr(IRProgram *ir, Node *node)
{
	if (!node)
		return;
	if (node->kind != ND_DECL && ir_node_uses_floating(node) &&
	    !ir_node_allows_raw_floating(node)) {
		ir_reject_floating_expr(ir, node);
		return;
	}

	const char *op = binop_name(node->kind);
	if (op) {
		if (node->kind == ND_NEG && ir_node_uses_floating(node)) {
			int size = (node->type && type_sizeof(node->type) > 0) ? type_sizeof(node->type) : 8;
			ir_emit_const(ir, 0);
			ir_expr(ir, node->left);
			ir_emit_binary_op_fp(ir, "sub", size);
			return;
		}

		if (node->is_unsigned) {
			if (node->kind == ND_DIV)
				op = "udiv";
			else if (node->kind == ND_MOD)
				op = "umod";
			else if (node->kind == ND_SHR)
				op = "ushr";
			else if (node->kind == ND_LT)
				op = "ult";
			else if (node->kind == ND_LE)
				op = "ule";
			else if (node->kind == ND_GT)
				op = "ugt";
			else if (node->kind == ND_GE)
				op = "uge";
		}

		if (node->kind == ND_LOGICAL_AND) {
			int false_label = new_ir_label();
			int end_label = new_ir_label();

			/*
			 * C logical AND must short-circuit: the right-hand side is not
			 * evaluated when the left-hand side is false.  This matters for
			 * expressions such as:
			 *
			 *     p && STRCMP(p, "hello") == 0
			 *
			 * The old IR lowering evaluated both sides and then combined their
			 * truth values, which dereferenced NULL in cases like the above.
			 */
			ir_emit_cond_branch(ir, node->left, false_label, 0);

			ir_emit_cond_branch(ir, node->right, false_label, 0);

			ir_emit_const(ir, 1);
			ir_emit_jump(ir, end_label);

			ir_emit_label_num(ir, false_label);
			ir_emit_const(ir, 0);

			ir_emit_label_num(ir, end_label);
			return;
		}

		if (node->kind == ND_LOGICAL_OR) {
			int true_label = new_ir_label();
			int end_label = new_ir_label();

			/* Logical OR short-circuits when the left-hand side is true. */
			ir_emit_cond_branch(ir, node->left, true_label, 1);

			ir_emit_cond_branch(ir, node->right, true_label, 1);

			ir_emit_const(ir, 0);
			ir_emit_jump(ir, end_label);

			ir_emit_label_num(ir, true_label);
			ir_emit_const(ir, 1);

			ir_emit_label_num(ir, end_label);
			return;
		}

		if ((node->kind == ND_SHL || node->kind == ND_SHR) &&
		    node->right && node->right->kind == ND_NUM &&
		    node->right->long_value >= 0 &&
		    node->right->long_value < 64) {
			ir_expr(ir, node->left);
			if (node->kind == ND_SHL)
				ir_emit_shift_imm(ir, "shl_imm", node->right->long_value);
			else if (node->is_unsigned)
				ir_emit_shift_imm(ir, "ushr_imm", node->right->long_value);
			else
				ir_emit_shift_imm(ir, "shr_imm", node->right->long_value);
			return;
		}

		if (ir_node_uses_floating(node)) {
			int size = ir_binary_fp_operand_size(node);
			if (size == 0)
				size = ir_raw_floating_expr_size(node->left);
			if (size == 0)
				size = ir_raw_floating_expr_size(node->right);
			ir_emit_float_operand(ir, node->left, size);
			ir_emit_float_operand(ir, node->right, size);
			ir_emit_binary_op_fp(ir, op, size > 0 ? size : 8);
			return;
		}

		ir_expr(ir, node->left);
		ir_expr(ir, node->right);

		if ((node->kind == ND_ADD || node->kind == ND_SUB) && node->is_pointer) {
			int scale = node->elem_size ? node->elem_size : 1;
			ir_emit_binop_scaled(ir, node->kind == ND_ADD ? "ptr_add" : "ptr_sub", scale);
		} else {
			/* Pass elem_size for operations where backends may need to
			 * choose a 32-bit vs 64-bit instruction sequence. */
			int is_cmp = (node->kind == ND_EQ || node->kind == ND_NE ||
			              node->kind == ND_LT || node->kind == ND_LE ||
			              node->kind == ND_GT || node->kind == ND_GE);
			int is_sized_arith = (node->kind == ND_MUL ||
			                      node->kind == ND_DIV ||
			                      node->kind == ND_MOD);
			if ((is_cmp || is_sized_arith) && node->elem_size > 0)
				ir_emit_binary_op_sized(ir, op, node->elem_size);
			else
				ir_emit_binary_op(ir, op);
		}

		return;
	}

	switch (node->kind) {
	case ND_BLOCK:
		ir_block_expr(ir, node);
		return;

	case ND_NUM:
		if (node->is_fp_num) {
			ir_emit_const(ir, (long)ir_fp_literal_bits(node));
			return;
		}
		ir_emit_const(ir, node->long_value);
		return;

	case ND_VAR:
		/* C array-to-pointer decay: local arrays used as rvalues produce
		 * their address.  Do not emit a scalar load from the first bytes.
		 */
		if (node->type && type_is_array(node->type)) {
			ir_emit_load_addr_local(ir, node->name, node->offset);
			return;
		}
		ir_emit_load_local(ir, node->name, node->offset,
		                   node->is_pointer ? TCC_SIZEOF_PTR : ir_lvalue_size(node));
		ir_emit_scalar_load_cast(ir, node);
		return;

	case ND_GLOBAL: {
		IRInst *gi = ir_emit_load_global(ir, node->name);
		gi->aux = node->is_pointer ? TCC_SIZEOF_PTR : ir_lvalue_size(node);
		gi->is_extern = ir_global_is_extern(node->name);
		ir_emit_scalar_load_cast(ir, node);
	}
	return;

	case ND_STRING:
		ir_add_string_len_width(ir, node->string_label, node->string_value, node->string_len, node->string_width ? node->string_width : 1);
		ir_emit_load_string(ir, node->string_value, node->string_label);
		return;

	case ND_FUNC_ADDR:
		ir_emit_load_funcaddr(ir, node->name);
		return;

	case ND_NEG:
		if (ir_node_uses_floating(node)) {
			int size = (node->type && type_sizeof(node->type) > 0) ? type_sizeof(node->type) : 8;
			ir_emit_const(ir, 0);
			ir_expr(ir, node->left);
			ir_emit_binary_op_fp(ir, "sub", size);
			return;
		}
		ir_expr(ir, node->left);
		ir_emit_unary_op(ir, "neg");
		return;

	case ND_BITNOT:
		ir_expr(ir, node->left);
		ir_emit_unary_op(ir, "bitnot");
		return;

	case ND_NOT:
		if (ir_node_uses_floating(node)) {
			int true_label = new_ir_label();
			int end_label = new_ir_label();

			ir_emit_cond_branch(ir, node->left, true_label, 0);
			ir_emit_const(ir, 0);
			ir_emit_jump(ir, end_label);
			ir_emit_label_num(ir, true_label);
			ir_emit_const(ir, 1);
			ir_emit_label_num(ir, end_label);
			return;
		}
		ir_expr(ir, node->left);
		ir_emit_unary_op(ir, "not");
		return;

	case ND_COND: {
		if (node->cond && node->cond->kind == ND_NUM) {
			ir_expr(ir, node->cond->value ? node->then_body : node->else_body);
			return;
		}

		/* ternary: cond ? then_expr : else_expr */
		int else_label = new_ir_label();
		int end_label  = new_ir_label();

		ir_emit_cond_branch(ir, node->cond, else_label, 0);
		ir_expr(ir, node->then_body);
		ir_emit_jump(ir, end_label);
		ir_emit_label_num(ir, else_label);
		ir_expr(ir, node->else_body);
		ir_emit_label_num(ir, end_label);
		return;
	}

	case ND_COMMA:
		/* evaluate left as statement (side effect), then produce right as value */
		ir_stmt(ir, node->left);
		ir_expr(ir, node->right);
		return;

	case ND_CAST:
	{
		int dst_size = node->type ? type_sizeof(node->type) : 4;
		int dst_unsigned = node->type ? type_is_unsigned(node->type) : 0;
		int src_size = (node->left && node->left->type) ? type_sizeof(node->left->type) : dst_size;
		int src_unsigned = (node->left && node->left->type) ? type_is_unsigned(node->left->type) : dst_unsigned;

		if (node->type && type_is_fp_scalar(node->type) &&
		    node->left && ir_raw_floating_expr_size(node->left) != 0 &&
		    ir_node_allows_raw_floating(node->left)) {
			ir_expr(ir, node->left);
			if (src_size != dst_size) {
				IRInst *inst = ir_emit_unary_op(ir, "cast");
				inst->fp_size = dst_size > 0 ? dst_size : 8;
				inst->value = src_size > 0 ? src_size : 8;
				inst->aux = dst_size > 0 ? dst_size : 8;
			}
			return;
		}
		if (node->type && type_is_fp_scalar(node->type) &&
		    node->left && ir_node_can_promote_integer_to_float(node->left)) {
			ir_expr(ir, node->left);
			ir_emit_int_to_fp_bits(ir, dst_size > 0 ? dst_size : 8, src_unsigned);
			return;
		}
		if (node->type && type_is_integer(node->type) &&
		    node->left && node->left->type && type_is_fp_scalar(node->left->type)) {
			ir_expr(ir, node->left);
			ir_emit_fp_bits_to_int(ir, src_size > 0 ? src_size : 8, dst_unsigned);
			if (dst_size < 8)
				ir_emit_cast(ir, dst_size, dst_unsigned);
			return;
		}

		ir_expr(ir, node->left);

		/* Widening casts are controlled by the source width/signedness.
		 * For example, (long long)(int)-7 must sign-extend from 32 bits,
		 * while (unsigned long long)(unsigned int)-1 must zero-extend. */
		if (dst_size > src_size && src_size < 8)
			ir_emit_cast(ir, src_size, src_unsigned);
		else
			ir_emit_cast(ir, dst_size, dst_unsigned);
		return;
	}

	case ND_CALL: {
		Node **args;
		int count;
		int fixed_params;
		unsigned int fp_arg_mask = 0;
		unsigned int fp_arg_double_mask = 0;

		ir_trace_call_abi("expr-call-enter", node);

		if (ir_x86_call_has_struct_value_arg(node)) {
			ir_mark_unsupported(ir, "x86 struct-by-value call");
			return;
		}
		if (irgen.target_cg == &arm64_codegen &&
		    ir_arm64_emit_single_hfa_aggregate_call(ir, node, 0)) {
			return;
		}
		if (irgen.target_cg == &arm64_codegen &&
		    ir_arm64_emit_single_intregs_aggregate_call(ir, node, 0)) {
			return;
		}
		if (irgen.target_cg == &arm64_codegen &&
		    ir_arm64_emit_mixed_hfa_gpr_call(ir, node, 0)) {
			return;
		}
		if (irgen.target_cg == &x64_codegen &&
		    ir_x64_emit_single_complex_double_call(ir, node, 0)) {
			return;
		}
		if (irgen.target_cg == &x64_codegen &&
		    ir_x64_emit_mixed_complex_double_gpr_call(ir, node, 0)) {
			return;
		}
		if (irgen.target_cg == &arm64_codegen &&
		    ir_arm64_call_uses_nonbyref_aggregate_abi(node)) {
			ir_mark_unsupported(ir, "arm64 non-byref aggregate call");
			return;
		}
		if (node->returns_struct &&
		    !ir_node_returns_x64_direct_complex_abi(node)) {
			ir_mark_unsupported(ir, "struct-returning call");
			return;
		}
		if (ir_emit_stack_builtin_call(ir, node, 0)) {
			return;
		}

		/* Count args, then allocate array */
		count = 0;
		{
			Node *_ct;
			for (_ct = node->args; _ct; _ct = _ct->next) count++;
		}
		args = (Node **)xcalloc(count > 0 ? count : 1, sizeof(Node *));
		{
			int _ci = 0;
			Node *_arg;
			for (_arg = node->args; _arg; _arg = _arg->next) args[_ci++] = _arg;
		}
		ir_collect_call_fp_arg_masks(args, count, &fp_arg_mask, &fp_arg_double_mask);
		fixed_params = node->left ? -1 : func_fixed_params(node->name);

		/*
		 * Fast path for common one-argument direct calls where the
		 * argument can be left directly in the accumulator and moved
		 * straight into x0 without building the temporary arg stack.
		 */
		if (!node->left && count == 1 && ir_arm64_direct_gpr_arg_ok(args[0])) {
			if (args[0]->kind == ND_STRING) {
				ir_add_string_len_width(ir, args[0]->string_label, args[0]->string_value,
				                        args[0]->string_len,
				                        args[0]->string_width ? args[0]->string_width : 1);
				ir_emit_load_string_acc(ir, args[0]->string_value, args[0]->string_label);
			} else {
				ir_expr(ir, args[0]);
				ir_emit_pop(ir);
			}
			{
				IRInst *ci = ir_emit_call_acc_arg0(ir, node->name, 0);
				if (ci && node->type &&
				    (type_is_fp_scalar(node->type) ||
				     ir_type_uses_x64_complex_float_abi(node->type))) {
					ci->result_is_fp = 1;
					ci->result_size = type_sizeof(node->type);
				}
			}
			xfree(args);
			return;
		}

		if (!node->left && count > 0 && count <= IR_SIMPLE_CALL_MAX_ARGS &&
		    fp_arg_mask == 0 &&
		    !(irgen.target_cg == &x64_codegen &&
		      ir_call_has_x64_complex_double_abi_arg(node))) {
			IRSimpleCallArg simple_args[IR_SIMPLE_CALL_MAX_ARGS];
			int simple_ok = 1;
			int i;

			memset(simple_args, 0, sizeof(simple_args));

			for (i = 0; i < count; i++) {
				if (!ir_try_capture_simple_call_arg(ir, &simple_args[i], args[i])) {
					simple_ok = 0;
					break;
				}
			}
			if (simple_ok) {
				IRInst *ci = ir_emit_call_direct(ir, node->name, count, 0);

				ci->fixed_params = fixed_params;
				ci->simple_call_arg_count = (uint8_t)count;
				for (i = 0; i < count; i++)
					ci->simple_call_args[i] = simple_args[i];
				if (node->type &&
				    (type_is_fp_scalar(node->type) ||
				     ir_type_uses_x64_complex_float_abi(node->type))) {
					ci->result_is_fp = 1;
					ci->result_size = type_sizeof(node->type);
				}
				xfree(args);
				return;
			}
			for (i = 0; i < IR_SIMPLE_CALL_MAX_ARGS; i++)
				xfree(simple_args[i].name);
		}

		/* Evaluate args right-to-left */
		{
			int _i;
			for (_i = count - 1; _i >= 0; _i--)
				ir_expr(ir, args[_i]);
		}

		if (node->left) {
			ir_expr(ir, node->left);
			{
				IRInst *ci = ir_emit_call_indirect(ir, count, 0);
				if (ci && node->type &&
				    (type_is_fp_scalar(node->type) ||
				     ir_type_uses_x64_complex_float_abi(node->type))) {
					ci->result_is_fp = 1;
					ci->result_size = type_sizeof(node->type);
				}
				if (ci) {
					ci->fixed_params = -1;
					ci->fp_arg_mask = fp_arg_mask;
					ci->fp_arg_double_mask = fp_arg_double_mask;
				}
			}
		} else {
			IRInst *_ci = ir_emit_call_direct(ir, node->name, count, 0);
			if (_ci) {
				_ci->fixed_params = fixed_params;
				_ci->fp_arg_mask = fp_arg_mask;
				_ci->fp_arg_double_mask = fp_arg_double_mask;
				if (node->type &&
				    (type_is_fp_scalar(node->type) ||
				     ir_type_uses_x64_complex_float_abi(node->type))) {
					_ci->result_is_fp = 1;
					_ci->result_size = type_sizeof(node->type);
				}
			}
		}
		xfree(args);
		return;
	}

	case ND_ASSIGN:
		ir_stmt(ir, node);
		/*
		 * Scalar assignment expressions produce the assigned value by
		 * reloading the lhs.  Struct assignment is lowered as a copy and
		 * currently has no first-class aggregate expression result in this
		 * IR, so do not reload/push a bogus scalar field for aggregate lhs.
		 */
		if (node->left &&
		        (!node->left->type || !type_is_struct(node->left->type)))
			ir_expr(ir, node->left);
		return;

	case ND_PRE_INC:
	case ND_PRE_DEC:
	case ND_POST_INC:
	case ND_POST_DEC:
		ir_incdec_expr(ir, node);
		return;

	case ND_ADDR:
		if (node->left && node->left->kind == ND_VAR) {
			ir_emit_load_addr_local(ir, node->left->name, node->left->offset);
			return;
		}

		if (node->left && node->left->kind == ND_GLOBAL) {
			ir_emit_load_addr_global(ir, node->left->name);
			return;
		}

		if (node->left && node->left->kind == ND_DEREF) {
			const Node *base = NULL;
			int offset = 0;

			if (ir_const_ptr_byte_offset(node->left->left, &base, &offset)) {
				ir_expr(ir, (Node *)base);
				if (offset)
					ir_emit_add_offset(ir, offset);
			} else {
				ir_expr(ir, node->left->left);
			}
			return;
		}

			if (node->left && node->left->kind == ND_INDEX) {
				int local_offset = 0;
				int local_size = 0;

				ir_local_const_index_info(node->left, &local_offset, &local_size);
				if (local_size > 0) {
					ir_emit_load_addr_local(ir, node->left->name, local_offset);
					return;
				}
				ir_expr(ir, node->left->left);
				ir_emit_unop_indexed(ir, "addr_indexed", node->left->name, node->left->offset, node->left->elem_size ? node->left->elem_size : 4);
				return;
			}

		if (node->left && node->left->kind == ND_MEMBER) {
			ir_emit_load_addr_local(ir, node->left->name, node->left->offset);
			return;
		}

		if (node->left && node->left->kind == ND_MEMBER_PTR) {
			ir_expr(ir, node->left->left);
			ir_emit_add_offset(ir, node->left->offset);
			return;
		}

		if (node->left && node->left->kind == ND_GLOBAL_INDEX) {
			/* &arr[i] -> address of global array element */
			ir_expr(ir, node->left->left); /* index */
			ir_emit_unop_indexed(ir, "addr_gidx", node->left->name, 0, node->left->elem_size ? node->left->elem_size : 4);
			return;
		}

		ir_mark_unsupported(ir, "address-of complex lvalue");
		return;

	case ND_DEREF:
		if (!node->is_bitfield && node->left && !type_is_array(node->type)) {
			const Node *base = NULL;
			int global_offset = 0;
			if (ir_const_global_byte_offset(node->left, &global_offset)) {
				IRInst *gi = ir_emit_load_global_member(ir, node->left->name, global_offset,
				                                        ir_lvalue_size(node));
				gi->is_extern = ir_global_is_extern(node->left->name);
				ir_emit_scalar_load_cast(ir, node);
				return;
			}
			if (ir_const_ptr_byte_offset(node->left, &base, &global_offset)) {
				ir_expr(ir, (Node *)base);
				ir_emit_raw(ir, IR_UNOP, "member_ptr", NULL, global_offset,
				            ir_lvalue_size(node));
				ir_emit_scalar_load_cast(ir, node);
				return;
			}
		}
		ir_expr(ir, node->left);
		/* If the dereferenced type is itself an array (e.g. g->init_syms[slot]
		 * where init_syms is char[128][64], giving a char[64] element), the result
		 * decays to a pointer — leave the address on the stack, don't load. */
		if (node->type && type_is_array(node->type))
			return;
		/* Route scalar dereferences through member_ptr offset 0 so later IR
		 * emission can fold integer promotion/sign-extension into the load
		 * itself (for example ldrb/ldrsh/ldrsw on arm64). */
		ir_emit_raw(ir, IR_UNOP, "member_ptr", NULL, 0, ir_lvalue_size(node));
		ir_emit_scalar_load_cast(ir, node);
		return;

		case ND_INDEX:
		{
			int local_offset = 0;
			int local_size = 0;

			ir_local_const_index_info(node, &local_offset, &local_size);
			if (local_size > 0) {
				ir_emit_load_local(ir, node->name, local_offset, local_size);
				ir_emit_scalar_load_cast(ir, node);
				return;
			}
			ir_expr(ir, node->left);
			ir_emit_unop_indexed(ir, "load_indexed", node->name, node->offset, ir_lvalue_size(node));
			ir_emit_scalar_load_cast(ir, node);
			return;
		}

	case ND_GLOBAL_INDEX:
		ir_expr(ir, node->left);
		if (node->is_array_field) {
			/* Array field: emit address, not load */
			ir_emit_unop_indexed(ir, "addr_gidx", node->name, 0, 1);
		} else {
			ir_emit_unop_indexed(ir, "gidx_load", node->name, node->elem_size ? node->elem_size : TCC_SIZEOF_INT, 0);
			ir_emit_scalar_load_cast(ir, node);
		}
		return;

	case ND_MEMBER:
		if (node->is_array_field) {
			/* Local struct array member used as an expression decays to &member[0]. */
			ir_emit_load_addr_local(ir, node->name, node->offset);
		} else if (!node->is_bitfield && ir_global_lookup_find(node->name)) {
			IRInst *gi = ir_emit_load_global_member(ir, node->name, node->offset,
			                                        ir_lvalue_size(node));
			gi->is_extern = ir_global_is_extern(node->name);
			ir_emit_scalar_load_cast(ir, node);
		} else {
			ir_emit_load_local(ir, node->name, node->offset,
			                   node->is_bitfield ? node->bit_storage_size :
			                   ir_lvalue_size(node));
			if (node->is_bitfield)
				ir_emit_bitfield_extract(ir, node);
			else
				ir_emit_scalar_load_cast(ir, node);
		}
		return;

	case ND_MEMBER_PTR:
		ir_expr(ir, node->left);
		if (!node->is_array_field) {
			ir_emit_raw(ir, IR_UNOP, "member_ptr", NULL, node->offset,
			            node->is_bitfield ? node->bit_storage_size :
			            (node->elem_size ? node->elem_size : TCC_SIZEOF_INT));
			if (node->is_bitfield)
				ir_emit_bitfield_extract(ir, node);
			else
				ir_emit_scalar_load_cast(ir, node);
		} else if (node->offset) {
			ir_emit_add_offset(ir, node->offset);
		}
		/* Array fields decay to pointer — just leave the address in acc */
		return;

	case ND_STRUCT_ASSIGN:
		if (!node->left || !node->right) {
			ir_mark_unsupported(ir, "non-local struct assignment");
			return;
		}

		{
			Node *src = node->right;

			while (src && src->kind == ND_COMMA) {
				ir_stmt(ir, src->left);
				src = src->right;
			}

			if (src && src->kind == ND_COND &&
			    src->cond && src->then_body && src->else_body) {
				int else_label = new_ir_label();
				int end_label = new_ir_label();

				ir_emit_cond_branch(ir, src->cond, else_label, 0);
				if (!ir_emit_struct_lvalue_address(ir, node->left)) {
					ir_mark_unsupported(ir, "non-local struct conditional assignment");
					return;
				}
				ir_emit_acc_to_saved(ir);
				if (!ir_emit_struct_lvalue_address(ir, src->then_body)) {
					ir_mark_unsupported(ir, "non-local struct conditional assignment");
					return;
				}
				ir_emit_unop_sized(ir, "ptr_copy", node->value);
				ir_emit_jump(ir, end_label);
				ir_emit_label_num(ir, else_label);
				if (!ir_emit_struct_lvalue_address(ir, node->left)) {
					ir_mark_unsupported(ir, "non-local struct conditional assignment");
					return;
				}
				ir_emit_acc_to_saved(ir);
				if (!ir_emit_struct_lvalue_address(ir, src->else_body)) {
					ir_mark_unsupported(ir, "non-local struct conditional assignment");
					return;
				}
				ir_emit_unop_sized(ir, "ptr_copy", node->value);
				ir_emit_label_num(ir, end_label);
				return;
			}
		}

		if (irgen.target_cg == &arm64_codegen) {
			Node *src = node->right;
			if (src && src->kind == ND_COMMA)
				src = src->right;
			if (src && src->kind == ND_CALL &&
			    src->returns_struct &&
			    src->aggregate_abi_class == AGGREGATE_ABI_HFA &&
			    ir_emit_arm64_direct_hfa_call_to_lvalue(ir, node->left, src)) {
				return;
			}
			if (src && src->kind == ND_CALL &&
			    src->returns_struct &&
			    src->aggregate_abi_class == AGGREGATE_ABI_INTREGS &&
			    ir_emit_arm64_direct_aggregate_call_to_lvalue(ir, node->left, src)) {
				return;
			}
			if (src && src->kind == ND_CALL &&
			    src->returns_struct &&
			    src->aggregate_abi_class != AGGREGATE_ABI_INTREGS) {
				ir_mark_unsupported(ir, "arm64 byref struct return assignment");
				return;
			}
		}
		if (irgen.target_cg == &x64_codegen) {
			Node *src = node->right;

			if (src && src->kind == ND_COMMA)
				src = src->right;
			if (src && src->kind == ND_CALL &&
			    src->type &&
			    ir_type_uses_x64_complex_double_abi(src->type) &&
			    ir_emit_x64_direct_complex_double_call_to_lvalue(ir, node->left, src)) {
				return;
			}
		}

		if (!ir_emit_struct_lvalue_address(ir, node->left)) {
			ir_mark_unsupported(ir, "non-local struct assignment");
			return;
		}
		ir_emit_acc_to_saved(ir);

		if (!ir_emit_struct_lvalue_address(ir, node->right)) {
			ir_mark_unsupported(ir, "non-local struct assignment");
			return;
		}

		ir_emit_unop_sized(ir, "ptr_copy", node->value);
		return;

	default:
		ir_mark_unsupported(ir, "unhandled AST node in IR lowering");
		return;
	}
}

IRProgram *
ir_build(Node *program)
{
	IRProgram *ir = xcalloc(1, sizeof(IRProgram));
	irgen_reset_for_build();
	ir_list(ir, program);
	ir->next_label_limit = irgen.next_label;
	return ir;
}


static void
ir_binop_to_shift_left(IRInst *inst)
{
	STRNCPY(inst->op, "shl", sizeof(inst->op) - 1);
	inst->op[sizeof(inst->op) - 1] = '\0';
	inst->subop = IR_OP_SHL;
	inst->aux = 0;
}

static int 
ir_eval_binop(const char *op, long lhs, long rhs, long *out)
{
	if (STRCMP(op, "add") == 0) *out = lhs + rhs;
	else if (STRCMP(op, "sub") == 0) *out = lhs - rhs;
	else if (STRCMP(op, "mul") == 0) *out = lhs * rhs;
	else if (STRCMP(op, "div") == 0) {
		if (rhs == 0)
			return 0;
		*out = lhs / rhs;
	} else if (STRCMP(op, "and") == 0) *out = lhs & rhs;
	else if (STRCMP(op, "or") == 0) *out = lhs | rhs;
	else if (STRCMP(op, "xor") == 0) *out = lhs ^ rhs;
	else if (STRCMP(op, "shl") == 0) *out = lhs << rhs;
	else if (STRCMP(op, "shr") == 0) *out = lhs >> rhs;
	else if (STRCMP(op, "eq") == 0) *out = lhs == rhs;
	else if (STRCMP(op, "ne") == 0) *out = lhs != rhs;
	else if (STRCMP(op, "lt") == 0) *out = lhs < rhs;
	else if (STRCMP(op, "le") == 0) *out = lhs <= rhs;
	else if (STRCMP(op, "gt") == 0) *out = lhs > rhs;
	else if (STRCMP(op, "ge") == 0) *out = lhs >= rhs;
	else return 0;

	return 1;
}

static int 
ir_eval_unop(const char *op, long value, long imm, long *out)
{
	if (STRCMP(op, "neg") == 0) *out = -value;
	else if (STRCMP(op, "not") == 0) *out = !value;
	else if (STRCMP(op, "cast") == 0) *out = value;
	else if (STRCMP(op, "shl_imm") == 0) *out = value << imm;
	else if (STRCMP(op, "shr_imm") == 0) *out = value >> imm;
	else if (STRCMP(op, "ushr_imm") == 0) *out = (long)((unsigned long)value >> imm);
	else return 0;

	return 1;
}

static int 
ir_is_side_effect_or_barrier(IRInst *inst)
{
	if (!inst)
		return 0;

	switch (inst->kind) {
	case IR_STORE:
	case IR_CALL:
	case IR_CALL_ACC_ARG0:
	case IR_CALL_PACKED_GPR:
	case IR_ASM:
	case IR_BRANCH:
	case IR_RETURN:
	case IR_LABEL:
		return 1;
	default:
		return 0;
	}
}

static IRInst *
ir_prev_inst(IRProgram *program, IRInst *target)
{
	IRInst *prev = NULL;
	for (IRInst *inst = program->head; inst && inst != target; inst = inst->next)
		prev = inst;
	return prev;
}

static int
ir_prev_is_long_const(IRInst *prev, long *value)
{
	if (!prev || prev->kind != IR_CONST)
		return 0;

	*value = prev->value;
	return 1;
}

static int 
ir_prev_is_local_load(IRInst *prev, int *slot)
{
	if (!prev || !ir_is_local_scalar_load(prev))
		return 0;

	*slot = prev->value;
	return 1;
}

static int 
ir_valid_copy_slot(int slot)
{
	int idx = (-slot) / 8; /* normalise byte offset to slot index */
	return idx >= 0 && idx < 512;
}

typedef struct IRLocalCopyState {
	unsigned char known[512];
	int source[512];
} IRLocalCopyState;

typedef struct IRLocalConstState {
	unsigned char known[512];
	long value[512];
} IRLocalConstState;

typedef struct IRMaterializedLocalStateEntry {
	unsigned char known;
	uint8_t subop;
	int slot;
	int size;
	int is_extern;
	long value;
	const char *name;
} IRMaterializedLocalStateEntry;

#define IR_MATERIALIZED_LOCAL_STATE_MAX 64

typedef struct IRMaterializedLocalState {
	IRMaterializedLocalStateEntry entries[IR_MATERIALIZED_LOCAL_STATE_MAX];
} IRMaterializedLocalState;

static int
ir_local_slot_index(int slot)
{
	int idx = (-slot) / 8;

	if (idx < 0 || idx >= 512)
		return -1;
	return idx;
}

static void
ir_local_copy_state_clear(IRLocalCopyState *state)
{
	memset(state, 0, sizeof(*state));
}

static void
ir_local_copy_state_invalidate_source(IRLocalCopyState *state, int slot)
{
	for (int i = 0; i < 512; i++) {
		if (state->known[i] && state->source[i] == slot)
			state->known[i] = 0;
	}
}

static int
ir_local_copy_state_try_rewrite_load(IRLocalCopyState *state, IRInst *inst)
{
	int idx;

	if (!ir_is_local_scalar_load(inst))
		return 0;

	idx = ir_local_slot_index(inst->value);
	if (idx < 0 || !state->known[idx] || inst->value == state->source[idx])
		return 0;

	inst->value = state->source[idx];
	return 1;
}

static void
ir_local_copy_state_record_store(IRLocalCopyState *state, IRInst *store, IRInst *prev)
{
	int dst;
	int dst_idx;
	int src;

	if (!ir_is_local_scalar_store(store))
		return;

	dst = store->value;
	dst_idx = ir_local_slot_index(dst);
	ir_local_copy_state_invalidate_source(state, dst);

	if (dst_idx < 0)
		return;

	if (ir_prev_is_local_load(prev, &src) &&
	    src != dst &&
	    ir_valid_copy_slot(src)) {
		state->known[dst_idx] = 1;
		state->source[dst_idx] = src;
		return;
	}

	state->known[dst_idx] = 0;
}

static void
ir_local_const_state_clear(IRLocalConstState *state)
{
	memset(state, 0, sizeof(*state));
}

static void
ir_materialized_local_state_clear(IRMaterializedLocalState *state)
{
	memset(state, 0, sizeof(*state));
}

static int
ir_is_reusable_materialized_load(IRInst *inst)
{
	if (!inst || inst->kind != IR_LOAD)
		return 0;

	switch ((IRSubOp)inst->subop) {
	case IR_OP_GLOBAL:
	case IR_OP_GLOBAL_MEMBER:
	case IR_OP_STRING:
	case IR_OP_ADDR_GLOBAL:
	case IR_OP_FUNCADDR:
		return 1;
	default:
		return 0;
	}
}

static int
ir_materialized_load_matches_entry(const IRMaterializedLocalStateEntry *entry, IRInst *inst)
{
	if (!entry || !entry->known || !ir_is_reusable_materialized_load(inst) ||
	    entry->subop != inst->subop ||
	    entry->size != ir_effective_load_size(inst) ||
	    entry->is_extern != inst->is_extern)
		return 0;

	switch ((IRSubOp)inst->subop) {
	case IR_OP_STRING:
		return entry->value == inst->value;
	case IR_OP_GLOBAL:
	case IR_OP_ADDR_GLOBAL:
	case IR_OP_FUNCADDR:
		return entry->name && inst->name && STRCMP(entry->name, inst->name) == 0;
	case IR_OP_GLOBAL_MEMBER:
		return entry->value == inst->value &&
		       entry->name && inst->name &&
		       STRCMP(entry->name, inst->name) == 0;
	default:
		return 0;
	}
}

static void
ir_materialized_local_state_invalidate_slot(IRMaterializedLocalState *state, int slot)
{
	for (int i = 0; i < IR_MATERIALIZED_LOCAL_STATE_MAX; i++) {
		if (state->entries[i].known && state->entries[i].slot == slot)
			state->entries[i].known = 0;
	}
}

static void
ir_rewrite_load_as_local(IRInst *inst, int slot, int size)
{
	inst->kind = IR_LOAD;
	inst->value = slot;
	inst->aux = size;
	inst->is_static = 0;
	inst->is_extern = 0;
	inst->fixed_params = 0;
	inst->result_size = 0;
	inst->result_is_fp = 0;
	inst->fp_size = 0;
	inst->extra = 0;
	inst->fp_arg_mask = 0;
	inst->fp_arg_double_mask = 0;
	snprintf(inst->op, sizeof(inst->op), "local");
	inst->subop = IR_OP_LOCAL;
	ir_inst_clear_simple_call_args(inst);
	xfree(inst->name);
	inst->name = xstrdup("");
}

static int
ir_materialized_local_state_try_rewrite_load(IRMaterializedLocalState *state, IRInst *inst)
{
	for (int i = 0; i < IR_MATERIALIZED_LOCAL_STATE_MAX; i++) {
		IRMaterializedLocalStateEntry *entry = &state->entries[i];

		if (!ir_materialized_load_matches_entry(entry, inst))
			continue;

		ir_rewrite_load_as_local(inst, entry->slot, entry->size);
		return 1;
	}

	return 0;
}

static IRInst *
ir_materialized_local_store_source(IRInst *store, IRInst *prev, IRInst *prev_prev)
{
	IRInst *src;
	int store_size;

	if (!ir_is_local_forwardable_store(store))
		return NULL;

	store_size = store->aux ? store->aux : TCC_SIZEOF_INT;

	src = prev;
	if (ir_is_reusable_materialized_load(src) &&
	    ir_effective_load_size(src) == store_size)
		return src;

	if (prev && prev->kind == IR_UNOP && prev->subop == IR_OP_CAST &&
	    prev_prev && ir_is_reusable_materialized_load(prev_prev) &&
	    prev->value == store_size &&
	    ir_effective_load_size(prev_prev) == store_size)
		return prev_prev;

	return NULL;
}

static void
ir_materialized_local_state_record_store(IRMaterializedLocalState *state, IRInst *store,
                                         IRInst *prev, IRInst *prev_prev)
{
	IRMaterializedLocalStateEntry *entries = state->entries;
	IRMaterializedLocalStateEntry *entry;
	IRInst *src;
	int dst;
	int free_idx = -1;
	int match_idx = -1;

	if (!ir_is_local_forwardable_store(store))
		return;

	dst = store->value;
	ir_materialized_local_state_invalidate_slot(state, dst);

	src = ir_materialized_local_store_source(store, prev, prev_prev);
	if (!src)
		return;

	for (int i = 0; i < IR_MATERIALIZED_LOCAL_STATE_MAX; i++) {
		entry = &entries[i];
		if (!entry->known) {
			if (free_idx < 0)
				free_idx = i;
			continue;
		}
		if (ir_materialized_load_matches_entry(entry, src)) {
			match_idx = i;
			break;
		}
	}

	if (match_idx < 0)
		match_idx = free_idx >= 0 ? free_idx : 0;

	entry = &entries[match_idx];
	entry->known = 1;
	entry->subop = src->subop;
	entry->slot = dst;
	entry->size = store->aux ? store->aux : TCC_SIZEOF_INT;
	entry->is_extern = src->is_extern;
	entry->value = src->value;
	entry->name = src->name;
}

static int
ir_local_const_state_try_rewrite_load(IRLocalConstState *state, IRInst *inst)
{
	int idx;

	if (!ir_is_local_scalar_load(inst))
		return 0;

	idx = ir_local_slot_index(inst->value);
	if (idx < 0 || !state->known[idx] ||
	    !ir_local_const_trackable_size(inst->aux))
		return 0;

	ir_make_const(inst, state->value[idx]);
	return 1;
}

static void
ir_local_const_state_record_prev_const(IRLocalConstState *state, IRInst *store, IRInst *prev)
{
	int idx;
	long value;

	if (!ir_is_local_scalar_store(store) ||
	    !ir_local_const_trackable_size(store->aux))
		return;

	idx = ir_local_slot_index(store->value);
	if (idx < 0)
		return;

	if (ir_prev_is_long_const(prev, &value)) {
		state->known[idx] = 1;
		state->value[idx] = value;
		return;
	}

	state->known[idx] = 0;
}


static void 
ir_make_const(IRInst *inst, long value)
{
	inst->kind = IR_CONST;
	inst->value = value;
	inst->aux = 0;
	/* op is embedded array: no free needed */
	inst->op[0] = '\0'; inst->subop = IR_OP_NONE;
	ir_inst_clear_simple_call_args(inst);
	xfree(inst->name);
	inst->name = xstrdup("");
}

static int 
ir_local_inst_is_volatile(IRInst *inst)
{
	Type *type;

	if (!inst || inst->subop != IR_OP_LOCAL || !inst->name || !inst->name[0])
		return 0;

	type = type_local_optional(inst->name);
	return type && type_has_qualifier(type, TYPE_QUAL_VOLATILE);
}

static int 
ir_is_local_scalar_store(IRInst *inst)
{
	return inst &&
	       inst->kind == IR_STORE &&
	       inst->subop == IR_OP_LOCAL &&
	       !ir_local_inst_is_volatile(inst) &&
	       ir_local_const_trackable_size(inst->aux);
}

static int 
ir_is_local_scalar_load(IRInst *inst)
{
	return inst &&
	       inst->kind == IR_LOAD &&
	       inst->subop == IR_OP_LOCAL &&
	       !ir_local_inst_is_volatile(inst) &&
	       ir_local_const_trackable_size(inst->aux);
}


static int
ir_is_local_forwardable_store(IRInst *inst)
{
	return inst &&
	       inst->kind == IR_STORE &&
	       inst->subop == IR_OP_LOCAL &&
	       !ir_local_inst_is_volatile(inst) &&
	       (inst->aux == 1 || inst->aux == 2 || inst->aux == 4 || inst->aux == 8);
}

static int
ir_is_local_forwardable_load(IRInst *inst)
{
	return inst &&
	       inst->kind == IR_LOAD &&
	       inst->subop == IR_OP_LOCAL &&
	       !ir_local_inst_is_volatile(inst) &&
	       (inst->aux == 1 || inst->aux == 2 || inst->aux == 4 || inst->aux == 8);
}

static int 
ir_next_uses_value(IRInst *inst)
{
	if (!inst)
		return 0;

	switch (inst->kind) {
	case IR_BINOP:
	case IR_UNOP:
	case IR_STORE:
	case IR_RETURN:
	case IR_BRANCH:
	case IR_POP:
	case IR_CALL:
	case IR_CALL_INDIRECT:
	case IR_CALL_ACC_ARG0:
	case IR_CALL_PACKED_GPR:
		return 1;
	default:
		return 0;
	}
}

static int 
ir_next_is_value_boundary(IRInst *inst)
{
	if (!inst)
		return 1;

	switch (inst->kind) {
	case IR_LABEL:
	case IR_ASM:
		return 1;
	default:
		return 0;
	}
}

static int
ir_branch_uses_two_values(IRInst *inst)
{
	return inst &&
	       inst->kind == IR_BRANCH &&
	       ir_branch_is_conditional_subop((IRSubOp)inst->subop) &&
	       inst->subop != IR_OP_JZ &&
	       inst->subop != IR_OP_JNZ;
}

static int 
ir_label_is_referenced(IRProgram *program, int label)
{
	for (IRInst *inst = program->head; inst; inst = inst->next) {
		if (inst->kind == IR_BRANCH && inst->value == label)
			return 1;
	}

	return 0;
}

static IRInst *
ir_find_label_inst(IRProgram *program, int label)
{
	for (IRInst *inst = program ? program->head : NULL; inst; inst = inst->next) {
		if (inst->kind == IR_LABEL && inst->subop == IR_OP_L &&
		    inst->value == label)
			return inst;
	}

	return NULL;
}

static const char *
ir_branch_subop_name(IRSubOp subop)
{
	switch (subop) {
	case IR_OP_JMP: return "jmp";
	case IR_OP_JZ: return "jz";
	case IR_OP_JNZ: return "jnz";
	case IR_OP_JE: return "je";
	case IR_OP_JNE: return "jne";
	case IR_OP_JLT: return "jlt";
	case IR_OP_JLE: return "jle";
	case IR_OP_JGT: return "jgt";
	case IR_OP_JGE: return "jge";
	case IR_OP_JULT: return "jult";
	case IR_OP_JULE: return "jule";
	case IR_OP_JUGT: return "jugt";
	case IR_OP_JUGE: return "juge";
	default: return NULL;
	}
}

static IRSubOp
ir_invert_branch_subop(IRSubOp subop)
{
	switch (subop) {
	case IR_OP_JZ: return IR_OP_JNZ;
	case IR_OP_JNZ: return IR_OP_JZ;
	case IR_OP_JE: return IR_OP_JNE;
	case IR_OP_JNE: return IR_OP_JE;
	case IR_OP_JLT: return IR_OP_JGE;
	case IR_OP_JLE: return IR_OP_JGT;
	case IR_OP_JGT: return IR_OP_JLE;
	case IR_OP_JGE: return IR_OP_JLT;
	case IR_OP_JULT: return IR_OP_JUGE;
	case IR_OP_JULE: return IR_OP_JUGT;
	case IR_OP_JUGT: return IR_OP_JULE;
	case IR_OP_JUGE: return IR_OP_JULT;
	default: return IR_OP_UNKNOWN;
	}
}

static void
ir_set_branch_subop(IRInst *inst, IRSubOp subop)
{
	const char *name = ir_branch_subop_name(subop);

	if (!inst || !name)
		return;

	inst->subop = (uint8_t)subop;
	inst->op[0] = '\0';
	STRNCPY(inst->op, name, sizeof(inst->op) - 1);
}

static int
ir_resolve_jump_target(IRProgram *program, int label)
{
	int current = label;

	for (int depth = 0; depth < 32; depth++) {
		IRInst *target = ir_find_label_inst(program, current);
		IRInst *next = target ? target->next : NULL;

		if (!next || next->kind != IR_BRANCH || next->subop != IR_OP_JMP ||
		    next->value == current)
			break;

		current = (int)next->value;
	}

	return current;
}

static int
ir_opt_pass_branch_target_cleanup(IRProgram *program)
{
	int changed = 0;

	for (IRInst *inst = program ? program->head : NULL; inst; inst = inst->next) {
		int target;

		if (inst->kind != IR_BRANCH || inst->subop == IR_OP_NONE ||
		    inst->name[0])
			continue;

		target = ir_resolve_jump_target(program, (int)inst->value);
		if (target != inst->value) {
			inst->value = target;
			changed = 1;
		}
	}

	return changed;
}

static int 
ir_try_remove_unreferenced_label(IRProgram *program, IRInst *prev, IRInst *inst)
{
	if (!inst || inst->kind != IR_LABEL)
		return 0;

	if (inst->subop == IR_OP_FUNC)
		return 0;

	if (ir_label_is_referenced(program, inst->value))
		return 0;

	ir_remove_range(program, prev, inst, inst);
	return 1;
}

static int 
ir_try_merge_adjacent_labels(IRProgram *program, IRInst *first, IRInst *second)
{
	if (!first || !second)
		return 0;

	if (first->kind != IR_LABEL || second->kind != IR_LABEL)
		return 0;

	if (first->subop == IR_OP_FUNC || second->subop == IR_OP_FUNC)
		return 0;

	int old_label = second->value;
	int new_label = first->value;

	for (IRInst *inst = program->head; inst; inst = inst->next) {
		if (inst->kind == IR_BRANCH && inst->value == old_label)
			inst->value = new_label;
	}

	first->next = second->next;
	if (program->tail == second)
		program->tail = first;
	xfree(second);
	return 1;
}

static int
ir_pure_value_stack_delta(IRInst *inst)
{
	if (!inst)
		return 0;

	switch (inst->kind) {
	case IR_CONST:
	case IR_LOAD:
		return 1;
	case IR_UNOP:
		return 0;
	case IR_BINOP:
		return -1;
	default:
		return 0;
	}
}

static int
ir_try_remove_dead_value_chain(IRProgram *program, IRInst *prev, IRInst *inst)
{
	IRInst *scan = inst;
	IRInst *last = NULL;
	int depth = 0;

	if (!inst ||
	    (inst->kind != IR_CONST &&
	     inst->kind != IR_LOAD &&
	     inst->kind != IR_BINOP &&
	     inst->kind != IR_UNOP))
		return 0;

	for (; scan &&
	       (scan->kind == IR_CONST ||
	        scan->kind == IR_LOAD ||
	        scan->kind == IR_BINOP ||
	        scan->kind == IR_UNOP);
	     scan = scan->next) {
		int delta = ir_pure_value_stack_delta(scan);

		if (scan->kind == IR_UNOP) {
			if (depth < 1)
				return 0;
		} else if (scan->kind == IR_BINOP) {
			if (depth < 2)
				return 0;
		}

		depth += delta;
		last = scan;
	}

	if (!last || !scan || scan->kind != IR_POP)
		return 0;
	if (depth != 1)
		return 0;
	if (scan->next &&
	    !(scan->next->kind == IR_BRANCH && scan->next->subop == IR_OP_JMP) &&
	    ir_next_uses_value(scan->next))
		return 0;

	ir_remove_range(program, prev, inst, scan);
	return 1;
}

static int 
ir_try_remove_dead_value(IRProgram *program, IRInst *prev, IRInst *inst)
{
	if (!inst ||
	    (inst->kind != IR_CONST &&
	     inst->kind != IR_LOAD &&
	     inst->kind != IR_BINOP &&
	     inst->kind != IR_UNOP))
		return 0;

	IRInst *next = inst->next;

	/*
	 * Stack-machine IR values are consumed by nearby stack-consuming
	 * instructions.  A binary operation consumes two operands, so the first
	 * operand in a sequence such as:
	 *
	 *   load x
	 *   const 4
	 *   mul
	 *
	 * is live even though the immediately following instruction is another
	 * value producer.
	 */
	if (next &&
	        (next->kind == IR_CONST ||
	         next->kind == IR_LOAD ||
	         next->kind == IR_BINOP ||
	         next->kind == IR_UNOP) &&
	        next->next &&
	        (next->next->kind == IR_BINOP ||
	         ir_branch_uses_two_values(next->next)))
		return 0;

	/*
	 * Stack-machine IR values are consumed by the immediately following
	 * stack-consuming instruction.  If the next instruction is not a consumer,
	 * this value is dead and can be removed.  This deliberately avoids looking
	 * across labels/asm or trying to remove values before calls/stores.
	 */
	if (ir_next_uses_value(next) || ir_next_is_value_boundary(next))
		return 0;

	ir_remove_range(program, prev, inst, inst);
	return 1;
}

static int
ir_opt_pass_dead_value_chain(IRProgram *program)
{
	IRInst *prev = NULL;
	IRInst *a = program ? program->head : NULL;

	while (a) {
		if (ir_try_remove_dead_value_chain(program, prev, a))
			return 1;
		prev = a;
		a = a->next;
	}

	return 0;
}

static int 
ir_is_dse_barrier(IRInst *inst)
{
	if (!inst)
		return 0;

	if (inst->kind == IR_LABEL ||
	        inst->kind == IR_BRANCH ||
	        inst->kind == IR_RETURN ||
	        inst->kind == IR_CALL ||
	        inst->kind == IR_CALL_INDIRECT ||
	        inst->kind == IR_CALL_ACC_ARG0 ||
	        inst->kind == IR_CALL_PACKED_GPR ||
	        inst->kind == IR_ASM)
		return 1;

	if (inst->kind == IR_STORE && inst->subop != IR_OP_LOCAL)
		return 1;

	return 0;
}

static int
ir_function_has_call(IRInst *func_inst)
{
	IRInst *scan;

	if (!func_inst)
		return 0;

	for (scan = func_inst->next; scan; scan = scan->next) {
		if (scan->kind == IR_LABEL && scan->subop == IR_OP_FUNC)
			break;
		if (scan->kind == IR_CALL ||
		    scan->kind == IR_CALL_INDIRECT ||
		    scan->kind == IR_CALL_ACC_ARG0 ||
		    scan->kind == IR_CALL_PACKED_GPR)
			return 1;
	}

	return 0;
}

static int
ir_function_has_branch(IRInst *func_inst)
{
	IRInst *scan;

	if (!func_inst)
		return 0;

	for (scan = func_inst->next; scan; scan = scan->next) {
		if (scan->kind == IR_LABEL && scan->subop == IR_OP_FUNC)
			break;
		if (scan->kind == IR_BRANCH)
			return 1;
	}

	return 0;
}

static void 
ir_remove_range(IRProgram *program, IRInst *prev, IRInst *first, IRInst *last)
{
	IRInst *after = last->next;

	if (prev)
		prev->next = after;
	else
		program->head = after;

	if (program->tail == last)
		program->tail = prev;

	for (IRInst *p = first; p != after;) {
		IRInst *next = p->next;
		xfree(p->name);
		xfree(p);
		p = next;
	}
}

static int 
ir_try_remove_redundant_store(IRProgram *program, IRInst *prev, IRInst *inst)
{
	if (!ir_is_local_forwardable_store(inst))
		return 0;

	int slot = inst->value;
	IRInst *value = prev; /* caller already threads prev through its loop */
	IRInst *next = inst->next;

	/*
	 * v108 load forwarding:
	 *
	 * const C ; store x ; load x -> const C ; store x ; const C
	 *
	 * This preserves the stack value expected by following IR, unlike deleting
	 * the load outright.
	 */
	if (next && ir_is_local_forwardable_load(next) && next->value == slot && next->aux == inst->aux) {
		if (value && value->kind == IR_CONST && inst->aux <= 4) {
			ir_make_const(next, value->value);
			return 1;
		}

		if (value && ir_is_local_forwardable_load(value) && value->aux == inst->aux) {
			/* Only report a change when the forwarded source actually differs.
			 * Otherwise the outer fixed-point optimiser keeps revisiting the
			 * same store/load pair forever at -O1.
			 */
			if (next->value == value->value)
				return 0;
			next->value = value->value;
			return 1;
		}

		return 0;
	}

	if (next && ir_is_local_forwardable_store(next) && next->value == slot && next->aux == inst->aux) {
		ir_remove_range(program, prev, inst, inst);
		return 1;
	}

	return 0;
}

static int 
ir_try_remove_dead_local_store(IRProgram *program, IRInst *prev, IRInst *value, IRInst *store)
{
	if (!value || !store || !ir_is_local_scalar_store(store))
		return 0;

	int slot = store->value;

	for (IRInst *scan = store->next; scan; scan = scan->next) {
		if (ir_is_dse_barrier(scan))
			return 0;

		if (ir_is_local_scalar_load(scan) && scan->value == slot)
			return 0;

		if (ir_is_local_scalar_store(scan) && scan->value == slot) {
			/*
			 * The first store is overwritten before any read/barrier.  The IR
			 * value instruction immediately before it exists only to feed that
			 * store in normal assignment lowering, so remove both.
			 */
			ir_remove_range(program, prev, value, store);
			return 1;
		}
	}

	return 0;
}

static void 
ir_remove_one(IRProgram *program, IRInst *prev, IRInst *inst)
{
	IRInst *next = inst->next;

	if (prev)
		prev->next = next;
	else
		program->head = next;

	if (program->tail == inst)
		program->tail = prev;

	xfree(inst->name);
	xfree(inst);
}

static int
ir_opt_pass_dead_local_store(IRProgram *program)
{
	IRInst *prev = NULL;
	IRInst *a = program->head;
	int changed = 0;

	while (a && a->next) {
		IRInst *b = a->next;

		if (ir_try_remove_dead_local_store(program, prev, a, b)) {
			changed = 1;
			a = prev ? prev->next : program->head;
			continue;
		}

		prev = a;
		a = a->next;
	}

	return changed;
}

static int
ir_opt_pass_dead_value(IRProgram *program)
{
	IRInst *prev = NULL;
	IRInst *a = program->head;
	int changed = 0;

	while (a) {
		if (ir_try_remove_dead_value(program, prev, a)) {
			changed = 1;
			a = prev ? prev->next : program->head;
			continue;
		}

		prev = a;
		a = a->next;
	}

	return changed;
}

static int
ir_opt_pass_label_cleanup(IRProgram *program)
{
	IRInst *prev = NULL;
	IRInst *a = program->head;
	int changed = 0;

	while (a) {
		IRInst *b = a->next;

		if (b && ir_try_merge_adjacent_labels(program, a, b)) {
			changed = 1;
			continue;
		}

		if (ir_try_remove_unreferenced_label(program, prev, a)) {
			changed = 1;
			a = prev ? prev->next : program->head;
			continue;
		}

		prev = a;
		a = a->next;
	}

	return changed;
}

static int
ir_opt_pass_redundant_store(IRProgram *program)
{
	IRInst *prev = NULL;
	IRInst *a = program->head;
	int changed = 0;

	while (a) {
		if (ir_try_remove_redundant_store(program, prev, a)) {
			changed = 1;
			a = prev ? prev->next : program->head;
			continue;
		}

		prev = a;
		a = a->next;
	}

	return changed;
}

static int
ir_opt_pass_copy_propagation(IRProgram *program)
{
	IRLocalCopyState copy_state;
	IRInst *prev_p = NULL;
	IRInst *p = program->head;
	int changed = 0;

	ir_local_copy_state_clear(&copy_state);

	while (p) {
		IRInst *next_p = p->next;

		if (p->kind == IR_LABEL || p->kind == IR_BRANCH ||
		        p->kind == IR_RETURN || p->kind == IR_CALL || p->kind == IR_CALL_ACC_ARG0 ||
		        p->kind == IR_CALL_PACKED_GPR ||
		        p->kind == IR_ASM) {
			ir_local_copy_state_clear(&copy_state);
			prev_p = p;
			p = next_p;
			continue;
		}

		if (ir_is_local_scalar_load(p)) {
			if (ir_local_copy_state_try_rewrite_load(&copy_state, p))
				changed = 1;

			prev_p = p;
			p = next_p;
			continue;
		}

		if (ir_is_local_scalar_store(p)) {
			ir_local_copy_state_record_store(&copy_state, p, prev_p);

			prev_p = p;
			p = next_p;
			continue;
		}

		if (p->kind == IR_STORE) {
			ir_local_copy_state_clear(&copy_state);
			prev_p = p;
			p = next_p;
			continue;
		}

		prev_p = p;
		p = next_p;
	}

	return changed;
}

static int
ir_opt_pass_propagation_lite(IRProgram *program)
{
	IRLocalConstState const_state;
	IRInst *prev_p = NULL;
	IRInst *p = program->head;
	int changed = 0;

	ir_local_const_state_clear(&const_state);

	while (p) {
		IRInst *next_p = p->next;

		if (p->kind == IR_LABEL || p->kind == IR_BRANCH ||
		        p->kind == IR_CALL || p->kind == IR_CALL_ACC_ARG0 ||
		        p->kind == IR_CALL_PACKED_GPR || p->kind == IR_ASM) {
			ir_local_const_state_clear(&const_state);
			prev_p = p;
			p = next_p;
			continue;
		}

		if (p->kind == IR_STORE && p->subop == IR_OP_LOCAL) {
			ir_local_const_state_record_prev_const(&const_state, p, prev_p);

			prev_p = p;
			p = next_p;
			continue;
		}

		if (p->kind == IR_STORE) {
			ir_local_const_state_clear(&const_state);
			prev_p = p;
			p = next_p;
			continue;
		}

		if (p->kind == IR_LOAD && p->subop == IR_OP_LOCAL) {
			if (ir_local_const_state_try_rewrite_load(&const_state, p))
				changed = 1;
		}

		prev_p = p;
		p = next_p;
	}

	return changed;
}

static int
ir_opt_pass_block_local_const_prop(IRProgram *program)
{
	IRLocalConstState const_state;
	IRInst *prev_p = NULL;
	IRInst *p = program->head;
	int changed = 0;

	ir_local_const_state_clear(&const_state);

	while (p) {
		IRInst *next_p = p->next;

		if (ir_is_side_effect_or_barrier(p)) {
			if (!(p->kind == IR_STORE && p->subop == IR_OP_LOCAL))
				ir_local_const_state_clear(&const_state);
		}

		if (p->kind == IR_LOAD && p->subop == IR_OP_LOCAL &&
		    ir_local_const_trackable_size(p->aux)) {
			if (ir_local_const_state_try_rewrite_load(&const_state, p))
				changed = 1;

			prev_p = p;
			p = next_p;
			continue;
		}

		if (p->kind == IR_STORE && p->subop == IR_OP_LOCAL &&
		    ir_local_const_trackable_size(p->aux)) {
			ir_local_const_state_record_prev_const(&const_state, p, prev_p);

			prev_p = p;
			p = next_p;
			continue;
		}

		if (p->kind == IR_STORE) {
			ir_local_const_state_clear(&const_state);
			prev_p = p;
			p = next_p;
			continue;
		}

		prev_p = p;
		p = next_p;
	}

	return changed;
}

static int
ir_opt_pass_materialized_local_reuse(IRProgram *program)
{
	IRMaterializedLocalState materialized_state;
	IRInst *prev_prev_p = NULL;
	IRInst *prev_p = NULL;
	IRInst *p = program->head;
	int changed = 0;

	ir_materialized_local_state_clear(&materialized_state);

	while (p) {
		IRInst *next_p = p->next;

		if (ir_is_side_effect_or_barrier(p)) {
			if (!(p->kind == IR_STORE && p->subop == IR_OP_LOCAL))
				ir_materialized_local_state_clear(&materialized_state);
		}

		if (ir_is_reusable_materialized_load(p)) {
			if (ir_materialized_local_state_try_rewrite_load(&materialized_state, p))
				changed = 1;

			prev_prev_p = prev_p;
			prev_p = p;
			p = next_p;
			continue;
		}

		if (ir_is_local_forwardable_store(p)) {
			ir_materialized_local_state_record_store(&materialized_state, p, prev_p, prev_prev_p);

			prev_prev_p = prev_p;
			prev_p = p;
			p = next_p;
			continue;
		}

		if (p->kind == IR_STORE) {
			ir_materialized_local_state_clear(&materialized_state);
			prev_prev_p = prev_p;
			prev_p = p;
			p = next_p;
			continue;
		}

		prev_prev_p = prev_p;
		prev_p = p;
		p = next_p;
	}

	return changed;
}

void 
ir_optimize(IRProgram *program, int level)
{
	if (!program)
		return;
	if (level <= 0)
		return;

	int changed = 1;
	int opt_iter = 0;
	const char *opt_pass = "init";

#define OPT_CHANGED(pass_name) \
	do { \
		Debug(1, "[OPT] iter %d changed in %s\n", opt_iter, (pass_name)); \
		changed = 1; \
	} while (0)

	while (changed) {
		opt_iter++;
		Debug(1, "[OPT] iter %d begin\n", opt_iter);
		if (opt_iter > 100) {
			Debug(1, "[OPT] exceeded 100 iterations; dumping IR and stopping optimiser\n");
			ir_dump(program);
			break;
		}

		changed = 0;

		opt_pass = "v102 dead-store elimination";
		/*
		 * v102 dead-store elimination:
		 *
		 * Remove a local scalar store when the same local slot is overwritten
		 * before any load or side-effect/control-flow barrier.  This is
		 * deliberately block-local and conservative.
		 */
		if (ir_opt_pass_dead_local_store(program))
			OPT_CHANGED(opt_pass);

		opt_pass = "v104 pure dead-code elimination";
		/*
		 * v104 pure dead-code elimination:
		 *
		 * Remove side-effect-free expression chains that feed only a trailing
		 * pop, for example:
		 *
		 *   load local x ; cast ; pop
		 *   const 1 ; const 2 ; add ; pop
		 *
		 * This catches explicit `(void)x;`-style statements before the more
		 * local single-instruction dead-value cleanup below.
		 */
		if (ir_opt_pass_dead_value_chain(program))
			OPT_CHANGED(opt_pass);

		/*
		 * v104.1 pure dead-code elimination:
		 *
		 * Remove pure value-producing instructions whose result is not consumed
		 * by the immediately following stack instruction.  This handles dead
		 * expression statements such as:
		 *
		 *   1;
		 *   x + 2;
		 *
		 * while preserving stores, calls, returns, branches, pop, and asm.
		 */
		if (ir_opt_pass_dead_value(program))
			OPT_CHANGED(opt_pass);

		opt_pass = "v105 label cleanup";
		/*
		 * v105 label cleanup:
		 *
		 * Collapse adjacent non-function labels and remove unreferenced normal
		 * labels.  Earlier branch simplification and CFG-DCE can leave empty
		 * label islands behind; cleaning them up reduces CFG noise and emitted
		 * assembly labels.
		 */
		if (ir_opt_pass_label_cleanup(program))
			OPT_CHANGED(opt_pass);

		opt_pass = "v110 branch target cleanup";
		/*
		 * v110 branch target cleanup:
		 *
		 * Thread branches through local-label trampolines:
		 *
		 *   jcc L1      L1: jmp L2
		 *
		 * becomes:
		 *
		 *   jcc L2
		 *
		 * This is target-independent CFG simplification and exposes more
		 * jump-to-next-label and unreferenced-label cleanup opportunities.
		 */
		if (ir_opt_pass_branch_target_cleanup(program))
			OPT_CHANGED(opt_pass);

		opt_pass = "v108 redundant store/load forwarding";
		/*
		 * v108 redundant store/load forwarding:
		 *
		 * Remove adjacent redundant local scalar patterns:
		 *
		 *   store x ; load x  -> store x
		 *   store x ; store x -> store x
		 */
		if (ir_opt_pass_redundant_store(program))
			OPT_CHANGED(opt_pass);

		opt_pass = "v109 materialized-local reuse";
		/*
		 * v109 materialized-local reuse:
		 *
		 * Track globals, global members, function/global addresses, and string
		 * literals that are already materialised into local slots within the
		 * current straight-line block.  Rewrite later identical loads to reuse
		 * that local instead of rematerialising the symbol or literal.
		 *
		 * This is intentionally narrow: it never invents new temporaries and
		 * it clears state at labels, calls, branches, asm, returns, and
		 * unknown stores.
		 */
		if (ir_opt_pass_materialized_local_reuse(program))
			OPT_CHANGED(opt_pass);

		opt_pass = "v106 copy propagation";
		/*
		 * v106 copy propagation:
		 *
		 * Track simple local-to-local copies within a basic block:
		 *
		 *   load local x
		 *   store local y
		 *   load local y
		 *
		 * becomes:
		 *
		 *   load local x
		 *
		 * when no barrier or overwrite intervenes.  This is intentionally
		 * conservative and block-local.
		 */
		if (ir_opt_pass_copy_propagation(program))
			OPT_CHANGED(opt_pass);

		opt_pass = "v94.1 propagation-lite";
		/*
		 * v94.1 propagation-lite:
		 *
		 * Track constant stores to local stack slots until a label/control-flow
		 * boundary or unknown store/call.  Replace subsequent local loads with
		 * constants when safe.  This deliberately avoids global dataflow.
		 */
		if (ir_opt_pass_propagation_lite(program))
			OPT_CHANGED(opt_pass);

		opt_pass = "v101 block-local const propagation";
		/*
		 * v101 block-local constant folding / propagation:
		 *
		 * This pass tracks simple scalar local constants within a basic block.
		 * Labels, branches, calls, asm, returns, and non-local stores are
		 * barriers.  It improves on v94.1 by using the previous IR instruction
		 * as the value source for each local store, then allowing normal
		 * const/const/binop folding to collapse the resulting expressions.
		 */
		if (ir_opt_pass_block_local_const_prop(program))
			OPT_CHANGED(opt_pass);

		opt_pass = "peepholes/branch folding";

		IRInst *prev = NULL;
		IRInst *a = program->head;

		while (a) {
			IRInst *b = a->next;
			IRInst *c = b ? b->next : NULL;

			/*
			 * Constant fold stack-machine triples:
			 *
			 *   const A
			 *   const B
			 *   add/mul/...
			 *
			 * into:
			 *
			 *   const RESULT
			 */
			if (a->kind == IR_CONST && b && b->kind == IR_CONST && c && c->kind == IR_BINOP) {
				long result = 0;
				if (ir_eval_binop(c->op, a->value, b->value, &result)) {
					IRInst *replacement = xcalloc(1, sizeof(IRInst));

					replacement->kind = IR_CONST;
					replacement->id = program->next_id++;
					replacement->value = result;
					replacement->next = c->next;

					if (prev)
						prev->next = replacement;
					else
						program->head = replacement;

					if (program->tail == c)
						program->tail = replacement;

					xfree(a);
					xfree(b);
					xfree(c);

					OPT_CHANGED(opt_pass);
					a = replacement;
					continue;
				}
			}

			/*
			 * Constant fold unary pairs:
			 *
			 *   const A
			 *   neg/not/cast
			 */
			if (a->kind == IR_CONST && b && b->kind == IR_UNOP) {
				long result = 0;
				if (ir_eval_unop(b->op, a->value, b->value, &result)) {
					a->value = result;
					a->next = b->next;
					if (program->tail == b)
						program->tail = a;
					xfree(b);
					OPT_CHANGED(opt_pass);
					continue;
				}
			}

			/*
			 * v94 stack-machine peepholes for identity operations where one
			 * side is a literal and the other side may be an arbitrary
			 * expression result immediately before the literal.
			 *
			 * Examples:
			 *
			 *   expr
			 *   const 0
			 *   add        -> expr
			 *
			 *   expr
			 *   const 1
			 *   mul        -> expr
			 *
			 * These reduce instruction count before backend codegen, which in
			 * turn eliminates push/pop traffic in generated assembly.
			 */
			if (b && c && b->kind == IR_CONST && c->kind == IR_BINOP) {
				if ((c->subop == IR_OP_ADD || c->subop == IR_OP_SUB ||
				        c->subop == IR_OP_OR || c->subop == IR_OP_XOR ||
				        c->subop == IR_OP_SHL || c->subop == IR_OP_SHR) &&
				        b->value == 0) {
					a->next = c->next;
					if (program->tail == c)
						program->tail = a;
					xfree(b);
					xfree(c);
					OPT_CHANGED(opt_pass);
					continue;
				}

				if (c->subop == IR_OP_MUL && b->value == 1) {
					a->next = c->next;
					if (program->tail == c)
						program->tail = a;
					xfree(b);
					xfree(c);
					OPT_CHANGED(opt_pass);
					continue;
				}

				if (c->subop == IR_OP_MUL && b->value > 0 &&
				        (b->value & (b->value - 1)) == 0) {
					int shift = 0;
					long value = b->value;

					while (value > 1) {
						value >>= 1;
						shift++;
					}

					if (shift > 0) {
						b->value = shift;
						ir_binop_to_shift_left(c);
						OPT_CHANGED(opt_pass);
						continue;
					}
				}

				if ((c->subop == IR_OP_MUL || c->subop == IR_OP_AND) &&
				        b->value == 0) {
					/*
					 * expr, const 0, mul/and -> const 0
					 *
					 * This is safe only for our side-effect-free expression IR
					 * prefix at this stage.  Avoid applying it after calls or
					 * stores by requiring the left instruction itself to be a
					 * pure value producer.
					 */
					if (a->kind == IR_CONST || a->kind == IR_LOAD || a->kind == IR_UNOP || a->kind == IR_BINOP) {
						a->kind = IR_CONST;
						a->value = 0;
						a->aux = 0;
						a->op[0] = '\0';
						a->name[0] = '\0';
						a->next = c->next;
						if (program->tail == c)
							program->tail = a;
						xfree(b);
						xfree(c);
						OPT_CHANGED(opt_pass);
						continue;
					}
				}
			}

			/*
			 * Literal-left commutative identities:
			 *
			 *   const 0
			 *   expr
			 *   add/or/xor -> expr
			 *
			 * We can remove the leading literal and binop, leaving expr.
			 */
			if (a->kind == IR_CONST && c && c->kind == IR_BINOP &&
			        (c->subop == IR_OP_ADD ||
			         c->subop == IR_OP_OR ||
			         c->subop == IR_OP_XOR ||
			         c->subop == IR_OP_MUL ||
			         c->subop == IR_OP_AND)) {
				if (((c->subop == IR_OP_ADD || c->subop == IR_OP_OR || c->subop == IR_OP_XOR) && a->value == 0) ||
				        (c->subop == IR_OP_MUL && a->value == 1)) {
					/*
					 * Drop a and c.  b becomes the first instruction in the
					 * replacement window.
					 */
					if (prev)
						prev->next = b;
					else
						program->head = b;
					b->next = c->next;
					if (program->tail == c)
						program->tail = b;
					xfree(a);
					xfree(c);
					OPT_CHANGED(opt_pass);
					a = b;
					continue;
				}

				if ((c->subop == IR_OP_MUL || c->subop == IR_OP_AND) && a->value == 0 &&
				        (b->kind == IR_CONST || b->kind == IR_LOAD || b->kind == IR_UNOP || b->kind == IR_BINOP)) {
					a->next = c->next;
					if (program->tail == c)
						program->tail = a;
					xfree(b);
					xfree(c);
					OPT_CHANGED(opt_pass);
					continue;
				}
			}

			/*
			 * v96 dead-store-lite:
			 *
			 *   const A
			 *   store local X
			 *   const B
			 *   store local X
			 *
			 * -> const B ; store local X
			 */
			if (a->kind == IR_CONST && b && b->kind == IR_STORE &&
			        b->subop == IR_OP_LOCAL && c && c->kind == IR_CONST &&
			        c->next && c->next->kind == IR_STORE &&
			        c->next->subop == IR_OP_LOCAL &&
			        b->value == c->next->value) {
				IRInst *d = c->next;

				if (prev)
					prev->next = c;
				else
					program->head = c;

				xfree(a);
				xfree(b);
				OPT_CHANGED(opt_pass);
				a = c;
				(void)d;
				continue;
			}

			/*
			 * Branch peepholes:
			 *
			 *   const 0 ; jz  L  -> jmp L
			 *   const 1 ; jz  L  -> delete both
			 *   const 0 ; jnz L  -> delete both
			 *   const 1 ; jnz L  -> jmp L
			 */
			if (a->kind == IR_CONST && b && b->kind == IR_BRANCH &&
			        (b->subop == IR_OP_JZ || b->subop == IR_OP_JNZ)) {
				int take_branch = (b->subop == IR_OP_JZ) ? (a->value == 0) : (a->value != 0);

				if (take_branch) {
					a->kind = IR_BRANCH;
					STRNCPY(a->op, "jmp", sizeof(a->op) - 1); a->subop = IR_OP_JMP;
					a->value = b->value;
					a->aux = 0;
					a->name[0] = '\0';
					a->next = b->next;
					if (program->tail == b)
						program->tail = a;
					xfree(b);
				} else {
					IRInst *after = b->next;
					if (prev)
						prev->next = after;
					else
						program->head = after;
					if (program->tail == b)
						program->tail = prev;
					xfree(a);
					xfree(b);
					a = after;
				}

				OPT_CHANGED(opt_pass);
				continue;
			}

			/*
			 * Branch-over-jump:
			 *
			 *   jcc L1
			 *   jmp L2
			 * L1:
			 *
			 * -> inverted-jcc L2
			 * L1:
			 */
			if (a->kind == IR_BRANCH &&
			    ir_branch_is_conditional_subop((IRSubOp)a->subop) &&
			    b && b->kind == IR_BRANCH && b->subop == IR_OP_JMP &&
			    c && c->kind == IR_LABEL && c->subop == IR_OP_L &&
			    a->value == c->value && !a->name[0] && !b->name[0]) {
				IRSubOp inverted = ir_invert_branch_subop((IRSubOp)a->subop);

				if (inverted != IR_OP_UNKNOWN) {
					ir_set_branch_subop(a, inverted);
					a->value = b->value;
					a->next = c;
					if (program->tail == b)
						program->tail = a;
					xfree(b->name);
					xfree(b);
					OPT_CHANGED(opt_pass);
					continue;
				}
			}

			/*
			 * Consecutive identical casts are redundant.
			 *
			 *   cast size=S unsigned=U
			 *   cast size=S unsigned=U
			 *
			 * -> keep the first cast only
			 */
			if (a->kind == IR_UNOP && a->subop == IR_OP_CAST &&
			    b && b->kind == IR_UNOP && b->subop == IR_OP_CAST &&
			    a->value == b->value && a->aux == b->aux) {
				a->next = b->next;
				if (program->tail == b)
					program->tail = a;
				xfree(b);
				OPT_CHANGED(opt_pass);
				continue;
			}

			/*
			 * Remove jumps to immediately following labels.
			 */
			if (a->kind == IR_BRANCH && a->subop == IR_OP_JMP &&
			        b && b->kind == IR_LABEL && b->subop == IR_OP_L &&
			        a->value == b->value) {
				ir_remove_one(program, prev, a);
				OPT_CHANGED(opt_pass);
				a = b;
				continue;
			}

			/*
			 * Remove unreachable linear instructions between an unconditional
			 * jump/return and the next label.
			 */
			if ((a->kind == IR_BRANCH && a->subop == IR_OP_JMP) ||
			        a->kind == IR_RETURN) {
				IRInst *first_dead = a->next;
				IRInst *last_dead = NULL;
				IRInst *scan = first_dead;

				while (scan && scan->kind != IR_LABEL) {
					last_dead = scan;
					scan = scan->next;
				}

				if (first_dead && last_dead) {
					IRInst *after = last_dead->next;
					a->next = after;
					if (program->tail == last_dead)
						program->tail = a;

					for (IRInst *p = first_dead; p != after;) {
						IRInst *next = p->next;
						xfree(p);
						p = next;
					}

					OPT_CHANGED(opt_pass);
					continue;
				}
			}

			prev = a;
			a = a->next;
		}
	}

	/*
	 * Run CFG unreachable-block elimination at -O1 after the fixed-point
	 * peephole/branch simplification loop.  Keep it outside the loop so CFG
	 * removal cannot interact with the optimiser fixed point.
	 */
	if (level >= 1)
		ir_cfg_eliminate_unreachable(program);

}

static int
ir_is_block_terminator(IRInst *inst)
{
	if (!inst)
		return 0;

	if (inst->kind == IR_RETURN)
		return 1;

	if (inst->kind == IR_BRANCH)
		return 1;

	return 0;
}

static int
ir_call_name_is_noreturn(const char *name)
{
	if (!name || !name[0])
		return 0;

	return STRCMP(name, "exit") == 0 ||
	       STRCMP(name, "abort") == 0 ||
	       STRCMP(name, "tcc_error") == 0 ||
	       STRCMP(name, "fatal_ice") == 0 ||
	       STRCMP(name, "fatal_lex") == 0 ||
	       STRCMP(name, "fatal_pp") == 0 ||
	       STRCMP(name, "fatal_cur") == 0 ||
	       STRCMP(name, "fatal_token") == 0 ||
	       STRCMP(name, "node_error_at") == 0;
}

static int
ir_try_emit_arm64_tcc_va_base_call(Codegen *cg, IRInst *inst)
{
	if (!cg || cg != &arm64_codegen || !inst || inst->kind != IR_CALL ||
	    inst->value != 0 || inst->fp_arg_mask != 0 ||
	    !cg->emit_addr_local || !inst->name ||
	    STRCMP(inst->name, "__tcc_va_base") != 0)
		return 0;

	cg->emit_addr_local(16);
	return 1;
}

static int 
ir_starts_block(IRInst *inst, int need_new_block)
{
	if (!inst)
		return 0;

	if (inst->kind == IR_LABEL)
		return 1;

	return need_new_block;
}

static void 
ir_free_cfg(IRProgram *program)
{
	IRBlock *block = program->blocks;
	while (block) {
		IRBlock *next = block->next;
		xfree(block);
		block = next;
	}

	program->blocks = NULL;
	program->block_count = 0;
}

static IRBlock *
ir_new_block(IRProgram *program, IRInst *first)
{
	IRBlock *block = xcalloc(1, sizeof(IRBlock));
	block->id = program->block_count++;
	block->label = -1;
	block->first = first;

	if (first && first->kind == IR_LABEL && first->subop == IR_OP_L)
		block->label = first->value;
	else if (first && first->kind == IR_LABEL && first->subop == IR_OP_FUNC)
		block->label = -1000 - block->id;

	if (!program->blocks)
		program->blocks = block;
	else {
		IRBlock *tail = program->blocks;
		while (tail->next)
			tail = tail->next;
		tail->next = block;
	}

	return block;
}

static IRBlock *
ir_find_block_by_label(IRProgram *program, int label)
{
	for (IRBlock *block = program->blocks; block; block = block->next) {
		if (block->label == label)
			return block;
	}

	return NULL;
}

static IRBlock *
ir_next_block(IRBlock *block)
{
	return block ? block->next : NULL;
}

void 
ir_build_cfg(IRProgram *program)
{
	if (!program)
		return;

	ir_free_cfg(program);

	IRBlock *current = NULL;
	int need_new_block = 1;

	for (IRInst *inst = program->head; inst; inst = inst->next) {
		if (!current || ir_starts_block(inst, need_new_block)) {
			current = ir_new_block(program, inst);
			need_new_block = 0;
		}

		current->last = inst;

		if (ir_is_block_terminator(inst))
			need_new_block = 1;
	}

	for (IRBlock *block = program->blocks; block; block = block->next) {
		IRInst *last = block->last;

		if (!last)
			continue;

		if (last->kind == IR_BRANCH) {
			if (last->subop == IR_OP_JMP) {
				block->branch = ir_find_block_by_label(program, last->value);
			} else if (ir_branch_is_conditional_subop((IRSubOp)last->subop)) {
				block->branch = ir_find_block_by_label(program, last->value);
				block->fallthrough = ir_next_block(block);
			}
		} else if (last->kind != IR_RETURN) {
			block->fallthrough = ir_next_block(block);
		}
	}
}

static void 
ir_dump_block_name(IRBlock *block)
{
	if (!block) {
		printf("none");
		return;
	}

	printf("B%d", block->id);
	if (block->label >= 0)
		printf("(L%d)", block->label);
}

static void 
ir_mark_reachable_blocks(IRBlock *block, int *reachable, int count)
{
	if (!block || block->id < 0 || block->id >= count)
		return;

	if (reachable[block->id])
		return;

	reachable[block->id] = 1;

	ir_mark_reachable_blocks(block->fallthrough, reachable, count);
	ir_mark_reachable_blocks(block->branch, reachable, count);
}

static int 
ir_block_is_function_entry(IRBlock *block)
{
	return block &&
	       block->first &&
	       block->first->kind == IR_LABEL &&
	       block->first->subop == IR_OP_FUNC;
}


void 
ir_cfg_eliminate_unreachable(IRProgram *program)
{
	if (!program)
		return;

	ir_build_cfg(program);

	if (program->block_count <= 0)
		return;

	int *reachable = xcalloc((size_t)program->block_count, sizeof(int));
	/*
	 * Treat the first block and every function-entry block as roots.  The IR
	 * is a whole-program function list, not a single function body, so a return
	 * from one function should not make the next function unreachable.
	 */
	if (program->blocks)
		ir_mark_reachable_blocks(program->blocks, reachable, program->block_count);

	for (IRBlock *block = program->blocks; block; block = block->next) {
		if (ir_block_is_function_entry(block))
			ir_mark_reachable_blocks(block, reachable, program->block_count);
	}

	for (IRBlock *block = program->blocks; block; block = block->next) {
		if (block->id < 0 || block->id >= program->block_count || reachable[block->id])
			continue;

		IRInst *first = block->first;
		IRInst *last = block->last;
		IRInst *after = last ? last->next : NULL;
		IRInst *prev = ir_prev_inst(program, first); /* same as ir_find_prev_inst (merged) */

		if (prev)
			prev->next = after;
		else
			program->head = after;

		if (program->tail == last)
			program->tail = prev;

		for (IRInst *inst = first; inst != after;) {
			IRInst *next = inst->next;
			ir_inst_clear_simple_call_args(inst);
			xfree(inst->name);
			xfree(inst);
			inst = next;
		}
	}

	xfree(reachable);
	ir_build_cfg(program);

}

#undef OPT_CHANGED

void 
ir_dump_cfg(IRProgram *program)
{
	if (!program)
		return;

	ir_build_cfg(program);

	printf("; cfg blocks=%d\n", program->block_count);

	for (IRBlock *block = program->blocks; block; block = block->next) {
		printf("B%d", block->id);

		if (block->first && block->first->kind == IR_LABEL && block->first->subop == IR_OP_FUNC)
			printf(" func=%s", block->first->name);
		else if (block->label >= 0)
			printf(" label=L%d", block->label);

		printf(" first=%%%d last=%%%d", block->first ? block->first->id : -1,
		       block->last ? block->last->id : -1);

		printf(" fallthrough=");
		ir_dump_block_name(block->fallthrough);

		printf(" branch=");
		ir_dump_block_name(block->branch);

		printf("\n");
	}
}

void 
ir_dump(IRProgram *program)
{
	if (program->unsupported_count)
		printf("; unsupported=%d reason=\"%s\"\n", program->unsupported_count, program->unsupported_reason);

	for (IRInst *inst = program->head; inst; inst = inst->next) {
		printf("%%%d = ", inst->id);

		switch (inst->kind) {
		case IR_CONST:
			printf("const %ld", inst->value);
			break;
		case IR_LOAD:
			printf("load %s %s value=%ld", inst->op, inst->name, inst->value);
			if (inst->aux)
				printf(" size=%d", inst->aux);
			break;
		case IR_STORE:
			printf("store %s %s value=%ld", inst->op, inst->name, inst->value);
			if (inst->aux)
				printf(" size=%d", inst->aux);
			break;
		case IR_BINOP:
			printf("%s", inst->op);
			if (inst->aux)
				printf(" scale=%d", inst->aux);
			if (inst->fp_size)
				printf(" fp=%d", inst->fp_size);
			break;
		case IR_UNOP:
			printf("%s", inst->op);
			if (inst->value)
				printf(" value=%ld", inst->value);
			if (inst->aux)
				printf(" aux=%d", inst->aux);
			if (inst->fp_size)
				printf(" fp=%d", inst->fp_size);
			break;
		case IR_RETURN:
			printf("return");
			break;
		case IR_LABEL:
			if (inst->subop == IR_OP_FUNC)
				printf("label func %s stack=%ld params=%d", inst->name, inst->value, inst->aux);
			else
				printf("label L%ld", inst->value);
			break;
		case IR_BRANCH:
			printf("branch %s L%ld", inst->op, inst->value);
			if (inst->fp_size)
				printf(" fp=%d", inst->fp_size);
			break;
		case IR_CALL:
			printf("call %s argc=%ld", inst->name, inst->value);
			if (inst->fixed_params >= 0)
				printf(" fixed=%d", inst->fixed_params);
			if (inst->simple_call_arg_count > 0)
				printf(" simple=%u", (unsigned)inst->simple_call_arg_count);
			if (inst->fp_arg_mask)
				printf(" fp=0x%x", inst->fp_arg_mask);
			break;
		case IR_CALL_INDIRECT:
			printf("call_indirect argc=%ld", inst->value);
			break;
		case IR_CALL_ACC_ARG0:
			printf("call_acc_arg0 %s", inst->name);
			break;
		case IR_CALL_PACKED_GPR:
			printf("call_packed_gpr %s argc=%ld stack=%d", inst->name, inst->value,
			       inst->fixed_params);
			break;
		case IR_ASM:
			printf("asm%s \"%s\"", inst->aux ? " volatile" : "", inst->name);
			break;
		case IR_POP:
			printf("pop");
			break;
		}

		printf("\n");
	}
}

void 
ir_free(IRProgram *program)
{
	if (!program)
		return;

	IRInst *inst = program->head;
	while (inst) {
		IRInst *next = inst->next;
		if (inst->param_names) {
			for (int i = 0; i < inst->aux; i++)
				xfree(inst->param_names[i]);
			xfree(inst->param_names);
		}
		if (inst->param_struct_names) {
			for (int i = 0; i < inst->aux; i++)
				xfree(inst->param_struct_names[i]);
			xfree(inst->param_struct_names);
		}
		if (inst->param_pointer_struct_names) {
			for (int i = 0; i < inst->aux; i++)
				xfree(inst->param_pointer_struct_names[i]);
			xfree(inst->param_pointer_struct_names);
		}
		xfree(inst->param_pointer_depths);
		xfree(inst->param_offsets);
		xfree(inst->param_abi_sizes);
		xfree(inst->param_type_ids);
		if (inst->debug_locals) {
			for (int i = 0; i < inst->debug_local_count; i++)
				xfree(inst->debug_locals[i].name);
			xfree(inst->debug_locals);
		}
		ir_inst_clear_simple_call_args(inst);
		xfree(inst->name);
		xfree(inst);
		inst = next;
	}

	IRString *str = program->strings;
	while (str) {
		IRString *next = str->next;
		xfree(str->value);
		xfree(str);
		str = next;
	}

	for (int i = 0; i < program->unsupported_func_count; i++)
		xfree(program->unsupported_funcs[i].name);
	for (int i = 0; i < program->unsupported_func_count; i++)
		xfree(program->unsupported_funcs[i].reason);
	xfree(program->unsupported_funcs);
	for (int i = 0; i < program->function_span_count; i++)
		xfree(program->function_spans[i].name);
	xfree(program->function_spans);

	xfree(program);
}

static int __attribute__((unused))
ir_supported_binop(const char *op)
{
	return ir_subop_is_binop(ir_op_to_subop(op));
}

static int __attribute__((unused))
ir_supported_unop(const char *op)
{
	return ir_subop_is_unop(ir_op_to_subop(op));
}

int 
ir_can_codegen(IRProgram *program)
{
	return program->unsupported_count == 0;
}

static void 
ir_emit_binop(Codegen *cg, const char *op, int aux)
{
	if (aux && cg->emit_binop_sized &&
	    (STRCMP(op, "mul") == 0 ||
	     STRCMP(op, "div") == 0 ||
	     STRCMP(op, "mod") == 0 ||
	     STRCMP(op, "udiv") == 0 ||
	     STRCMP(op, "umod") == 0)) {
		cg->emit_binop_sized(op, aux);
		return;
	}

	if (STRCMP(op, "add") == 0)
		cg->emit_add();
	else if (STRCMP(op, "sub") == 0)
		cg->emit_sub();
	else if (STRCMP(op, "mul") == 0)
		cg->emit_mul();
	else if (STRCMP(op, "div") == 0) {
		if (aux && cg->emit_div_sized) cg->emit_div_sized(aux);
		else cg->emit_div();
	} else if (STRCMP(op, "mod") == 0) {
		if (aux && cg->emit_mod_sized) cg->emit_mod_sized(aux);
		else cg->emit_mod();
	}
	else if (STRCMP(op, "and") == 0)
		cg->emit_bitand();
	else if (STRCMP(op, "or") == 0)
		cg->emit_bitor();
	else if (STRCMP(op, "xor") == 0)
		cg->emit_bitxor();
	else if (STRCMP(op, "shl") == 0)
		cg->emit_shl();
	else if (STRCMP(op, "shr") == 0)
		cg->emit_shr();
	else if (STRCMP(op, "udiv") == 0) {
		if (aux && cg->emit_udiv_sized) cg->emit_udiv_sized(aux);
		else if (cg->emit_udiv) cg->emit_udiv();
		else cg->emit_div();
	} else if (STRCMP(op, "umod") == 0) {
		if (aux && cg->emit_umod_sized) cg->emit_umod_sized(aux);
		else if (cg->emit_umod) cg->emit_umod();
		else cg->emit_mod();
	} else if (STRCMP(op, "ushr") == 0) {
		if (cg->emit_ushr) cg->emit_ushr();
		else cg->emit_shr();
	}
	/* Comparison ops: use sized variants when aux carries operand size */
	else if (STRCMP(op, "eq") == 0) {
		if (aux && cg->emit_cmp_eq_sized) cg->emit_cmp_eq_sized(aux);
		else cg->emit_cmp_eq();
	} else if (STRCMP(op, "ne") == 0) {
		if (aux && cg->emit_cmp_ne_sized) cg->emit_cmp_ne_sized(aux);
		else cg->emit_cmp_ne();
	} else if (STRCMP(op, "lt") == 0) {
		if (aux && cg->emit_cmp_lt_sized) cg->emit_cmp_lt_sized(aux);
		else cg->emit_cmp_lt();
	} else if (STRCMP(op, "le") == 0) {
		if (aux && cg->emit_cmp_le_sized) cg->emit_cmp_le_sized(aux);
		else cg->emit_cmp_le();
	} else if (STRCMP(op, "gt") == 0) {
		if (aux && cg->emit_cmp_gt_sized) cg->emit_cmp_gt_sized(aux);
		else cg->emit_cmp_gt();
	} else if (STRCMP(op, "ge") == 0) {
		if (aux && cg->emit_cmp_ge_sized) cg->emit_cmp_ge_sized(aux);
		else cg->emit_cmp_ge();
	} else if (STRCMP(op, "ult") == 0 && cg->emit_cmp_lt_u) {
		if (aux && cg->emit_cmp_lt_u_sized) cg->emit_cmp_lt_u_sized(aux);
		else cg->emit_cmp_lt_u();
	} else if (STRCMP(op, "ule") == 0 && cg->emit_cmp_le_u) {
		if (aux && cg->emit_cmp_le_u_sized) cg->emit_cmp_le_u_sized(aux);
		else cg->emit_cmp_le_u();
	} else if (STRCMP(op, "ugt") == 0 && cg->emit_cmp_gt_u) {
		if (aux && cg->emit_cmp_gt_u_sized) cg->emit_cmp_gt_u_sized(aux);
		else cg->emit_cmp_gt_u();
	} else if (STRCMP(op, "uge") == 0 && cg->emit_cmp_ge_u) {
		if (aux && cg->emit_cmp_ge_u_sized) cg->emit_cmp_ge_u_sized(aux);
		else cg->emit_cmp_ge_u();
	} else if (STRCMP(op, "land") == 0)
		cg->emit_bitand();
	else if (STRCMP(op, "lor") == 0)
		cg->emit_bitor();
	else if (STRCMP(op, "ptr_add") == 0)
		cg->emit_ptr_add(aux ? aux : 1);
	else if (STRCMP(op, "ptr_sub") == 0)
		cg->emit_ptr_sub(aux ? aux : 1);
	else {
		ICE("Unsupported IR binop: %s", op);
	}
}

static const char *
ir_branch_compare_to_binop(const char *op)
{
	if (STRCMP(op, "je") == 0 || STRCMP(op, "jne") == 0)
		return STRCMP(op, "je") == 0 ? "eq" : "ne";
	if (STRCMP(op, "jlt") == 0 || STRCMP(op, "jge") == 0)
		return STRCMP(op, "jlt") == 0 ? "lt" : "ge";
	if (STRCMP(op, "jle") == 0 || STRCMP(op, "jgt") == 0)
		return STRCMP(op, "jle") == 0 ? "le" : "gt";
	if (STRCMP(op, "jult") == 0 || STRCMP(op, "juge") == 0)
		return STRCMP(op, "jult") == 0 ? "ult" : "uge";
	if (STRCMP(op, "jule") == 0 || STRCMP(op, "jugt") == 0)
		return STRCMP(op, "jule") == 0 ? "ule" : "ugt";
	return NULL;
}

static const char *
ir_binop_to_branch_compare(const char *op, int branch_on_true)
{
	if (STRCMP(op, "eq") == 0)
		return branch_on_true ? "je" : "jne";
	if (STRCMP(op, "ne") == 0)
		return branch_on_true ? "jne" : "je";
	if (STRCMP(op, "lt") == 0)
		return branch_on_true ? "jlt" : "jge";
	if (STRCMP(op, "le") == 0)
		return branch_on_true ? "jle" : "jgt";
	if (STRCMP(op, "gt") == 0)
		return branch_on_true ? "jgt" : "jle";
	if (STRCMP(op, "ge") == 0)
		return branch_on_true ? "jge" : "jlt";
	if (STRCMP(op, "ult") == 0)
		return branch_on_true ? "jult" : "juge";
	if (STRCMP(op, "ule") == 0)
		return branch_on_true ? "jule" : "jugt";
	if (STRCMP(op, "ugt") == 0)
		return branch_on_true ? "jugt" : "jule";
	if (STRCMP(op, "uge") == 0)
		return branch_on_true ? "juge" : "jult";
	return NULL;
}

static void
ir_emit_cmp_branch(Codegen *cg, const char *op, int size, int label)
{
	const char *binop;

	if (cg->emit_cmp_branch) {
		cg->emit_cmp_branch(op, size, label);
		return;
	}

	binop = ir_branch_compare_to_binop(op);
	if (!binop)
		ICE("Unsupported IR compare-branch op: %s", op);

	ir_emit_binop(cg, binop, size);
	cg->emit_branch_if_nonzero(label);
}

static int
ir_branch_is_compare_op(const IRInst *inst)
{
	if (!inst || inst->kind != IR_BRANCH)
		return 0;
	return inst->subop == IR_OP_JE || inst->subop == IR_OP_JNE ||
	       inst->subop == IR_OP_JLT || inst->subop == IR_OP_JLE ||
	       inst->subop == IR_OP_JGT || inst->subop == IR_OP_JGE ||
	       inst->subop == IR_OP_JULT || inst->subop == IR_OP_JULE ||
	       inst->subop == IR_OP_JUGT || inst->subop == IR_OP_JUGE;
}

static void
ir_close_emitted_function(Codegen *cg, int *in_function, const char **current_func_name,
                          int *function_just_ended, int emit_epilogue,
                          int debug_unit_active, int *current_debug_end_label,
                          int *current_function_exit_label);

static int
ir_cast_is_redundant_after_load(const IRInst *cast_inst, int load_size, int load_is_unsigned);

typedef struct IRGlobalMemberCmpPattern {
	IRInst *const_base_inst;
	IRInst *addr_gidx_inst;
	IRInst *add_offset_inst;
	IRInst *member_inst;
	IRInst *cast_inst;
	IRInst *imm_inst;
	IRInst *branch_inst;
	const char *name;
	long total_offset;
	int load_size;
	int is_extern;
	int cast_size;
	int cast_unsigned;
} IRGlobalMemberCmpPattern;

static int
ir_match_global_member_cmp_branch_pattern(IRInst *inst, IRGlobalMemberCmpPattern *pat)
{
	IRInst *addr_gidx;
	IRInst *add_offset = NULL;
	IRInst *member_inst;
	IRInst *cast_inst = NULL;
	IRInst *imm_inst;
	IRInst *branch_inst;
	long scale;
	long total_offset;

	if (!inst || inst->kind != IR_CONST || !pat)
		return 0;

	addr_gidx = inst->next;
	if (!addr_gidx || addr_gidx->kind != IR_UNOP ||
	    addr_gidx->subop != IR_OP_ADDR_GIDX || !addr_gidx->name[0])
		return 0;

	member_inst = addr_gidx->next;
	if (member_inst && member_inst->kind == IR_UNOP &&
	    member_inst->subop == IR_OP_ADD_OFFSET) {
		add_offset = member_inst;
		member_inst = add_offset->next;
	}
	if (!member_inst || member_inst->kind != IR_UNOP ||
	    member_inst->subop != IR_OP_MEMBER_PTR)
		return 0;

	imm_inst = member_inst->next;
	if (imm_inst && imm_inst->kind == IR_UNOP &&
	    imm_inst->subop == IR_OP_CAST) {
		cast_inst = imm_inst;
		imm_inst = cast_inst->next;
	}
	if (!imm_inst || imm_inst->kind != IR_CONST)
		return 0;

	branch_inst = imm_inst->next;
	if (!branch_inst || branch_inst->kind != IR_BRANCH)
		return 0;
	if (branch_inst->subop != IR_OP_JE && branch_inst->subop != IR_OP_JNE &&
	    branch_inst->subop != IR_OP_JLT && branch_inst->subop != IR_OP_JLE &&
	    branch_inst->subop != IR_OP_JGT && branch_inst->subop != IR_OP_JGE &&
	    branch_inst->subop != IR_OP_JULT && branch_inst->subop != IR_OP_JULE &&
	    branch_inst->subop != IR_OP_JUGT && branch_inst->subop != IR_OP_JUGE)
		return 0;

	scale = addr_gidx->aux ? addr_gidx->aux : TCC_SIZEOF_INT;
	total_offset = inst->value * scale;
	if (add_offset)
		total_offset += add_offset->value;
	total_offset += member_inst->value;
	if ((long)(int)total_offset != total_offset)
		return 0;

	pat->const_base_inst = inst;
	pat->addr_gidx_inst = addr_gidx;
	pat->add_offset_inst = add_offset;
	pat->member_inst = member_inst;
	pat->cast_inst = cast_inst;
	pat->imm_inst = imm_inst;
	pat->branch_inst = branch_inst;
	pat->name = addr_gidx->name;
	pat->total_offset = total_offset;
	pat->load_size = member_inst->aux ? member_inst->aux : TCC_SIZEOF_INT;
	pat->is_extern = addr_gidx->is_extern;
	pat->cast_size = cast_inst ? (cast_inst->value ? cast_inst->value : TCC_SIZEOF_INT) : 0;
	pat->cast_unsigned = cast_inst ? cast_inst->aux : 0;
	return 1;
}

static int
ir_try_emit_repeated_global_member_cmp_branch_chain(Codegen *cg, IRInst **inst_ptr)
{
	IRGlobalMemberCmpPattern first;
	IRGlobalMemberCmpPattern cur;
	IRInst *cursor;
	IRInst *last_branch;
	int count = 0;

	if (!cg || !inst_ptr || !*inst_ptr || !cg->emit_load_global_member)
		return 0;
	if (!ir_match_global_member_cmp_branch_pattern(*inst_ptr, &first))
		return 0;

	cursor = *inst_ptr;
	last_branch = NULL;
	while (ir_match_global_member_cmp_branch_pattern(cursor, &cur)) {
		if (strcmp(cur.name, first.name) != 0 ||
		    cur.total_offset != first.total_offset ||
		    cur.load_size != first.load_size ||
		    cur.is_extern != first.is_extern ||
		    cur.cast_size != first.cast_size ||
		    cur.cast_unsigned != first.cast_unsigned)
			break;
		last_branch = cur.branch_inst;
		count++;
		cursor = cur.branch_inst->next;
	}
	if (count < 2 || !last_branch)
		return 0;

	cg->emit_load_global_member(first.name, (int)first.total_offset,
	                            first.load_size, first.is_extern);
	if (first.cast_inst && cg->emit_cast &&
	    !ir_cast_is_redundant_after_load(first.cast_inst, first.load_size, 0))
		cg->emit_cast(first.cast_size, first.cast_unsigned);

	cursor = *inst_ptr;
	while (ir_match_global_member_cmp_branch_pattern(cursor, &cur)) {
		if (strcmp(cur.name, first.name) != 0 ||
		    cur.total_offset != first.total_offset ||
		    cur.load_size != first.load_size ||
		    cur.is_extern != first.is_extern ||
		    cur.cast_size != first.cast_size ||
		    cur.cast_unsigned != first.cast_unsigned)
			break;
		if (cg->emit_cmp_branch_imm)
			cg->emit_cmp_branch_imm(cur.branch_inst->op, cur.branch_inst->aux,
			                        cur.imm_inst->value, cur.branch_inst->value);
		else {
			cg->emit_acc_to_tmp();
			cg->emit_load_imm(cur.imm_inst->value);
			ir_emit_cmp_branch(cg, cur.branch_inst->op,
			                   cur.branch_inst->aux,
			                   cur.branch_inst->value);
		}
		cursor = cur.branch_inst->next;
	}

	*inst_ptr = last_branch;
	return 1;
}

static int
ir_try_emit_zero_compare_branch_from_acc(Codegen *cg, IRInst **inst_ptr)
{
	IRInst *const_inst;
	IRInst *cmp_inst;
	IRInst *branch_inst;
	const char *branch_op;
	int branch_if_zero;

	if (!cg || !inst_ptr || !*inst_ptr ||
	    !cg->emit_load_func_addr || !cg->emit_acc_to_saved ||
	    !cg->emit_load_via_saved || !cg->emit_acc_to_tmp ||
	    !cg->emit_load_imm || !cg->emit_add ||
	    !cg->emit_store_via_saved || !cg->emit_tmp_to_acc)
		return 0;

	const_inst = (*inst_ptr)->next;
	if (!const_inst || const_inst->kind != IR_CONST)
		return 0;

	branch_inst = const_inst->next;
	if (branch_inst && branch_inst->kind == IR_BRANCH) {
		if (const_inst->value == 0 && branch_inst->subop == IR_OP_JE) {
			cg->emit_branch_if_zero(branch_inst->value);
			*inst_ptr = branch_inst;
			return 1;
		}
		if (const_inst->value == 0 && branch_inst->subop == IR_OP_JNE) {
			cg->emit_branch_if_nonzero(branch_inst->value);
			*inst_ptr = branch_inst;
			return 1;
		}
		if (branch_inst->subop == IR_OP_JE || branch_inst->subop == IR_OP_JNE ||
		    branch_inst->subop == IR_OP_JLT || branch_inst->subop == IR_OP_JLE ||
		    branch_inst->subop == IR_OP_JGT || branch_inst->subop == IR_OP_JGE ||
		    branch_inst->subop == IR_OP_JULT || branch_inst->subop == IR_OP_JULE ||
		    branch_inst->subop == IR_OP_JUGT || branch_inst->subop == IR_OP_JUGE) {
			if (cg->emit_cmp_branch_imm)
				cg->emit_cmp_branch_imm(branch_inst->op, branch_inst->aux,
				                        const_inst->value, branch_inst->value);
			else {
				cg->emit_acc_to_tmp();
				cg->emit_load_imm(const_inst->value);
				ir_emit_cmp_branch(cg, branch_inst->op, branch_inst->aux, branch_inst->value);
			}
			*inst_ptr = branch_inst;
			return 1;
		}
	}

	cmp_inst = const_inst->next;
	if (!cmp_inst || cmp_inst->kind != IR_BINOP)
		return 0;
	if (cmp_inst->subop != IR_OP_EQ && cmp_inst->subop != IR_OP_NE &&
	    cmp_inst->subop != IR_OP_LT && cmp_inst->subop != IR_OP_LE &&
	    cmp_inst->subop != IR_OP_GT && cmp_inst->subop != IR_OP_GE &&
	    cmp_inst->subop != IR_OP_ULT && cmp_inst->subop != IR_OP_ULE &&
	    cmp_inst->subop != IR_OP_UGT && cmp_inst->subop != IR_OP_UGE)
		return 0;

	branch_inst = cmp_inst->next;
	if (!branch_inst || branch_inst->kind != IR_BRANCH)
		return 0;
	if (branch_inst->subop != IR_OP_JZ && branch_inst->subop != IR_OP_JNZ)
		return 0;

	if (const_inst->value == 0 &&
	    (cmp_inst->subop == IR_OP_EQ || cmp_inst->subop == IR_OP_NE)) {
		if (cmp_inst->subop == IR_OP_EQ)
			branch_if_zero = (branch_inst->subop == IR_OP_JNZ);
		else
			branch_if_zero = (branch_inst->subop == IR_OP_JZ);

		if (branch_if_zero)
			cg->emit_branch_if_zero(branch_inst->value);
		else
			cg->emit_branch_if_nonzero(branch_inst->value);
	} else {
		branch_op = ir_binop_to_branch_compare(cmp_inst->op,
		                                       branch_inst->subop == IR_OP_JNZ);
		if (!branch_op)
			return 0;
		if (cg->emit_cmp_branch_imm)
			cg->emit_cmp_branch_imm(branch_op, cmp_inst->aux,
			                        const_inst->value, branch_inst->value);
		else {
			cg->emit_acc_to_tmp();
			cg->emit_load_imm(const_inst->value);
			ir_emit_cmp_branch(cg, branch_op, cmp_inst->aux, branch_inst->value);
		}
	}

	*inst_ptr = branch_inst;
	return 1;
}

static int
ir_try_finish_value_from_acc(Codegen *cg, IRInst **inst_ptr,
                             int *in_function, const char **current_func_name,
                             int *function_just_ended, int debug_unit_active,
                             int *current_debug_end_label,
                             int *current_function_exit_label,
                             int *skip_linear_until_label)
{
	IRInst *next;
	IRInst *cast_inst;

	if (!inst_ptr || !*inst_ptr)
		return 0;

	next = (*inst_ptr)->next;
	if (!next)
		return 0;

	if (next->kind == IR_RETURN) {
		if (!next->aux && next->fp_size) {
			if (!cg->emit_acc_bits_to_fp_return)
				ICE("backend missing emit_acc_bits_to_fp_return");
			cg->emit_acc_bits_to_fp_return(next->fp_size);
		}
		IRInst *after_return = next->next;
		if (!after_return ||
		    (after_return->kind == IR_LABEL && after_return->subop == IR_OP_FUNC)) {
			ir_close_emitted_function(cg, in_function, current_func_name,
			                          function_just_ended, 0,
			                          debug_unit_active, current_debug_end_label,
			                          current_function_exit_label);
		} else if (current_function_exit_label && *current_function_exit_label > 0) {
			cg->emit_branch(*current_function_exit_label);
			if (skip_linear_until_label)
				*skip_linear_until_label = 1;
		} else {
			ir_close_emitted_function(cg, in_function, current_func_name,
			                          function_just_ended, 0,
			                          debug_unit_active, current_debug_end_label,
			                          current_function_exit_label);
		}
		*inst_ptr = next;
		return 1;
	}

	if (next->kind == IR_POP) {
		*inst_ptr = next;
		return 1;
	}

	if (next->kind == IR_UNOP && next->subop == IR_OP_CAST) {
		IRInst *tail = next;
		IRInst *after_cast;
		int cast_size;
		int omit_arm64_return_cast = 0;

		while (tail->next &&
		       tail->next->kind == IR_UNOP &&
		       tail->next->subop == IR_OP_CAST &&
		       tail->next->value == tail->value &&
		       tail->next->aux == tail->aux &&
		       tail->next->fp_size == tail->fp_size)
			tail = tail->next;

		after_cast = tail->next;
		if (!after_cast)
			return 0;

		if (after_cast->kind == IR_POP) {
			*inst_ptr = after_cast;
			return 1;
		}

		if (after_cast->kind != IR_RETURN)
			return 0;

		cast_inst = next;
		cast_size = cast_inst->value ? cast_inst->value : 4;
		if (cg == &arm64_codegen &&
		    cast_inst->fp_size == 0 &&
		    cast_size == 4) {
			/* AArch64 integer return values are observed through w0.
			 * A final cast to int does not need an explicit sxtw/uxtw
			 * before ret. Narrower widths still do. */
			omit_arm64_return_cast = 1;
		}
		if (!omit_arm64_return_cast)
			cg->emit_cast(cast_size, cast_inst->aux != 0);

		if (!after_cast->next ||
		    (after_cast->next->kind == IR_LABEL && after_cast->next->subop == IR_OP_FUNC)) {
			ir_close_emitted_function(cg, in_function, current_func_name,
			                          function_just_ended, 0,
			                          debug_unit_active, current_debug_end_label,
			                          current_function_exit_label);
		} else if (current_function_exit_label && *current_function_exit_label > 0) {
			cg->emit_branch(*current_function_exit_label);
			if (skip_linear_until_label)
				*skip_linear_until_label = 1;
		} else {
			ir_close_emitted_function(cg, in_function, current_func_name,
			                          function_just_ended, 0,
			                          debug_unit_active, current_debug_end_label,
			                          current_function_exit_label);
		}
		*inst_ptr = after_cast;
		return 1;
	}

	return 0;
}

static int
ir_try_finish_fp_value_from_call(Codegen *cg, IRInst **inst_ptr,
                                 int *in_function, const char **current_func_name,
                                 int *function_just_ended, int debug_unit_active,
                                 int *current_debug_end_label,
                                 int *current_function_exit_label,
                                 int *skip_linear_until_label)
{
	IRInst *next;

	if (!inst_ptr || !*inst_ptr)
		return 0;

	next = (*inst_ptr)->next;
	if (!next || next->kind != IR_RETURN)
		return 0;

	if (!next->next ||
	    (next->next->kind == IR_LABEL && next->next->subop == IR_OP_FUNC)) {
		ir_close_emitted_function(cg, in_function, current_func_name,
		                          function_just_ended, 0,
		                          debug_unit_active, current_debug_end_label,
		                          current_function_exit_label);
	} else if (current_function_exit_label && *current_function_exit_label > 0) {
		cg->emit_branch(*current_function_exit_label);
		if (skip_linear_until_label)
			*skip_linear_until_label = 1;
	} else {
		ir_close_emitted_function(cg, in_function, current_func_name,
		                          function_just_ended, 0,
		                          debug_unit_active, current_debug_end_label,
		                          current_function_exit_label);
	}

	*inst_ptr = next;
	return 1;
}

static int
ir_try_store_then_branch_from_acc(Codegen *cg, IRInst **inst_ptr)
{
	IRInst *store_inst;
	IRInst *load_inst;
	IRInst *cast_inst = NULL;
	IRInst *const_inst;
	IRInst *branch_inst;
	int size;

	if (!cg || !inst_ptr || !*inst_ptr)
		return 0;

	store_inst = (*inst_ptr)->next;
	if (!store_inst || store_inst->kind != IR_STORE ||
	    store_inst->subop != IR_OP_LOCAL)
		return 0;
	load_inst = store_inst->next;
	if (!load_inst || load_inst->kind != IR_LOAD ||
	    load_inst->subop != IR_OP_LOCAL ||
	    load_inst->value != store_inst->value)
		return 0;
	size = store_inst->aux ? store_inst->aux : TCC_SIZEOF_INT;
	if ((load_inst->aux ? load_inst->aux : TCC_SIZEOF_INT) != size)
		return 0;
	branch_inst = load_inst->next;
	if (branch_inst && branch_inst->kind == IR_UNOP &&
	    branch_inst->subop == IR_OP_CAST &&
	    branch_inst->value == size) {
		cast_inst = branch_inst;
		branch_inst = cast_inst->next;
	}
	if (!branch_inst)
		return 0;
	if (branch_inst->kind == IR_BRANCH) {
		if (branch_inst->subop != IR_OP_JZ && branch_inst->subop != IR_OP_JNZ)
			return 0;

		cg->emit_store_local_sized(store_inst->value, size);
		if (branch_inst->subop == IR_OP_JZ)
			cg->emit_branch_if_zero(branch_inst->value);
		else
			cg->emit_branch_if_nonzero(branch_inst->value);
		*inst_ptr = branch_inst;
		return 1;
	}
	if (branch_inst->kind != IR_CONST || branch_inst->value != 0)
		return 0;
	const_inst = branch_inst;
	branch_inst = const_inst->next;
	if (!branch_inst || branch_inst->kind != IR_BRANCH)
		return 0;
	if (branch_inst->subop != IR_OP_JE && branch_inst->subop != IR_OP_JNE)
		return 0;

	cg->emit_store_local_sized(store_inst->value, size);
	if (branch_inst->subop == IR_OP_JE)
		cg->emit_branch_if_zero(branch_inst->value);
	else
		cg->emit_branch_if_nonzero(branch_inst->value);
	*inst_ptr = branch_inst;
	return 1;
}

static int
ir_try_store_value_from_acc(Codegen *cg, IRInst **inst_ptr)
{
	IRInst *store_inst;

	if (!cg || !inst_ptr || !*inst_ptr)
		return 0;

	store_inst = (*inst_ptr)->next;
	if (!store_inst || store_inst->kind != IR_STORE)
		return 0;

	switch ((IRSubOp)store_inst->subop) {
	case IR_OP_LOCAL:
		cg->emit_store_local_sized(store_inst->value,
		                           store_inst->aux ? store_inst->aux : TCC_SIZEOF_INT);
		break;
	case IR_OP_LOCAL_PTR_MEMBER:
		if (!cg->emit_store_local_ptr_member)
			return 0;
		cg->emit_store_local_ptr_member((int)store_inst->value,
		                                store_inst->fixed_params,
		                                store_inst->aux ? store_inst->aux : TCC_SIZEOF_INT);
		break;
	case IR_OP_GLOBAL:
		if (store_inst->is_extern)
			cg->emit_store_global_extern(store_inst->name);
		else
			cg->emit_store_global(store_inst->name,
			                      ir_global_elem_size(store_inst->name));
		break;
	default:
		return 0;
	}

	*inst_ptr = store_inst;
	return 1;
}

static int
ir_bool_materialized_tail_is_sink(IRInst *label_end)
{
	IRInst *next;

	if (!label_end)
		return 0;

	next = label_end->next;
	if (!next)
		return 0;

	if (next->kind == IR_STORE &&
	    (next->subop == IR_OP_LOCAL || next->subop == IR_OP_GLOBAL))
		return 1;

	if (next->kind == IR_RETURN || next->kind == IR_POP)
		return 1;

	if (next->kind == IR_UNOP && next->subop == IR_OP_CAST) {
		IRInst *tail = next;

		while (tail->next &&
		       tail->next->kind == IR_UNOP &&
		       tail->next->subop == IR_OP_CAST &&
		       tail->next->value == tail->value &&
		       tail->next->aux == tail->aux &&
		       tail->next->fp_size == tail->fp_size)
			tail = tail->next;

		next = tail->next;
		return next && (next->kind == IR_RETURN || next->kind == IR_POP);
	}

	return 0;
}

static int
ir_try_emit_bool_const_sink(Codegen *cg, IRInst **inst_ptr,
                            int *in_function, const char **current_func_name,
                            int *function_just_ended, int debug_unit_active,
                            int *current_debug_end_label,
                            int *current_function_exit_label,
                            int *skip_linear_until_label)
{
	IRInst *true_const;
	IRInst *jump_inst;
	IRInst *false_label;
	IRInst *false_const;
	IRInst *end_label;
	IRInst *cursor;

	if (!cg || !cg->emit_load_imm || !cg->emit_branch || !cg->emit_label ||
	    !inst_ptr || !*inst_ptr)
		return 0;

	true_const = *inst_ptr;
	jump_inst = true_const ? true_const->next : NULL;
	false_label = jump_inst ? jump_inst->next : NULL;
	false_const = false_label ? false_label->next : NULL;
	end_label = false_const ? false_const->next : NULL;

	if (!true_const || true_const->kind != IR_CONST ||
	    !jump_inst || jump_inst->kind != IR_BRANCH || jump_inst->subop != IR_OP_JMP ||
	    !false_label || false_label->kind != IR_LABEL ||
	    !false_const || false_const->kind != IR_CONST ||
	    !end_label || end_label->kind != IR_LABEL)
		return 0;

	if (!ir_bool_materialized_tail_is_sink(end_label))
		return 0;

	cg->emit_load_imm(true_const->value);
	cg->emit_branch(end_label->value);
	cg->emit_label(false_label->value);
	cg->emit_load_imm(false_const->value);
	cg->emit_label(end_label->value);

	cursor = end_label;
	if (ir_try_store_value_from_acc(cg, &cursor)) {
		*inst_ptr = cursor;
		return 1;
	}
	if (ir_try_finish_value_from_acc(cg, &cursor, in_function,
	                                 current_func_name, function_just_ended,
	                                 debug_unit_active, current_debug_end_label,
	                                 current_function_exit_label,
	                                 skip_linear_until_label)) {
		*inst_ptr = cursor;
		return 1;
	}

	ICE("bool sink matcher accepted unsupported tail");
}

static int
ir_finish_emitted_call_result(Codegen *cg, IRInst **inst_ptr,
                              int *in_function, const char **current_func_name,
                              int *function_just_ended, int debug_unit_active,
                              int *current_debug_end_label,
                              int *current_function_exit_label,
                              int *skip_linear_until_label)
{
	IRInst *inst;

	if (!cg || !inst_ptr || !*inst_ptr)
		return 0;
	inst = *inst_ptr;

	if (inst->result_is_fp) {
		if (cg == &x64_codegen && inst->result_size == 16) {
			IRInst *next = inst->next;

			if (next &&
			    (next->subop == IR_OP_X64_STORE_RET_FP_AGG_LOCAL ||
			     next->subop == IR_OP_X64_STORE_RET_FP_AGG_GLOBAL)) {
				ir_emit_x64_store_ret_fp_aggregate(cg, next);
				*inst_ptr = next;
				return 1;
			}
			if (next && next->kind == IR_RETURN) {
				if (!next->next ||
				    (next->next->kind == IR_LABEL && next->next->subop == IR_OP_FUNC)) {
					ir_close_emitted_function(cg, in_function, current_func_name,
					                          function_just_ended, 0,
					                          debug_unit_active, current_debug_end_label,
					                          current_function_exit_label);
				} else if (current_function_exit_label && *current_function_exit_label > 0) {
					cg->emit_branch(*current_function_exit_label);
					if (skip_linear_until_label)
						*skip_linear_until_label = 1;
				} else {
					ir_close_emitted_function(cg, in_function, current_func_name,
					                          function_just_ended, 0,
					                          debug_unit_active, current_debug_end_label,
					                          current_function_exit_label);
				}
				*inst_ptr = next;
				return 1;
			}
			return 0;
		}
		if (ir_try_finish_fp_value_from_call(cg, inst_ptr, in_function,
		                                     current_func_name, function_just_ended,
		                                     debug_unit_active, current_debug_end_label,
		                                     current_function_exit_label,
		                                     skip_linear_until_label))
			return 1;
		if (!cg->emit_fp_to_acc_bits)
			ICE("backend missing emit_fp_to_acc_bits");
		cg->emit_fp_to_acc_bits(inst->result_size ? inst->result_size : 8);
	}
	if (inst->aux)
		return 1;
	if (ir_try_emit_zero_compare_branch_from_acc(cg, inst_ptr))
		return 1;
	if (inst->next && inst->next->kind == IR_BRANCH) {
		if (inst->next->subop == IR_OP_JZ) {
			cg->emit_branch_if_zero(inst->next->value);
			*inst_ptr = inst->next;
			return 1;
		}
		if (inst->next->subop == IR_OP_JNZ) {
			cg->emit_branch_if_nonzero(inst->next->value);
			*inst_ptr = inst->next;
			return 1;
		}
	}
	if (ir_try_store_then_branch_from_acc(cg, inst_ptr))
		return 1;
	if (ir_try_store_value_from_acc(cg, inst_ptr))
		return 1;
	if (ir_try_finish_value_from_acc(cg, inst_ptr, in_function,
	                                 current_func_name, function_just_ended,
	                                 debug_unit_active, current_debug_end_label,
	                                 current_function_exit_label,
	                                 skip_linear_until_label))
		return 1;
	cg->emit_push_acc();
	return 1;
}

static int
ir_try_emit_arm64_local_cast_local_pair_call(Codegen *cg, IRInst **inst_ptr,
                                             int *in_function, const char **current_func_name,
                                             int *function_just_ended, int debug_unit_active,
                                             int *current_debug_end_label,
                                             int *current_function_exit_label,
                                             int *skip_linear_until_label)
{
	IRInst *arg1_inst;
	IRInst *cast_inst;
	IRInst *arg0_inst;
	IRInst *call_inst;
	int arg1_size;
	int arg0_size;

	if (!cg || cg != &arm64_codegen || !cg->emit_load_local_to_arg ||
	    !inst_ptr || !*inst_ptr)
		return 0;

	arg1_inst = *inst_ptr;
	cast_inst = arg1_inst ? arg1_inst->next : NULL;
	arg0_inst = cast_inst ? cast_inst->next : NULL;
	call_inst = arg0_inst ? arg0_inst->next : NULL;

	if (!arg1_inst || arg1_inst->kind != IR_LOAD || arg1_inst->subop != IR_OP_LOCAL ||
	    !cast_inst || cast_inst->kind != IR_UNOP || cast_inst->subop != IR_OP_CAST ||
	    !arg0_inst || arg0_inst->kind != IR_LOAD || arg0_inst->subop != IR_OP_LOCAL ||
	    !call_inst || call_inst->kind != IR_CALL || call_inst->value != 2 ||
	    call_inst->fp_arg_mask != 0)
		return 0;
	if (call_inst->fixed_params >= 0 && call_inst->value > call_inst->fixed_params)
		return 0;

	arg1_size = cast_inst->value ? cast_inst->value : (arg1_inst->aux ? arg1_inst->aux : TCC_SIZEOF_INT);
	arg0_size = arg0_inst->aux ? arg0_inst->aux : TCC_SIZEOF_INT;
	if (arg1_size != 1 && arg1_size != 2 &&
	    arg1_size != 4 && arg1_size != TCC_SIZEOF_PTR)
		return 0;
	if (arg0_size != 1 && arg0_size != 2 &&
	    arg0_size != 4 && arg0_size != TCC_SIZEOF_PTR)
		return 0;

	cg->emit_load_local_to_arg(0, arg0_inst->value, arg0_size);
	cg->emit_load_local_to_arg(1, arg1_inst->value, arg1_size);
	cg->emit_call(call_inst->name);
	cg->emit_cleanup_call_args(2, call_inst->fixed_params);
	*inst_ptr = call_inst;
	ir_finish_emitted_call_result(cg, inst_ptr, in_function,
	                              current_func_name, function_just_ended,
	                              debug_unit_active, current_debug_end_label,
	                              current_function_exit_label,
	                              skip_linear_until_label);
	return 1;
}

static int
ir_try_emit_arm64_local_pair_call(Codegen *cg, IRInst **inst_ptr,
                                  int *in_function, const char **current_func_name,
                                  int *function_just_ended, int debug_unit_active,
                                  int *current_debug_end_label,
                                  int *current_function_exit_label,
                                  int *skip_linear_until_label)
{
	IRInst *inst;
	IRInst *arg0;
	IRInst *call_inst;

	if (!cg || cg != &arm64_codegen || !cg->emit_load_local_to_arg ||
	    !inst_ptr || !*inst_ptr)
		return 0;

	inst = *inst_ptr;
	arg0 = inst->next;
	call_inst = arg0 ? arg0->next : NULL;

	if (inst->kind != IR_LOAD || inst->subop != IR_OP_LOCAL ||
	    !arg0 || arg0->kind != IR_LOAD || arg0->subop != IR_OP_LOCAL ||
	    !call_inst || call_inst->kind != IR_CALL ||
	    call_inst->value != 2 || call_inst->fp_arg_mask != 0)
		return 0;
	if (call_inst->fixed_params >= 0 && call_inst->value > call_inst->fixed_params)
		return 0;

	if ((inst->aux ? inst->aux : TCC_SIZEOF_INT) != TCC_SIZEOF_PTR ||
	    (arg0->aux ? arg0->aux : TCC_SIZEOF_INT) != TCC_SIZEOF_PTR)
		return 0;

	cg->emit_load_local_to_arg(1, inst->value, TCC_SIZEOF_PTR);
	cg->emit_load_local_sized(arg0->value, TCC_SIZEOF_PTR);
	cg->emit_call(call_inst->name);
	cg->emit_cleanup_call_args(2, call_inst->fixed_params);
	*inst_ptr = call_inst;
	ir_finish_emitted_call_result(cg, inst_ptr, in_function,
	                              current_func_name, function_just_ended,
	                              debug_unit_active, current_debug_end_label,
	                              current_function_exit_label,
	                              skip_linear_until_label);
	return 1;
}

static int
ir_try_emit_direct_global_index_load(Codegen *cg, IRInst **inst_ptr,
                                     int *in_function, const char **current_func_name,
                                     int *function_just_ended, int debug_unit_active,
                                     int *current_debug_end_label,
                                     int *current_function_exit_label,
                                     int *skip_linear_until_label)
{
	IRInst *inst;
	IRInst *cast_inst = NULL;
	IRInst *gidx_inst;

	if (!cg || !inst_ptr || !*inst_ptr || !cg->emit_load_global_indexed)
		return 0;

	inst = *inst_ptr;
	gidx_inst = inst->next;
	if (inst->kind != IR_LOAD || !gidx_inst)
		return 0;
	if (gidx_inst->kind == IR_UNOP && gidx_inst->subop == IR_OP_CAST &&
	    gidx_inst->value == (inst->aux ? inst->aux : TCC_SIZEOF_INT)) {
		cast_inst = gidx_inst;
		gidx_inst = cast_inst->next;
	}
	if (!gidx_inst ||
	    gidx_inst->kind != IR_UNOP || gidx_inst->subop != IR_OP_GIDX_LOAD)
		return 0;

	if (inst->subop == IR_OP_LOCAL) {
		cg->emit_load_local_sized(inst->value,
		                          inst->aux ? inst->aux : TCC_SIZEOF_INT);
	} else if (inst->subop == IR_OP_GLOBAL) {
		if (inst->is_extern)
			cg->emit_load_global_extern(inst->name);
		else
			cg->emit_load_global(inst->name,
			                     ir_effective_load_size(inst));
	} else {
		return 0;
	}

	cg->emit_load_global_indexed(gidx_inst->name, gidx_inst->value ? gidx_inst->value : 4);
	*inst_ptr = gidx_inst;
	if (ir_try_finish_value_from_acc(cg, inst_ptr, in_function,
	                                 current_func_name, function_just_ended,
	                                 debug_unit_active, current_debug_end_label,
	                                 current_function_exit_label,
	                                 skip_linear_until_label))
		return 1;
	cg->emit_push_acc();
	return 1;
}

static int
ir_try_emit_direct_global_index_mask_cmp_ret(Codegen *cg, IRInst **inst_ptr,
                                             int *in_function, const char **current_func_name,
                                             int *function_just_ended, int debug_unit_active,
                                             int *current_debug_end_label,
                                             int *current_function_exit_label,
                                             int *skip_linear_until_label)
{
	IRInst *inst;
	IRInst *cursor;
	IRInst *gidx_inst;
	IRInst *mask_const;
	IRInst *and_inst;
	IRInst *zero_const;
	IRInst *cmp_inst;
	IRInst *ret_inst;
	int size;
	const char *cond;

	if (!cg || cg != &arm64_codegen || !inst_ptr || !*inst_ptr ||
	    !cg->emit_load_global_indexed || !cg->emit_test_imm_setcc)
		return 0;

	inst = *inst_ptr;
	if (inst->kind != IR_LOAD || inst->subop != IR_OP_LOCAL)
		return 0;

	size = inst->aux ? inst->aux : TCC_SIZEOF_INT;
	cursor = inst->next;
	while (cursor &&
	       cursor->kind == IR_UNOP &&
	       cursor->subop == IR_OP_CAST &&
	       cursor->value == size)
		cursor = cursor->next;
	gidx_inst = cursor;
	if (!gidx_inst || gidx_inst->kind != IR_UNOP || gidx_inst->subop != IR_OP_GIDX_LOAD)
		return 0;
	cursor = gidx_inst->next;
	while (cursor &&
	       cursor->kind == IR_UNOP &&
	       cursor->subop == IR_OP_CAST &&
	       cursor->value == (gidx_inst->value ? gidx_inst->value : TCC_SIZEOF_INT))
		cursor = cursor->next;
	mask_const = cursor;
	and_inst = mask_const ? mask_const->next : NULL;
	zero_const = and_inst ? and_inst->next : NULL;
	cmp_inst = zero_const ? zero_const->next : NULL;
	ret_inst = cmp_inst ? cmp_inst->next : NULL;

	if (!mask_const || mask_const->kind != IR_CONST ||
	    !and_inst || and_inst->kind != IR_BINOP || and_inst->subop != IR_OP_AND ||
	    !zero_const || zero_const->kind != IR_CONST || zero_const->value != 0 ||
	    !cmp_inst || cmp_inst->kind != IR_BINOP ||
	    (cmp_inst->subop != IR_OP_EQ && cmp_inst->subop != IR_OP_NE) ||
	    !ret_inst || ret_inst->kind != IR_RETURN)
		return 0;

	cond = (cmp_inst->subop == IR_OP_EQ) ? "eq" : "ne";
	cg->emit_load_local_sized(inst->value, size);
	cg->emit_load_global_indexed(gidx_inst->name, gidx_inst->value ? gidx_inst->value : 4);
	cg->emit_test_imm_setcc(mask_const->value, cond, 4);

	*inst_ptr = cmp_inst;
	return ir_try_finish_value_from_acc(cg, inst_ptr, in_function,
	                                    current_func_name, function_just_ended,
	                                    debug_unit_active, current_debug_end_label,
	                                    current_function_exit_label,
	                                    skip_linear_until_label);
}

static int
ir_try_emit_const_addr_gidx_local_store_zero_return(Codegen *cg, IRInst **inst_ptr,
                                                     int *in_function, const char **current_func_name,
                                                     int *function_just_ended, int debug_unit_active,
                                                     int *current_debug_end_label,
                                                     int *current_function_exit_label,
                                                     int *skip_linear_until_label)
{
	IRInst *inst;
	IRInst *addr_gidx;
	IRInst *value_last = NULL;
	IRInst *store_inst;
	IRInst *zero_inst;
	long total_offset;
	int value_offset = 0;
	int value_size = 0;
	int value_unsigned = 0;
	int store_size;
	int scale;

	if (!cg || !inst_ptr || !*inst_ptr ||
	    !cg->emit_load_func_addr || !cg->emit_acc_to_saved ||
	    !cg->emit_load_local_sized || !cg->emit_store_via_saved ||
	    !cg->emit_load_imm)
		return 0;

	inst = *inst_ptr;
	if (inst->kind != IR_CONST)
		return 0;
	addr_gidx = inst->next;
	if (!addr_gidx || addr_gidx->kind != IR_UNOP ||
	    addr_gidx->subop != IR_OP_ADDR_GIDX || !addr_gidx->name[0])
		return 0;
	if (!ir_match_local_with_optional_cast(addr_gidx->next, &value_last,
	                                       &value_offset, &value_size, &value_unsigned))
		return 0;
	store_inst = value_last ? value_last->next : NULL;
	zero_inst = store_inst ? store_inst->next : NULL;

	if (!store_inst || store_inst->kind != IR_STORE || store_inst->subop != IR_OP_MEMBER_PTR ||
	    !zero_inst || zero_inst->kind != IR_CONST || zero_inst->value != 0)
		return 0;
	if (!zero_inst->next || zero_inst->next->kind != IR_RETURN)
		return 0;

	store_size = store_inst->aux ? store_inst->aux : TCC_SIZEOF_INT;
	if (store_size != 1 && store_size != 2 && store_size != 4 && store_size != 8)
		return 0;
	if (value_size != store_size)
		return 0;

	scale = addr_gidx->aux ? addr_gidx->aux : 1;
	total_offset = inst->value * (long)scale + store_inst->value;
	if ((long)(int)total_offset != total_offset)
		return 0;
	(void)value_unsigned;

	cg->emit_load_func_addr(addr_gidx->name);
	if ((int)total_offset != 0) {
		if (!cg->emit_add_offset)
			return 0;
		cg->emit_add_offset((int)total_offset);
	}
	cg->emit_acc_to_saved();
	cg->emit_load_local_sized(value_offset, value_size);
	cg->emit_store_via_saved(store_size);
	cg->emit_load_imm(0);
	*inst_ptr = zero_inst;
	return ir_try_finish_value_from_acc(cg, inst_ptr, in_function,
	                                    current_func_name, function_just_ended,
	                                    debug_unit_active, current_debug_end_label,
	                                    current_function_exit_label,
	                                    skip_linear_until_label);
}

