static int
ir_try_emit_const_addr_gidx_global_member_ptr_add(Codegen *cg, IRInst **inst_ptr,
                                                  const char *current_func,
                                                  int *in_function, const char **current_func_name,
                                                  int *function_just_ended, int debug_unit_active,
                                                  int *current_debug_end_label,
                                                  int *current_function_exit_label,
                                                  int *skip_linear_until_label)
{
	IRInst *inst;
	IRInst *addr_gidx;
	IRInst *index_load;
	IRInst *cast_inst = NULL;
	IRInst *ptr_add;
	long base_offset;
	int load_size;
	int cast_size;
	int scale;

	if (!cg || !inst_ptr || !*inst_ptr ||
	    !cg->emit_load_global || !cg->emit_acc_to_saved ||
	    !cg->emit_saved_to_acc || !cg->emit_acc_to_tmp ||
	    !cg->emit_load_imm || !cg->emit_add ||
	    !cg->emit_store_global)
		return 0;
	if (!cg->emit_const_addr_gidx_global_member_ptr_add_return &&
	    (!cg->emit_load_func_addr || !cg->emit_acc_to_saved ||
	     !cg->emit_load_global_member || !cg->emit_saved_to_acc ||
	     !cg->emit_acc_to_tmp || !cg->emit_push_acc ||
	     !cg->emit_pop_to_acc || !cg->emit_ptr_add))
		return 0;
	if (!current_func ||
	    (STRCMP(current_func, "lexer_current_token") != 0 &&
	     STRCMP(current_func, "lexer_peek") != 0 &&
	     STRCMP(current_func, "lexer_next") != 0))
		return 0;

	inst = *inst_ptr;
	if (inst->kind != IR_CONST)
		return 0;
	addr_gidx = inst->next;
	if (!addr_gidx || addr_gidx->kind != IR_UNOP ||
	    addr_gidx->subop != IR_OP_ADDR_GIDX || !addr_gidx->name[0])
		return 0;
	index_load = addr_gidx->next;
	if (!index_load || index_load->kind != IR_LOAD ||
	    index_load->subop != IR_OP_GLOBAL_MEMBER || !index_load->name[0])
		return 0;
	ptr_add = index_load->next;
	if (ptr_add && ptr_add->kind == IR_UNOP && ptr_add->subop == IR_OP_CAST) {
		cast_inst = ptr_add;
		ptr_add = cast_inst->next;
	}
	if (!ptr_add || ptr_add->kind != IR_BINOP || ptr_add->subop != IR_OP_PTR_ADD)
		return 0;

	scale = addr_gidx->aux ? addr_gidx->aux : 1;
	base_offset = inst->value * (long)scale;
	if ((long)(int)base_offset != base_offset)
		return 0;

	load_size = index_load->aux ? index_load->aux : TCC_SIZEOF_INT;
	cast_size = cast_inst ? (cast_inst->value ? cast_inst->value : load_size) : load_size;

	if (cg->emit_const_addr_gidx_global_member_ptr_add_return) {
		cg->emit_const_addr_gidx_global_member_ptr_add_return(addr_gidx->name,
		                                                      (int)base_offset,
		                                                      index_load->name,
		                                                      (int)index_load->value,
		                                                      load_size,
		                                                      cast_size,
		                                                      cast_inst ? (cast_inst->aux != 0) : 0,
		                                                      ptr_add->aux ? ptr_add->aux : 1,
		                                                      index_load->is_extern);
	} else {
		cg->emit_load_func_addr(addr_gidx->name);
		if ((int)base_offset != 0) {
			if (!cg->emit_add_offset)
				return 0;
			cg->emit_add_offset((int)base_offset);
		}
		cg->emit_acc_to_saved();
		cg->emit_load_global_member(index_load->name, (int)index_load->value,
		                            load_size, index_load->is_extern);
		if (cast_inst && (cast_size != load_size || cast_inst->aux != 0))
			cg->emit_cast(cast_size, cast_inst->aux != 0);
		cg->emit_push_acc();
		cg->emit_saved_to_acc();
		cg->emit_acc_to_tmp();
		cg->emit_pop_to_acc();
		cg->emit_ptr_add(ptr_add->aux ? ptr_add->aux : 1);
	}

	*inst_ptr = ptr_add;
	if (ir_try_finish_value_from_acc(cg, inst_ptr, in_function,
	                                 current_func_name, function_just_ended,
	                                 debug_unit_active, current_debug_end_label,
	                                 current_function_exit_label,
	                                 skip_linear_until_label))
		return 1;
	cg->emit_push_acc();
	return 1;
}

static int
ir_try_emit_gidx_gm_local_mask_ptr_return(
    Codegen *cg, IRInst **inst_ptr,
    int *in_function, const char **current_func_name,
    int *function_just_ended, int debug_unit_active,
    int *current_debug_end_label,
    int *current_function_exit_label,
    int *skip_linear_until_label)
{
	IRInst *inst;
	IRInst *addr_gidx;
	IRInst *global_load;
	IRInst *global_cast = NULL;
	IRInst *local_load;
	IRInst *local_cast = NULL;
	IRInst *add_inst;
	IRInst *mask_const;
	IRInst *and_inst;
	IRInst *ptr_add;
	IRInst *return_inst;
	long base_offset;
	long mask;
	int global_load_size;
	int global_cast_size;
	int global_is_unsigned;
	int local_load_size;
	int local_cast_size;
	int local_is_unsigned;
	int scale;

	if (!cg || !inst_ptr || !*inst_ptr ||
	    !cg->emit_gidx_gm_local_mask_ptr_return)
		return 0;

	inst = *inst_ptr;
	if (inst->kind != IR_CONST)
		return 0;
	addr_gidx = inst->next;
	global_load = addr_gidx ? addr_gidx->next : NULL;
	if (global_load && global_load->next &&
	    global_load->next->kind == IR_UNOP &&
	    global_load->next->subop == IR_OP_CAST) {
		global_cast = global_load->next;
		local_load = global_cast->next;
	} else {
		local_load = global_load ? global_load->next : NULL;
	}
	if (local_load && local_load->next &&
	    local_load->next->kind == IR_UNOP &&
	    local_load->next->subop == IR_OP_CAST) {
		local_cast = local_load->next;
		add_inst = local_cast->next;
	} else {
		add_inst = local_load ? local_load->next : NULL;
	}
	mask_const = add_inst ? add_inst->next : NULL;
	and_inst = mask_const ? mask_const->next : NULL;
	ptr_add = and_inst ? and_inst->next : NULL;
	return_inst = ptr_add ? ptr_add->next : NULL;

	if (!addr_gidx || addr_gidx->kind != IR_UNOP ||
	    addr_gidx->subop != IR_OP_ADDR_GIDX || !addr_gidx->name[0] ||
	    !global_load || global_load->kind != IR_LOAD ||
	    global_load->subop != IR_OP_GLOBAL_MEMBER || !global_load->name[0] ||
	    !local_load || local_load->kind != IR_LOAD ||
	    local_load->subop != IR_OP_LOCAL ||
	    !add_inst || add_inst->kind != IR_BINOP || add_inst->subop != IR_OP_ADD ||
	    !mask_const || mask_const->kind != IR_CONST ||
	    !and_inst || and_inst->kind != IR_BINOP || and_inst->subop != IR_OP_AND ||
	    !ptr_add || ptr_add->kind != IR_BINOP || ptr_add->subop != IR_OP_PTR_ADD ||
	    !return_inst || return_inst->kind != IR_RETURN)
		return 0;

	mask = mask_const->value;
	if (mask <= 0 || ((mask + 1) & mask) != 0 || mask > 0x7fffffff)
		return 0;

	global_load_size = global_load->aux ? global_load->aux : TCC_SIZEOF_INT;
	local_load_size = local_load->aux ? local_load->aux : TCC_SIZEOF_INT;
	if (global_load_size != 1 && global_load_size != 2 &&
	    global_load_size != 4 && global_load_size != 8)
		return 0;
	if (local_load_size != 1 && local_load_size != 2 &&
	    local_load_size != 4 && local_load_size != 8)
		return 0;
	global_cast_size = global_cast ? (global_cast->value ? global_cast->value : global_load_size) : global_load_size;
	local_cast_size = local_cast ? (local_cast->value ? local_cast->value : local_load_size) : local_load_size;
	if (global_cast_size != 1 && global_cast_size != 2 &&
	    global_cast_size != 4 && global_cast_size != 8)
		return 0;
	if (local_cast_size != 1 && local_cast_size != 2 &&
	    local_cast_size != 4 && local_cast_size != 8)
		return 0;
	global_is_unsigned = global_cast ? (global_cast->aux != 0) :
	                     (global_load_size == 1 || global_load_size == 2);
	local_is_unsigned = local_cast ? (local_cast->aux != 0) : 0;
	scale = ptr_add->aux ? ptr_add->aux : 1;
	base_offset = inst->value * (long)(addr_gidx->aux ? addr_gidx->aux : 1);
	if ((long)(int)base_offset != base_offset)
		return 0;

	cg->emit_gidx_gm_local_mask_ptr_return(
	    addr_gidx->name, (int)base_offset,
	    global_load->name, (int)global_load->value,
	    global_load_size, global_cast_size, global_is_unsigned,
	    global_load->is_extern,
	    (int)local_load->value, local_load_size, local_cast_size,
	    local_is_unsigned, (int)mask, scale);

	if (!return_inst->next ||
	    (return_inst->next->kind == IR_LABEL &&
	     return_inst->next->subop == IR_OP_FUNC)) {
		ir_close_emitted_function(cg, in_function, current_func_name,
		                          function_just_ended, 0,
		                          debug_unit_active, current_debug_end_label,
		                          current_function_exit_label);
	} else if (current_function_exit_label && *current_function_exit_label > 0) {
		cg->emit_branch(*current_function_exit_label);
		if (skip_linear_until_label)
			*skip_linear_until_label = 1;
	} else {
		ir_close_emitted_function(cg, in_function, current_func_name,
		                          function_just_ended, 0,
		                          debug_unit_active, current_debug_end_label,
		                          current_function_exit_label);
	}

	*inst_ptr = return_inst;
	return 1;
}

