	token_base = (int)const_old->value * (addr_old->aux ? addr_old->aux : 1);
	token_scale = ptr_add0->aux ? ptr_add0->aux : 1;

	printf("    adrp x8, _%s@PAGE\n", load_head0->name);
	printf("    add x8, x8, _%s@PAGEOFF\n", load_head0->name);
	printf("    ldrsw x9, [x8, #%d]\n", head_off);
