	printf("    tbz w9, #31, L%d\n", (int)branch0->value);
	printf("    str wzr, [x8, #%d]\n", fill_off);
	cg->emit_label(branch0->value);
	printf("    ldr w8, [x8, #%d]\n", fill_off);
	printf("    cbnz w8, L%d\n", (int)branch1->value);
	printf("    bl _%s\n", call_fill->name);
	printf("    adrp x8, _%s@PAGE\n", load_head0->name);
	printf("    add x8, x8, _%s@PAGEOFF\n", load_head0->name);
