	base_offset1 = inst->value * (long)(addr1->aux ? addr1->aux : 1);
	base_offset2 = inst2->value * (long)(addr2->aux ? addr2->aux : 1);
	if ((long)(int)base_offset1 != base_offset1 || base_offset1 != base_offset2)
		return 0;

	cg->emit_accumulate_global_member_indexed_double_from_local_ptr(addr1->name,
	                                                                (int)base_offset1,
	                                                                ptr_add1->aux,
	                                                                (int)frame_load1->value,
	                                                                (int)frame_bucket1->value,
	                                                                (int)now_load->value,
	                                                                (int)frame_time_load->value);
