static int
ir_try_emit_store_local_ptr_indexed_member_direct(Codegen *cg, IRInst **inst_ptr)
{
	IRInst *addr_last;
	IRInst *value_inst;
	IRInst *value_last;
	IRInst *store_inst;
	int ptr_offset;
	int index_offset;
	int index_size;
	int index_unsigned;
	int index_add;
	int elem_size;
	int src_offset;
	int src_size;
	int src_unsigned;
	int member_offset;
	int store_size;

	if (!cg || !inst_ptr || !*inst_ptr)
		return 0;
	if (!ir_match_local_ptr_indexed_addr(*inst_ptr, &addr_last,
	                                     &ptr_offset, &index_offset,
	                                     &index_size, &index_unsigned,
	                                     &index_add, &elem_size))
		return 0;
	if (index_add != 0)
		return 0;

	value_inst = addr_last->next;
	if (value_inst && value_inst->kind == IR_CONST) {
		store_inst = value_inst->next;
		if (!store_inst || store_inst->kind != IR_STORE ||
		    store_inst->subop != IR_OP_MEMBER_PTR ||
		    !cg->emit_store_local_ptr_indexed_member_imm)
			return 0;
		member_offset = (int)store_inst->value;
		store_size = store_inst->aux ? store_inst->aux : TCC_SIZEOF_INT;
		cg->emit_store_local_ptr_indexed_member_imm(ptr_offset,
		                                            index_offset,
		                                            index_size,
		                                            index_unsigned,
		                                            index_add,
		                                            elem_size,
		                                            member_offset,
		                                            store_size,
		                                            value_inst->value);
		*inst_ptr = store_inst;
		return 1;
	}

	if (!ir_match_local_with_optional_cast(value_inst, &value_last,
	                                       &src_offset, &src_size,
	                                       &src_unsigned))
		return 0;
	store_inst = value_last->next;
	if (!store_inst || store_inst->kind != IR_STORE ||
	    store_inst->subop != IR_OP_MEMBER_PTR ||
	    !cg->emit_store_local_ptr_indexed_member_from_local)
		return 0;

	member_offset = (int)store_inst->value;
	store_size = store_inst->aux ? store_inst->aux : TCC_SIZEOF_INT;
	cg->emit_store_local_ptr_indexed_member_from_local(ptr_offset,
	                                                   index_offset,
	                                                   index_size,
	                                                   index_unsigned,
	                                                   index_add,
	                                                   elem_size,
	                                                   member_offset,
	                                                   store_size,
	                                                   src_offset,
	                                                   src_size,
	                                                   src_unsigned);
	*inst_ptr = store_inst;
	return 1;
}

static int
ir_try_emit_zero_local_range(Codegen *cg, IRInst **inst_ptr)
{
	IRInst *inst;
	IRInst *cursor;
	IRInst *last_store;
	int start_offset;
	int size = 0;
	int expected_offset;

	if (!cg || !inst_ptr || !*inst_ptr || !cg->emit_zero_local_range)
		return 0;

	inst = *inst_ptr;
	if (inst->kind != IR_CONST || inst->value != 0)
		return 0;
	if (!inst->next || inst->next->kind != IR_STORE ||
	    inst->next->subop != IR_OP_LOCAL || inst->next->aux != 1)
		return 0;

	start_offset = (int)inst->next->value;
	expected_offset = start_offset;
	cursor = inst;
	last_store = NULL;
	while (cursor &&
	       cursor->kind == IR_CONST && cursor->value == 0 &&
	       cursor->next &&
	       cursor->next->kind == IR_STORE &&
	       cursor->next->subop == IR_OP_LOCAL &&
	       cursor->next->aux == 1 &&
	       cursor->next->value == expected_offset) {
		last_store = cursor->next;
		size++;
		expected_offset++;
		cursor = last_store->next;
	}

	if (size < 8)
		return 0;

	cg->emit_zero_local_range(start_offset, size);
	*inst_ptr = last_store;
	return 1;
}

