static int
ir_try_emit_arm64_repeated_local_member_indirect_call(Codegen *cg, IRInst **inst_ptr,
                                                      int *in_function, const char **current_func_name,
                                                      int *function_just_ended, int debug_unit_active,
                                                      int *current_debug_end_label,
                                                      int *current_function_exit_label,
                                                      int *skip_linear_until_label)
{
	IRInst *cursor;
	IRInst *call_inst;
	IRInst *base0_inst;
	IRInst *member0_inst;
	IRInst *member0_cast = NULL;
	IRInst *base1_inst;
	IRInst *member1_inst;
	IRInst *member1_cast = NULL;
	IRInst *slot_inst;
	struct {
		int is_const;
		long imm;
		int local_offset;
		int size;
	} args[2];
	int argc, arg_index;
	int member0_size, member1_size, slot_size;

	if (!cg || cg != &arm64_codegen ||
	    !cg->emit_load_local_ptr_member || !cg->emit_acc_to_tmp ||
	    !cg->emit_tmp_to_acc || !cg->emit_load_member_ptr ||
	    !cg->emit_acc_to_saved || !cg->emit_acc_to_arg ||
	    !cg->emit_load_local_to_arg || !cg->emit_load_imm_to_arg ||
	    !inst_ptr || !*inst_ptr)
		return 0;

	for (argc = 2; argc <= 3; argc++) {
		cursor = *inst_ptr;
		for (arg_index = argc - 1; arg_index >= 1; arg_index--) {
			IRInst *inst = cursor;
			IRInst *cast_inst = NULL;
			int size;

			if (!inst)
				goto next_argc;
			if (inst->kind == IR_LOAD && inst->subop == IR_OP_LOCAL &&
			    inst->next && inst->next->kind == IR_UNOP &&
			    inst->next->subop == IR_OP_CAST) {
				cast_inst = inst->next;
			}

			if (inst->kind == IR_CONST) {
				args[arg_index - 1].is_const = 1;
				args[arg_index - 1].imm = inst->value;
				args[arg_index - 1].local_offset = 0;
				args[arg_index - 1].size = 0;
				cursor = inst->next;
				continue;
			}

			if (inst->kind != IR_LOAD || inst->subop != IR_OP_LOCAL)
				goto next_argc;

			size = inst->aux ? inst->aux : TCC_SIZEOF_INT;
			if (cast_inst) {
				if (cast_inst->value != 1 && cast_inst->value != 2 &&
				    cast_inst->value != 4 && cast_inst->value != TCC_SIZEOF_PTR)
					goto next_argc;
				size = cast_inst->value;
			}
			if (size != 1 && size != 2 && size != 4 && size != TCC_SIZEOF_PTR)
				goto next_argc;

			args[arg_index - 1].is_const = 0;
			args[arg_index - 1].imm = 0;
			args[arg_index - 1].local_offset = (int)inst->value;
			args[arg_index - 1].size = size;
			cursor = cast_inst ? cast_inst->next : inst->next;
		}

		base0_inst = cursor;
		member0_inst = base0_inst ? base0_inst->next : NULL;
		if (member0_inst &&
		    member0_inst->next &&
		    member0_inst->next->kind == IR_UNOP &&
		    member0_inst->next->subop == IR_OP_CAST) {
			member0_cast = member0_inst->next;
		}
		base1_inst = member0_cast ? member0_cast->next : (member0_inst ? member0_inst->next : NULL);
		member1_inst = base1_inst ? base1_inst->next : NULL;
		if (member1_inst &&
		    member1_inst->next &&
		    member1_inst->next->kind == IR_UNOP &&
		    member1_inst->next->subop == IR_OP_CAST) {
			member1_cast = member1_inst->next;
		}
		slot_inst = member1_cast ? member1_cast->next : (member1_inst ? member1_inst->next : NULL);
		call_inst = slot_inst ? slot_inst->next : NULL;

		if (!base0_inst || base0_inst->kind != IR_LOAD || base0_inst->subop != IR_OP_LOCAL ||
		    (base0_inst->aux ? base0_inst->aux : TCC_SIZEOF_INT) != TCC_SIZEOF_PTR ||
		    !member0_inst || member0_inst->kind != IR_UNOP || member0_inst->subop != IR_OP_MEMBER_PTR ||
		    !base1_inst || base1_inst->kind != IR_LOAD || base1_inst->subop != IR_OP_LOCAL ||
		    base1_inst->value != base0_inst->value ||
		    (base1_inst->aux ? base1_inst->aux : TCC_SIZEOF_INT) != TCC_SIZEOF_PTR ||
		    !member1_inst || member1_inst->kind != IR_UNOP || member1_inst->subop != IR_OP_MEMBER_PTR ||
		    member1_inst->value != member0_inst->value ||
		    !slot_inst || slot_inst->kind != IR_UNOP || slot_inst->subop != IR_OP_MEMBER_PTR ||
		    !call_inst || call_inst->kind != IR_CALL_INDIRECT || call_inst->value != argc ||
		    call_inst->fp_arg_mask != 0)
			goto next_argc;

		member0_size = member0_inst->aux ? member0_inst->aux : TCC_SIZEOF_INT;
		member1_size = member1_inst->aux ? member1_inst->aux : TCC_SIZEOF_INT;
		slot_size = slot_inst->aux ? slot_inst->aux : TCC_SIZEOF_INT;
		if (member0_size != TCC_SIZEOF_PTR || member1_size != TCC_SIZEOF_PTR ||
		    slot_size != TCC_SIZEOF_PTR)
			goto next_argc;

		if (member0_cast &&
		    ((member0_cast->value ? member0_cast->value : member0_size) != TCC_SIZEOF_PTR ||
		     member0_cast->aux == 0))
			goto next_argc;
		if (member1_cast &&
		    ((member1_cast->value ? member1_cast->value : member1_size) != TCC_SIZEOF_PTR ||
		     member1_cast->aux == 0))
			goto next_argc;

		cg->emit_load_local_ptr_member((int)base0_inst->value, (int)member0_inst->value, member0_size);
		cg->emit_acc_to_tmp();
		cg->emit_load_member_ptr((int)slot_inst->value, slot_size);
		cg->emit_acc_to_saved();
		cg->emit_tmp_to_acc();
		cg->emit_acc_to_arg(0);
		for (arg_index = 1; arg_index < argc; arg_index++) {
			if (args[arg_index - 1].is_const)
				cg->emit_load_imm_to_arg(arg_index, args[arg_index - 1].imm);
			else
				cg->emit_load_local_to_arg(arg_index,
				                           args[arg_index - 1].local_offset,
				                           args[arg_index - 1].size);
		}
		cg->emit_call_saved();
		cg->emit_cleanup_call_args(argc, -1);
		*inst_ptr = call_inst;
		ir_finish_emitted_call_result(cg, inst_ptr, in_function,
		                              current_func_name, function_just_ended,
		                              debug_unit_active, current_debug_end_label,
		                              current_function_exit_label,
		                              skip_linear_until_label);
		return 1;

next_argc:
		member0_cast = NULL;
		member1_cast = NULL;
		continue;
	}

	return 0;
}

static int
ir_try_emit_arm64_const_pair_call(Codegen *cg, IRInst **inst_ptr,
                                  int *in_function, const char **current_func_name,
                                  int *function_just_ended, int debug_unit_active,
                                  int *current_debug_end_label,
                                  int *current_function_exit_label,
                                  int *skip_linear_until_label)
{
	IRInst *inst;
	IRInst *inst_cast = NULL;
	IRInst *arg0;
	IRInst *call_inst;

	if (!cg || cg != &arm64_codegen ||
	    !cg->emit_load_imm_to_arg || !cg->emit_load_local_to_arg ||
	    !inst_ptr || !*inst_ptr)
		return 0;

	inst = *inst_ptr;
	arg0 = inst->next;
	if (arg0 && arg0->kind == IR_UNOP && arg0->subop == IR_OP_CAST) {
		inst_cast = arg0;
		arg0 = inst_cast->next;
	}
	call_inst = arg0 ? arg0->next : NULL;
	if (inst->kind != IR_CONST || !arg0 || !call_inst ||
	    call_inst->kind != IR_CALL || call_inst->value != 2 ||
	    call_inst->fp_arg_mask != 0)
		return 0;
	if (call_inst->fixed_params >= 0 && call_inst->value > call_inst->fixed_params)
		return 0;
	if (inst_cast &&
	    ((inst_cast->value ? inst_cast->value : TCC_SIZEOF_INT) != 4 ||
	     inst_cast->aux == 0))
		return 0;

	if (arg0->kind == IR_CONST) {
		cg->emit_load_imm_to_arg(1, inst->value);
		cg->emit_load_imm_to_arg(0, arg0->value);
	} else if (arg0->kind == IR_LOAD && arg0->subop == IR_OP_LOCAL) {
		cg->emit_load_imm_to_arg(1, inst->value);
		cg->emit_load_local_to_arg(0, arg0->value,
		                           arg0->aux ? arg0->aux : TCC_SIZEOF_INT);
	} else {
		return 0;
	}

	cg->emit_call(call_inst->name);
	cg->emit_cleanup_call_args(2, call_inst->fixed_params);
	*inst_ptr = call_inst;
	ir_finish_emitted_call_result(cg, inst_ptr, in_function,
	                              current_func_name, function_just_ended,
	                              debug_unit_active, current_debug_end_label,
	                              current_function_exit_label,
	                              skip_linear_until_label);
	return 1;
}

static int
ir_try_emit_arm64_const_const_binop_local_pair_call(Codegen *cg, IRInst **inst_ptr,
                                                    int *in_function, const char **current_func_name,
                                                    int *function_just_ended, int debug_unit_active,
                                                    int *current_debug_end_label,
                                                    int *current_function_exit_label,
                                                    int *skip_linear_until_label)
{
	IRInst *lhs_inst;
	IRInst *rhs_inst;
	IRInst *binop_inst;
	IRInst *arg0_inst;
	IRInst *cast_inst = NULL;
	IRInst *call_inst;
	long imm;
	int arg0_size;

	if (!cg || cg != &arm64_codegen ||
	    !cg->emit_load_imm_to_arg || !cg->emit_load_local_to_arg ||
	    !inst_ptr || !*inst_ptr)
		return 0;

	lhs_inst = *inst_ptr;
	rhs_inst = lhs_inst->next;
	binop_inst = rhs_inst ? rhs_inst->next : NULL;
	arg0_inst = binop_inst ? binop_inst->next : NULL;
	if (arg0_inst &&
	    arg0_inst->kind == IR_UNOP &&
	    arg0_inst->subop == IR_OP_CAST) {
		cast_inst = arg0_inst;
		arg0_inst = cast_inst->next;
	}
	call_inst = arg0_inst ? arg0_inst->next : NULL;

	if (!lhs_inst || lhs_inst->kind != IR_CONST ||
	    !rhs_inst || rhs_inst->kind != IR_CONST ||
	    !binop_inst || binop_inst->kind != IR_BINOP ||
	    !arg0_inst || arg0_inst->kind != IR_LOAD || arg0_inst->subop != IR_OP_LOCAL ||
	    !call_inst || call_inst->kind != IR_CALL || call_inst->value != 2 ||
	    call_inst->fp_arg_mask != 0 || call_inst->fixed_params >= 0)
		return 0;

	switch ((IRSubOp)binop_inst->subop) {
	case IR_OP_OR:
		imm = lhs_inst->value | rhs_inst->value;
		break;
	case IR_OP_AND:
		imm = lhs_inst->value & rhs_inst->value;
		break;
	case IR_OP_XOR:
		imm = lhs_inst->value ^ rhs_inst->value;
		break;
	case IR_OP_ADD:
		imm = lhs_inst->value + rhs_inst->value;
		break;
	case IR_OP_SUB:
		imm = lhs_inst->value - rhs_inst->value;
		break;
	default:
		return 0;
	}

	arg0_size = arg0_inst->aux ? arg0_inst->aux : TCC_SIZEOF_INT;
	if (cast_inst) {
		if (cast_inst->value != 1 && cast_inst->value != 2 &&
		    cast_inst->value != 4 && cast_inst->value != TCC_SIZEOF_PTR)
			return 0;
		arg0_size = cast_inst->value;
	}
	if (arg0_size != 1 && arg0_size != 2 &&
	    arg0_size != 4 && arg0_size != TCC_SIZEOF_PTR)
		return 0;

	cg->emit_load_local_to_arg(0, arg0_inst->value, arg0_size);
	cg->emit_load_imm_to_arg(1, imm);
	cg->emit_call(call_inst->name);
	cg->emit_cleanup_call_args(2, call_inst->fixed_params);
	*inst_ptr = call_inst;
	ir_finish_emitted_call_result(cg, inst_ptr, in_function,
	                              current_func_name, function_just_ended,
	                              debug_unit_active, current_debug_end_label,
	                              current_function_exit_label,
	                              skip_linear_until_label);
	return 1;
}

static int
ir_match_gidx_local_scaled_addr(IRInst *inst, IRInst **last_out,
                                const char **name_out, int *base_offset_out,
                                int *elem_size_out, int *index_offset_out,
                                int *index_size_out, int *index_unsigned_out,
                                int *is_extern_out)
{
	IRInst *idx_last = NULL;
	IRInst *scale_inst;
	IRInst *mul_inst;
	IRInst *offset_inst = NULL;
	IRInst *add_inst = NULL;
	IRInst *addr_gidx;
	int index_offset = 0;
	int index_size = 0;
	int index_unsigned = 0;
	int base_offset = 0;

	if (!ir_match_local_with_optional_cast(inst, &idx_last,
	                                       &index_offset, &index_size, &index_unsigned))
		return 0;

	scale_inst = idx_last->next;
	mul_inst = scale_inst ? scale_inst->next : NULL;
	if (!scale_inst || scale_inst->kind != IR_CONST ||
	    !mul_inst || mul_inst->kind != IR_BINOP || mul_inst->subop != IR_OP_MUL)
		return 0;

	addr_gidx = mul_inst->next;
	if (addr_gidx && addr_gidx->kind == IR_CONST &&
	    addr_gidx->next && addr_gidx->next->kind == IR_BINOP &&
	    (addr_gidx->next->subop == IR_OP_ADD || addr_gidx->next->subop == IR_OP_SUB)) {
		offset_inst = addr_gidx;
		add_inst = addr_gidx->next;
		base_offset = (int)offset_inst->value;
		if (add_inst->subop == IR_OP_SUB)
			base_offset = -base_offset;
		addr_gidx = add_inst->next;
	}

	if (!addr_gidx || addr_gidx->kind != IR_UNOP ||
	    addr_gidx->subop != IR_OP_ADDR_GIDX || !addr_gidx->name[0])
		return 0;

	if (last_out)
		*last_out = addr_gidx;
	if (name_out)
		*name_out = addr_gidx->name;
	if (base_offset_out)
		*base_offset_out = base_offset;
	if (elem_size_out)
		*elem_size_out = (int)scale_inst->value;
	if (index_offset_out)
		*index_offset_out = index_offset;
	if (index_size_out)
		*index_size_out = index_size;
	if (index_unsigned_out)
		*index_unsigned_out = index_unsigned;
	if (is_extern_out)
		*is_extern_out = addr_gidx->is_extern;
	return 1;
}

static int
ir_try_emit_arm64_gidx_str_imm_str_quad_call(Codegen *cg, IRInst **inst_ptr,
                                             int *in_function,
                                             const char **current_func_name,
                                             int *function_just_ended,
                                             int debug_unit_active,
                                             int *current_debug_end_label,
                                             int *current_function_exit_label,
                                             int *skip_linear_until_label)
{
	IRInst *arg3_inst;
	IRInst *arg2_inst;
	IRInst *arg1_inst;
	IRInst *addr_last = NULL;
	IRInst *member_inst;
	IRInst *call_inst;
	const char *name = NULL;
	int base_offset = 0;
	int elem_size = 0;
	int idx_offset = 0;
	int idx_size = 0;
	int idx_unsigned = 0;
	int is_extern = 0;
	int load_size;

	if (!cg || cg != &arm64_codegen ||
	    !cg->emit_load_string || !cg->emit_acc_to_arg ||
	    !cg->emit_load_imm_to_arg || !cg->emit_load_global_member_indexed ||
	    !cg->emit_acc_to_saved || !cg->emit_saved_to_acc ||
	    !inst_ptr || !*inst_ptr)
		return 0;

	arg3_inst = *inst_ptr;
	arg2_inst = arg3_inst->next;
	arg1_inst = arg2_inst ? arg2_inst->next : NULL;

	if (!arg3_inst || arg3_inst->kind != IR_LOAD ||
	    (arg3_inst->subop != IR_OP_STRING && arg3_inst->subop != IR_OP_STRING_ACC) ||
	    !arg2_inst || arg2_inst->kind != IR_CONST ||
	    !arg1_inst || arg1_inst->kind != IR_LOAD ||
	    (arg1_inst->subop != IR_OP_STRING && arg1_inst->subop != IR_OP_STRING_ACC))
		return 0;

	if (!ir_match_gidx_local_scaled_addr(arg1_inst->next, &addr_last,
	                                     &name, &base_offset, &elem_size,
	                                     &idx_offset, &idx_size, &idx_unsigned,
	                                     &is_extern))
		return 0;

	member_inst = addr_last->next;
	call_inst = member_inst ? member_inst->next : NULL;
	if (!member_inst || member_inst->kind != IR_UNOP || member_inst->subop != IR_OP_MEMBER_PTR ||
	    !call_inst || call_inst->kind != IR_CALL || call_inst->value != 4 ||
	    call_inst->fp_arg_mask != 0)
		return 0;
	if (STRCMP(call_inst->name, "xfree_impl") != 0)
		return 0;

	load_size = member_inst->aux ? member_inst->aux : TCC_SIZEOF_INT;
	if (load_size != TCC_SIZEOF_PTR)
		return 0;

	cg->emit_load_global_member_indexed(name, base_offset, elem_size,
	                                    (int)member_inst->value,
	                                    load_size, load_size, 0,
	                                    idx_offset, idx_size, idx_unsigned,
	                                    is_extern, 0);
	cg->emit_acc_to_saved();
	cg->emit_load_string(arg1_inst->value);
	cg->emit_acc_to_arg(1);
	cg->emit_load_imm_to_arg(2, arg2_inst->value);
	cg->emit_load_string(arg3_inst->value);
	cg->emit_acc_to_arg(3);
	cg->emit_saved_to_acc();
	cg->emit_call(call_inst->name);
	cg->emit_cleanup_call_args(4, call_inst->fixed_params);
	*inst_ptr = call_inst;
	ir_finish_emitted_call_result(cg, inst_ptr, in_function,
	                              current_func_name, function_just_ended,
	                              debug_unit_active, current_debug_end_label,
	                              current_function_exit_label,
	                              skip_linear_until_label);
	return 1;
}

