static int
ir_try_emit_arm64_lmidx_str_imm_str_quad(Codegen *cg, IRInst **inst_ptr,
                                         int *in_function,
                                         const char **current_func_name,
                                         int *function_just_ended,
                                         int debug_unit_active,
                                         int *current_debug_end_label,
                                         int *current_function_exit_label,
                                         int *skip_linear_until_label)
{
	IRInst *arg3_inst;
	IRInst *arg2_inst;
	IRInst *arg1_inst;
	IRInst *base_inst;
	IRInst *array_member_inst;
	IRInst *index_inst;
	IRInst *cast_inst = NULL;
	IRInst *ptr_add_inst;
	IRInst *value_member_inst;
	IRInst *call_inst;
	int array_member_size;
	int index_size;
	int index_unsigned;
	int value_member_size;

	if (!cg || cg != &arm64_codegen ||
	    !cg->emit_load_string || !cg->emit_acc_to_arg ||
	    !cg->emit_load_imm_to_arg || !cg->emit_load_local_casted ||
	    !cg->emit_call || !cg->emit_cleanup_call_args ||
	    !inst_ptr || !*inst_ptr)
		return 0;

	arg3_inst = *inst_ptr;
	arg2_inst = arg3_inst ? arg3_inst->next : NULL;
	arg1_inst = arg2_inst ? arg2_inst->next : NULL;
	base_inst = arg1_inst ? arg1_inst->next : NULL;
	array_member_inst = base_inst ? base_inst->next : NULL;
	index_inst = array_member_inst ? array_member_inst->next : NULL;
	cast_inst = (index_inst && index_inst->next &&
	             index_inst->next->kind == IR_UNOP &&
	             index_inst->next->subop == IR_OP_CAST)
		? index_inst->next
		: NULL;
	ptr_add_inst = cast_inst ? cast_inst->next : (index_inst ? index_inst->next : NULL);
	value_member_inst = ptr_add_inst ? ptr_add_inst->next : NULL;
	call_inst = value_member_inst ? value_member_inst->next : NULL;

	if (!arg3_inst || arg3_inst->kind != IR_LOAD ||
	    (arg3_inst->subop != IR_OP_STRING && arg3_inst->subop != IR_OP_STRING_ACC) ||
	    !arg2_inst || arg2_inst->kind != IR_CONST ||
	    !arg1_inst || arg1_inst->kind != IR_LOAD ||
	    (arg1_inst->subop != IR_OP_STRING && arg1_inst->subop != IR_OP_STRING_ACC) ||
	    !base_inst || base_inst->kind != IR_LOAD || base_inst->subop != IR_OP_LOCAL ||
	    (base_inst->aux ? base_inst->aux : TCC_SIZEOF_INT) != TCC_SIZEOF_PTR ||
	    !array_member_inst || array_member_inst->kind != IR_UNOP ||
	    array_member_inst->subop != IR_OP_MEMBER_PTR ||
	    !index_inst || index_inst->kind != IR_LOAD || index_inst->subop != IR_OP_LOCAL ||
	    !ptr_add_inst || ptr_add_inst->kind != IR_BINOP || ptr_add_inst->subop != IR_OP_PTR_ADD ||
	    !value_member_inst || value_member_inst->kind != IR_UNOP ||
	    value_member_inst->subop != IR_OP_MEMBER_PTR ||
	    !call_inst || call_inst->kind != IR_CALL || call_inst->value != 4 ||
	    call_inst->fp_arg_mask != 0)
		return 0;
	if (STRCMP(call_inst->name, "xfree_impl") != 0)
		return 0;

	array_member_size = array_member_inst->aux ? array_member_inst->aux : TCC_SIZEOF_INT;
	value_member_size = value_member_inst->aux ? value_member_inst->aux : TCC_SIZEOF_INT;
	if (array_member_size != TCC_SIZEOF_PTR || value_member_size != TCC_SIZEOF_PTR)
		return 0;

	index_size = index_inst->aux ? index_inst->aux : TCC_SIZEOF_INT;
	index_unsigned = 0;
	if (cast_inst) {
		if (cast_inst->value != 1 && cast_inst->value != 2 &&
		    cast_inst->value != 4 && cast_inst->value != TCC_SIZEOF_PTR)
			return 0;
		index_size = cast_inst->value;
		index_unsigned = cast_inst->aux != 0;
	}
	if (index_size != 1 && index_size != 2 &&
	    index_size != 4 && index_size != TCC_SIZEOF_PTR)
		return 0;

	cg->emit_load_string(arg1_inst->value);
	cg->emit_acc_to_arg(1);
	cg->emit_load_imm_to_arg(2, arg2_inst->value);
	cg->emit_load_string(arg3_inst->value);
	cg->emit_acc_to_arg(3);

	printf("    ldur x1, [x29, #%d]\n", (int)base_inst->value);
	if ((int)array_member_inst->value)
		printf("    ldr x1, [x1, #%d]\n", (int)array_member_inst->value);
	else
		printf("    ldr x1, [x1]\n");
	cg->emit_load_local_casted((int)index_inst->value, index_size, index_unsigned);
	if (ptr_add_inst->aux && ptr_add_inst->aux != 1) {
		printf("    mov x10, #%d\n", ptr_add_inst->aux);
		printf("    madd x1, x0, x10, x1\n");
	} else {
		printf("    add x1, x1, x0\n");
	}
	if ((int)value_member_inst->value)
		printf("    ldr x0, [x1, #%d]\n", (int)value_member_inst->value);
	else
		printf("    ldr x0, [x1]\n");
	cg->emit_call(call_inst->name);
	cg->emit_cleanup_call_args(4, call_inst->fixed_params);
	*inst_ptr = call_inst;
	ir_finish_emitted_call_result(cg, inst_ptr, in_function,
	                              current_func_name, function_just_ended,
	                              debug_unit_active, current_debug_end_label,
	                              current_function_exit_label,
	                              skip_linear_until_label);
	return 1;
}

