	printf("    mov x2, #%ld\n", const_line0->value);
	cg->emit_load_string(load_file_str0->value);
	printf("    mov x1, x0\n");
	printf("    ldur x11, [x29, #%d]\n", inst_offset);
	printf("    add x11, x11, #%d\n", base_offset);
	printf("    ldursw x12, [x29, #%d]\n", i_offset);
	printf("    add x11, x11, x12, lsl #5\n");
	printf("    ldr x0, [x11, #%d]\n", member_name_offset);
	cg->emit_call(call_xfree0->name);
	cg->emit_cleanup_call_args(4, call_xfree0->fixed_params);

	printf("    ldur x11, [x29, #%d]\n", inst_offset);
	printf("    add x11, x11, #%d\n", base_offset);
	printf("    ldursw x12, [x29, #%d]\n", i_offset);
	printf("    add x11, x11, x12, lsl #5\n");
	printf("    str xzr, [x11, #0]\n");
	printf("    str xzr, [x11, #%d]\n", value_offset);
	printf("    str wzr, [x11, #%d]\n", aux_offset);
	printf("    str wzr, [x11, #%d]\n", aux2_offset);
	printf("    str xzr, [x11, #%d]\n", member_name_offset);
	printf("    ldur w8, [x29, #%d]\n", i_offset);
	printf("    add w8, w8, #1\n");
	printf("    stur w8, [x29, #%d]\n", i_offset);
	printf("    b L%d\n", label_loop);

	cg->emit_label(label_done);
	printf("    ldur x0, [x29, #%d]\n", inst_offset);
	printf("    strb wzr, [x0, #%d]\n", count_offset);
