static int
ir_match_local_global_addr_cmp_return(IRInst *inst, IRInst **last_out,
                                      int *local_offset_out,
                                      const char **name_out,
                                      int *is_extern_out,
                                      const char **op_out)
{
	IRInst *addr_inst;
	IRInst *cmp_inst;
	IRInst *ret_inst;

	if (!inst || inst->kind != IR_LOAD || inst->subop != IR_OP_LOCAL)
		return 0;
	if ((inst->aux ? inst->aux : TCC_SIZEOF_INT) != TCC_SIZEOF_PTR)
		return 0;

	addr_inst = inst->next;
	cmp_inst = addr_inst ? addr_inst->next : NULL;
	ret_inst = cmp_inst ? cmp_inst->next : NULL;

	if (!addr_inst || addr_inst->kind != IR_LOAD || addr_inst->subop != IR_OP_ADDR_GLOBAL ||
	    !cmp_inst || cmp_inst->kind != IR_BINOP ||
	    (cmp_inst->subop != IR_OP_EQ && cmp_inst->subop != IR_OP_NE) ||
	    !ret_inst || ret_inst->kind != IR_RETURN)
		return 0;

	if (local_offset_out)
		*local_offset_out = (int)inst->value;
	if (name_out)
		*name_out = addr_inst->name;
	if (is_extern_out)
		*is_extern_out = addr_inst->is_extern;
	if (op_out)
		*op_out = cmp_inst->op;
	if (last_out)
		*last_out = cmp_inst;
	return 1;
}

static int
ir_match_local_ptr_offset_store_imm(IRInst *inst, IRInst **last_out,
                                    int *ptr_local_offset_out,
                                    int *member_offset_out,
                                    int *store_size_out,
                                    long *imm_out)
{
	IRInst *cursor;
	IRInst *const_inst;
	IRInst *store_inst;
	int member_offset = 0;

	if (!inst || inst->kind != IR_LOAD || inst->subop != IR_OP_LOCAL)
		return 0;
	if ((inst->aux ? inst->aux : TCC_SIZEOF_INT) != TCC_SIZEOF_PTR)
		return 0;

	cursor = inst->next;
	while (cursor && cursor->kind == IR_UNOP && cursor->subop == IR_OP_ADD_OFFSET) {
		member_offset += (int)cursor->value;
		cursor = cursor->next;
	}
	const_inst = cursor;
	store_inst = const_inst ? const_inst->next : NULL;

	if (!const_inst || const_inst->kind != IR_CONST ||
	    !store_inst || store_inst->kind != IR_STORE ||
	    store_inst->subop != IR_OP_MEMBER_PTR)
		return 0;

	member_offset += (int)store_inst->value;
	if (ptr_local_offset_out)
		*ptr_local_offset_out = (int)inst->value;
	if (member_offset_out)
		*member_offset_out = member_offset;
	if (store_size_out)
		*store_size_out = store_inst->aux ? store_inst->aux : TCC_SIZEOF_INT;
	if (imm_out)
		*imm_out = const_inst->value;
	if (last_out)
		*last_out = store_inst;
	return 1;
}

