static int
ir_try_emit_arm64_global_local_cmp_return(Codegen *cg, IRInst **inst_ptr,
                                          int *in_function, const char **current_func_name,
                                          int *function_just_ended, int debug_unit_active,
                                          int *current_debug_end_label,
                                          int *current_function_exit_label,
                                          int *skip_linear_until_label)
{
	IRInst *tail = NULL;
	const char *name = NULL;
	int is_extern = 0;
	int global_size = 0;
	int local_offset = 0;
	int local_size = 0;
	int global_cast_size = 0;
	int global_is_unsigned = 0;
	int local_cast_size = 0;
	int local_is_unsigned = 0;
	const char *cmp_op = NULL;
	int cmp_size = 0;

	if (!cg || cg != &arm64_codegen || !cg->emit_load_global ||
	    !cg->emit_load_local_sized || !cg->emit_acc_to_tmp ||
	    !inst_ptr || !*inst_ptr)
		return 0;

	if (!ir_match_global_local_cmp_return(*inst_ptr, &tail,
	                                      &name, &is_extern,
	                                      &global_size, &local_offset,
	                                      &local_size, &global_cast_size,
	                                      &global_is_unsigned,
	                                      &local_cast_size,
	                                      &local_is_unsigned,
	                                      &cmp_op, &cmp_size))
		return 0;

	if (is_extern) {
		if (!cg->emit_load_global_extern)
			return 0;
		cg->emit_load_global_extern(name);
	} else {
		cg->emit_load_global(name, global_size);
	}
	if (global_cast_size != global_size || global_is_unsigned)
		cg->emit_cast(global_cast_size, global_is_unsigned);
	cg->emit_acc_to_tmp();
	cg->emit_load_local_sized(local_offset, local_size);
	if (local_cast_size != local_size || local_is_unsigned)
		cg->emit_cast(local_cast_size, local_is_unsigned);
	ir_emit_binop(cg, cmp_op, cmp_size);
	*inst_ptr = tail;
	return ir_try_finish_value_from_acc(cg, inst_ptr, in_function,
	                                    current_func_name, function_just_ended,
	                                    debug_unit_active, current_debug_end_label,
	                                    current_function_exit_label,
	                                    skip_linear_until_label);
}

