static int
ir_try_emit_arm64_local_ptr_bool_store_return_void(Codegen *cg, IRInst **inst_ptr,
                                                   int *in_function, const char **current_func_name,
                                                   int *function_just_ended, int debug_unit_active,
                                                   int *current_debug_end_label,
                                                   int *current_function_exit_label,
                                                   int *skip_linear_until_label)
{
	IRInst *tail = NULL;
	int ptr_local_offset = 0;
	int member_offset = 0;
	int bool_local_offset = 0;
	int bool_load_size = 0;
	int done_label;

	(void)in_function;
	(void)current_func_name;
	(void)function_just_ended;
	(void)debug_unit_active;
	(void)current_debug_end_label;
	(void)current_function_exit_label;
	(void)skip_linear_until_label;

	if (!cg || cg != &arm64_codegen || !inst_ptr || !*inst_ptr ||
	    !cg->emit_load_local_sized || !cg->emit_label)
		return 0;

	if (!ir_match_local_ptr_bool_store_return_void(*inst_ptr, &tail,
	                                               &ptr_local_offset,
	                                               &member_offset,
	                                               &bool_local_offset,
	                                               &bool_load_size))
		return 0;

	done_label = new_ir_label();
	cg->emit_load_local_sized(ptr_local_offset, TCC_SIZEOF_PTR);
	printf("    cbz x0, L%d\n", done_label);
	printf("    mov x1, x0\n");
	cg->emit_load_local_sized(bool_local_offset, bool_load_size);
	if (bool_load_size == TCC_SIZEOF_PTR)
		printf("    cmp x0, #0\n");
	else
		printf("    cmp w0, #0\n");
	printf("    cset w0, ne\n");
	printf("    strb w0, [x1, #%d]\n", member_offset);
	cg->emit_label(done_label);
	*inst_ptr = tail;
	return 1;
}

